import spidev
import time
import sqlite3
import datetime
import sys

SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 50000
TEMP_THRESHOLD = 100.0
DB_FILE = 'wildlife_temp_data.db'

spi = None
conn = None
running = True


def init_spi():
    global spi
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
    except Exception as e:
        print(f"Error initializing SPI: {e}", file=sys.stderr)
        spi = None
        return False
    return True


def init_database():
    global conn
    try:
        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS temperature_alerts (
                record_time TEXT,
                temp_reading REAL
            )
        ''')
        conn.commit()
    except sqlite3.Error as e:
        print(f"Error initializing database: {e}", file=sys.stderr)
        conn = None
        return False
    return True


def read_temperature():
    if spi is None:
        return None
    try:
        resp = spi.xfer2([0x01, 0x00, 0x00])
        if len(resp) < 3:
            print("Error: SPI transfer returned insufficient data.", file=sys.stderr)
            return None
        raw = ((resp[1] & 0x03) << 8) | resp[2]
        return raw / 1024.0
    except Exception as e:
        print(f"Error reading temperature: {e}", file=sys.stderr)
        return None


def log_alert(temp):
    if conn is None:
        return
    try:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        cursor = conn.cursor()
        cursor.execute("INSERT INTO temperature_alerts VALUES (?, ?)", (timestamp, temp))
        conn.commit()
        print(f"Alert logged: Temp {temp:.2f}C at {timestamp}")
    except sqlite3.Error as e:
        print(f"Error logging alert: {e}", file=sys.stderr)


def cleanup():
    global spi, conn
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
        spi = None
    if conn is not None:
        try:
            conn.close()
        except Exception:
            pass
        conn = None


def main():
    if not init_spi():
        sys.exit(1)
    if not init_database():
        cleanup()
        sys.exit(1)

    try:
        while running:
            temp = read_temperature()
            if temp is not None:
                if temp > TEMP_THRESHOLD:
                    log_alert(temp)
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

