#!/usr/bin/env python3
"""
Occupancy-Based Lighting Controller for Raspberry Pi.

Uses two motion sensors (GPIO 17 and 27) and an LDR (simulated value 0-100)
to control an LED (GPIO 22).  Includes logging, debug mode, and a
watchdog-free timer-based off-delay.
"""

import atexit
import logging
import logging.handlers
import signal
import threading
import time
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
MOTION_SENSOR_1_PIN = 17
MOTION_SENSOR_2_PIN = 27
LED_PIN = 22

MOTION_SENSOR_1_PIN_NAME = "sensor1_pin"
MOTION_SENSOR_2_PIN_NAME = "sensor2_pin"
LED_PIN_NAME = "led_pin"

MOTION_DEBOUNCE_MS = 200
MOTION_THRESHOLD = 2
SAMPLE_PERIOD = 1.0
ILLUMINATION_THRESHOLD = 60
ON_TIME = 60
OFF_DELAY = 300

LOG_FILE = "occupancy_lights.log"
LOG_LEVEL = logging.DEBUG if True else logging.INFO

# ---------------------------------------------------------------------------
# Logging setup
# ---------------------------------------------------------------------------
logger = logging.getLogger("occupancy_lights")
logger.setLevel(LOG_LEVEL)

fmt = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")

file_handler = logging.handlers.TimedRotatingFileHandler(
    LOG_FILE, when="midnight", interval=1, backupCount=7
)
file_handler.setFormatter(fmt)
logger.addHandler(file_handler)

console_handler = logging.StreamHandler()
console_handler.setFormatter(fmt)
logger.addHandler(console_handler)

# ---------------------------------------------------------------------------
# GPIO setup
# ---------------------------------------------------------------------------
class GPIOSetupError(Exception):
    pass

def setup_gpio():
    if GPIO is None:
        raise GPIOSetupError("RPi.GPIO module not available")
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in (MOTION_SENSOR_1_PIN, MOTION_SENSOR_2_PIN, LED_PIN):
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logger.info("GPIO setup complete.")
    except Exception as e:
        logger.error(f"GPIO setup failed: {e}")
        raise

def cleanup_gpio():
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logger.info("GPIO cleanup complete.")
        except Exception as e:
            logger.error(f"GPIO cleanup failed: {e}")

# ---------------------------------------------------------------------------
# MotionSensor
# ---------------------------------------------------------------------------
class MotionSensor:
    def __init__(self, pin, name, threshold, sample_period):
        self.pin = pin
        self.name = name
        self.threshold = threshold
        self.sample_period = sample_period
        self.event_count = 0
        self.last_event_time = 0.0
        self.lock = threading.Lock()
        self._running = True

        if GPIO is not None:
            try:
                GPIO.add_event_detect(
                    self.pin, GPIO.RISING,
                    callback=self._on_motion,
                    bouncetime=MOTION_DEBOUNCE_MS,
                )
            except Exception as e:
                logger.error(f"Failed to add event detect on {self.name}: {e}")
                raise

    def _on_motion(self, channel):
        """Rising-edge callback."""
        with self.lock:
            now = time.time()
            if now - self.last_event_time < self.sample_period:
                return
            self.last_event_time = now
            self.event_count += 1

    def check_motion(self):
        with self.lock:
            now = time.time()
            if now - self.last_event_time < self.sample_period:
                return False
            return self.event_count >= self.threshold

    def reset(self):
        with self.lock:
            self.event_count = 0
            self.last_event_time = 0.0

    def stop(self):
        self._running = False

# ---------------------------------------------------------------------------
# LightingController
# ---------------------------------------------------------------------------
class LightingController:
    def __init__(self, led_pin, on_time, off_delay, ldr_value):
        self.led_pin = led_pin
        self.on_time = on_time
        self.off_delay = off_delay
        self.ldr_value = ldr_value
        self.last_motion_time = 0.0
        self._running = True
        self._timer = None

        if GPIO is not None:
            try:
                GPIO.setup(self.led_pin, GPIO.OUT, initial=GPIO.LOW)
            except Exception as e:
                logger.error(f"Failed to setup LED pin {self.led_pin}: {e}")
                raise

    def turn_on(self):
        if not self._running:
            return
        try:
            GPIO.output(self.led_pin, GPIO.HIGH)
            logger.info(f"LED turned ON (motion detected, LDR={self.ldr_value}).")
        except Exception as e:
            logger.error(f"Failed to turn on LED: {e}")

    def turn_off(self):
        if not self._running:
            return
        try:
            GPIO.output(self.led_pin, GPIO.LOW)
            logger.info("LED turned OFF.")
        except Exception as e:
            logger.error(f"Failed to turn off LED: {e}")

    def _off_delay(self):
        if not self._running:
            return
        logger.info(f"Entering off-delay ({self.off_delay}s).")
        self.last_motion_time = 0.0
        self._running = False
        if self._timer is not None:
            self._timer.cancel()
        if GPIO is not None:
            try:
                GPIO.output(self.led_pin, GPIO.LOW)
            except Exception:
                pass
        threading.Timer(self.off_delay, self._off_delay).start()

    def cleanup(self):
        self._running = False
        if self._timer is not None:
            self._timer.cancel()
        if GPIO is not None:
            try:
                GPIO.output(self.led_pin, GPIO.LOW)
            except Exception:
                pass
            try:
                GPIO.cleanup(self.led_pin)
            except Exception:
                pass

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global debug_mode
    debug_mode = True

    signal.signal(signal.SIGINT, lambda s, f: logger.info(f"Received signal {s}"))
    signal.signal(signal.SIGTERM, lambda s, f: logger.info(f"Received signal {s}"))

    try:
        setup_gpio()
    except GPIOSetupError:
        logger.critical("Cannot continue without GPIO. Exiting.")
        return

    motion_sensor_1 = MotionSensor(
        MOTION_SENSOR_1_PIN, MOTION_SENSOR_1_PIN_NAME, MOTION_THRESHOLD, SAMPLE_PERIOD
    )
    motion_sensor_2 = MotionSensor(
        MOTION_SENSOR_2_PIN, MOTION_SENSOR_2_PIN_NAME, MOTION_THRESHOLD, SAMPLE_PERIOD
    )

    controller = LightingController(
        LED_PIN, ON_TIME, OFF_DELAY, 50
    )

    def motion_detected():
        if not debug_mode:
            logger.info("Motion detected.")
        controller.turn_on()

    motion_sensor_1.when_motion = motion_detected
    motion_sensor_2.when_motion = motion_detected

    try:
        while True:
            if debug_mode:
                logger.debug("Waiting for motion...")
            if motion_sensor_1.check_motion() or motion_sensor_2.check_motion():
                controller.last_motion_time = time.time()
            time.sleep(0.1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        controller.cleanup()
        cleanup_gpio()
        logger.info("Program exited.")

if __name__ == "__main__":
    main()

