import smbus
import time
import signal
import sys

# ADS1115 constants
ADS1115_ADDRESS = 0x00
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

# Config register bit fields
ADS1115_CONFIG_OS_BEGIN = 0x8000
ADS1115_CONFIG_MUX_OFFSET = 12
ADS1115_CONFIG_PGA_4_096V = 0x0200
ADS1115_CONFIG_MODE_SINGLE = 0x0100
ADS1115_CONFIG_DR_128SPS = 0x0080
ADS1115_CONFIG_CQUE_NONE = 0x0003

# Timing
CONVERSION_TIMEOUT_S = 0.100
LOOP_DELAY_S = 0.050

# Global handle for signal handler
_bus = None


def _signal_handler(signum, frame):
    global _bus
    print(f"\nReceived signal {signum}, exiting...")
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
    sys.exit(0)


def _swap_bytes(word):
    return ((word & 0xFF00) >> 8) | ((word & 0x00FF) << 8)


def _build_config(channel):
    if not 0 <= channel <= 3:
        raise ValueError(f"Invalid channel {channel}; must be 0-3")
    return (
        ADS1115_CONFIG_OS_BEGIN
        | (channel << ADS1115_CONFIG_MUX_OFFSET)
        | ADS1115_CONFIG_PGA_4_096V
        | ADS1115_CONFIG_MODE_SINGLE
        | ADS1115_CONFIG_DR_128SPS
        | ADS1115_CONFIG_CQUE_NONE
    )


def read_adc(channel, bus):
    config = _build_config(channel)
    try:
        bus.write_word_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG, config)
    except OSError as e:
        print(f"I2C write error on channel {channel}: {e}")
        return None

    deadline = time.monotonic() + CONVERSION_TIMEOUT_S
    while True:
        try:
            status = bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG)
        except OSError as e:
            print(f"I2C read error on channel {channel}: {e}")
            return None
        if not (status & ADS1115_CONFIG_OS_BEGIN):
            return None
        if time.monotonic() > deadline:
            print(f"Timeout reading channel {channel}")
            return None
        time.sleep(0.001)

    try:
        raw = bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONVERSION)
    except OSError as e:
        print(f"I2C read error on channel {channel}: {e}")
        return None

    if _swap_bytes(raw) & 0x8000:
        raw -= 0x10000
    return raw


def main():
    global _bus
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _bus = smbus.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}")
        sys.exit(1)

    try:
        while True:
            values = []
            for ch in range(4):
                val = read_adc(ch, _bus)
                if val is None:
                    values.append("ERROR")
                else:
                    values.append(f"{val:+d}")
            print("  ".join(values))
            time.sleep(LOOP_DELAY_S)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if _bus is not None:
            try:
                _bus.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

