    except OSError as e:
        print(f"I2C write error on channel {channel}: {e}")
        return None

    deadline = time.monotonic() + CONVERSION_TIMEOUT_S
    while True:
        try:
            status = bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG)
        except OSError as e:
            print(f"I2C read error on channel {channel}: {e}")
            return None
        if not (status & ADS1115_CONFIG_OS_BEGIN):
            return None
        if time.monotonic() > deadline:
            print(f"Timeout reading channel {channel}")
            return None
        time.sleep(0.001)

    try:
        raw = bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONVERSION)
    except OSError as e:
        print(f"I2C read error on channel {channel}: {e}")
        return None

    if _swap_bytes(raw) & 0x8000:
        raw -= 0x10000
    return raw


def main():
    global _bus
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _bus = smbus.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}")
        sys.exit(1)

    try:
        while True:
            values = []
            for ch in range(4):
                val = read_adc(ch, _bus)
                if val is None:
                    values.append("ERROR")
                else:
                    values.append(f"{val:+d}")
            print("  ".join(values))
            time.sleep(LOOP_DELAY_S)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if _bus is not None:
            try:
                _bus.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

