import time
import argparse
import logging
import threading
import queue
import spidev
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class SoundSensor:
    """
    A class to represent a sound sensor, either digital (GPIO) or analog (MCP3008 ADC).
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=None, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.gpio_initialized = False
        self._lock = threading.Lock()

        if self.sensor_type == 'digital':
            self.gpio_channel = self.gpio_pins[self.channels - 1]
            self._setup_gpio(self.gpio_channel)
        elif self.sensor_type == 'analog':
            self._setup_spi()
        else:
            raise ValueError("Invalid sensor_type. Must be 'digital' or 'analog'.")

    def _setup_gpio(self, gpio_channel):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(gpio_channel, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self.gpio_initialized = True
            logging.info(f"GPIO {gpio_channel} setup for sensor {self.sensor_id}.")
        except Exception as e:
            logging.error(f"Error setting up GPIO {gpio_channel} for sensor {self.sensor_id}: {e}")
            self.gpio_initialized = False

    def _setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            logging.info(f"SPI bus 0, device 0 setup for sensor {self.sensor_id} at {self.spi_speed} Hz.")
        except Exception as e:
            logging.error(f"Error setting up SPI for sensor {self.sensor_id}: {e}")
            self.spi = None

    def read_digital(self):
        if not self.gpio_initialized:
            logging.error("GPIO not initialized for digital reading.")
            return None
        try:
            return GPIO.input(self.gpio_channel)
        except Exception as e:
            logging.error(f"Error reading digital sensor {self.sensor_id}: {e}")
            return None

    def read_analog(self):
        if not self.spi:
            logging.error("SPI not initialized for analog reading.")
            return None
        try:
            adc = self._read_mcp3008(0, 0, self.channels)
            if adc is None:
                logging.error("Invalid ADC reading from sensor {self.sensor_id}.")
                return None
            return adc
        except Exception as e:
            logging.error(f"Error reading analog sensor {self.sensor_id}: {e}")
            return None

    def _read_mcp3008(self, cs, dc, channel):
        if not self.spi:
            return None
        try:
            r = self.spi.xfer2([1, (8 + channel) << 4, 0])
            adc = ((r[1] & 3) << 8) + r[2]
            return adc
        except Exception as e:
            logging.error(f"Error reading MCP3008 channel {channel} from sensor {self.sensor_id}: {e}")
            return None

    def detect_event(self):
        if self.sensor_type == 'digital':
            digital_value = self.read_digital()
            if digital_value is not None and digital_value == 1:
                logging.info(f"Event detected by digital sensor {self.sensor_id} (GPIO {self.gpio_channel}).")
                self.log_queue.put({'sensor_id': self.sensor_id, 'event': 'event_detected', 'timestamp': time.time()})
        elif self.sensor_type == 'analog':
            analog_value = self.read_analog()
            if analog_value is not None and analog_value >= self.threshold:
                logging.info(f"Event detected by analog sensor {self.sensor_id} (ADC: {analog_value}).")
                self.log_queue.put({'sensor_id': self.sensor_id, 'event': 'event_detected', 'timestamp': time.time(), 'adc_value': analog_value})

    def run(self):
        while True:
            self.detect_event()
            time.sleep(1 / self.sample_rate)

    def stop(self):
        logging.info(f"Stopping sensor {self.sensor_id}.")

    def cleanup(self):
        if self.sensor_type == 'digital':
            if self.gpio_initialized:
                try:
                    GPIO.cleanup(self.gpio_channel)
                    self.gpio_initialized = False
                    logging.info(f"GPIO {self.gpio_channel} cleaned up for sensor {self.sensor_id}.")
                except Exception as e:
                    logging.error(f"Error cleaning up GPIO {self.gpio_channel} for sensor {self.sensor_id}: {e}")
        elif self.sensor_type == 'analog':
            if self.spi:
                try:
                    self.spi.close()
                    logging.info("SPI closed for sensor {self.sensor_id}.")
                except Exception as e:
                    logging.error(f"Error closing SPI for sensor {self.sensor_id}: {e}")


def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitoring Program")
    parser.add_argument("--sensor_type", required=True, choices=['digital', 'analog'], help="Sensor type")
    parser.add_argument("--threshold", type=int, required=True, help="Threshold value for analog sensor")
    parser.add_argument("--sample_rate", type=float, required=True, help="Sample rate in Hz")
    parser.add_argument("--log_file", type=str, required=True, help="Path to the log file")
    parser.add_argument("--gpio_pins", type=str, required=True, help="GPIO pin numbers (e.g., 17,18,27)")
    parser.add_argument("--channels", type=int, required=True, help="MCP3008 channels (0-7)")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", nargs='+', required=True, help="Sensor IDs")

    args = parser.parse_args()

    log_queue = queue.Queue()
    sensors = []
    threads = []

    try:
        for sensor_id in args.sensor_ids:
            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
            sensors.append(sensor)
            t = threading.Thread(target=sensor.run, daemon=True)
            t.start()
            threads.append(t)

        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        for t in threads:
            t.join(timeout=2)
        for sensor in sensors:
            sensor.stop()
            sensor.cleanup()
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

