import signal
import sys
import time
import logging

try:
    import adafruit_ads1x15.ads1115 as ADS
    from adafruit_ads1x15.analog_in import AnalogIn
    from adafruit_ads1x15.i2c import ADS1115
except ImportError as exc:
    print(f"Missing required library: {exc.name}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-ads1x15", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("battery_monitor")

I2C_BUS = 3
ADC_CHANNEL = 0
SAMPLE_DELAY = 0.1
RETRY_DELAY = 1.0
CHANGE_THRESHOLD = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def read_battery_voltage(ads, channel):
    """Return the battery voltage in volts, or None on error."""
    try:
        return float(ads.read(channel))
    except OSError as exc:
        log.warning("I2C bus error reading ADS1115 channel %d: %s", channel, exc)
        return None
    except Exception as exc:
        log.warning("Unexpected error reading ADS1115 channel %d: %s", channel, exc)
        return None


def calculate_charge(voltage):
    """Return charge percentage (0–100) for a given voltage."""
    if voltage is None:
        return None
    if voltage < 3.0 or voltage > 4.2:
        log.warning("Voltage %.2f V out of valid range [3.0, 4.2]; skipping.", voltage)
        return None
    return (voltage / 4.2) * 100.0


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ads = ADS.ADS1115(i2c_bus=I2C_BUS, address=0x48)
        log.info("ADS1115 initialized on I2C bus %d at address 0x48.", I2C_BUS)
    except OSError as exc:
        log.error("Failed to initialize ADS1115 on I2C bus %d: %s", I2C_BUS, exc)
        sys.exit(1)
    except Exception as exc:
        log.error("Unexpected error initializing ADS1115: %s", exc)
        sys.exit(1)

    last_percentage = None

    try:
        while _running:
            voltage = read_battery_voltage(ads, ADC_CHANNEL)
            percentage = calculate_charge(voltage)

            if percentage is not None and (last_percentage is None or abs(percentage - last_percentage) >= CHANGE_THRESHOLD):
                print(f"Battery Voltage: {voltage:.2f} V | Charge: {percentage:.2f}%")
                last_percentage = percentage

            if _running:
                time.sleep(RETRY_DELAY)
    finally:
        try:
            ads.power_down()
        except Exception:
            pass
        log.info("ADS1115 driver closed cleanly.")


if __name__ == "__main__":
    main()

