import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
GAIN = 1          # ±4.096 V range
SAMPLE_DELAY = 0.5  # seconds between readings
TABLE_DELAY = 0.5   # seconds between table prints

# --- Initialize I2C bus --------------------------------------------------------
try:
    i2c = busio.I2C(board.SCL, board.SDA)
except Exception as exc:
    print(f"Error: failed to initialize I2C bus {I2C_BUS}: {exc}")
    raise SystemExit(1)

# --- Initialize ADS1115 --------------------------------------------------------
try:
    ads = ADS.ADS1115(i2c, address=0x48, gain=GAIN)
except ValueError as exc:
    print(f"Error: ADS1115 not found at 0x48 on bus {I2C_BUS}: {exc}")
    raise SystemExit(1)
except Exception as exc:
    print(f"Error: ADS1115 initialization failed: {exc}")
    raise SystemExit(1)

# --- Create AnalogIn objects for channels A0–A3 ---------------------------------
channels = []
for ch in range(4):
    try:
        channels.append(AnalogIn(ads, ch))
    except Exception as exc:
        print(f"Warning: failed to configure channel A{ch}: {exc}")
        channels.append(None)

# --- Main loop ---------------------------------------------------------------
try:
    while True:
        values = []
        for idx, ch in enumerate(channels):
            if ch is None:
                values.append("ERR")
            else:
                try:
                    values.append(ch.value)
                except Exception as exc:
                    print(f"Warning: read error on channel A{idx}: {exc}")
                    values.append("ERR")

        print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(*values))
        time.sleep(TABLE_DELAY)

except KeyboardInterrupt:
    print("\nExiting program gracefully.")

