import signal
import sys
import time
import logging
from datetime import datetime, timezone

try:
    import board
    import busio
    import adafruit_max30102
except ImportError as exc:
    print(f"Missing required library: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-max30102", file=sys.stderr)
    sys.exit(1)

LOG_FILE = "heart_rate_log.txt"
WINDOW_SECONDS = 4
SAMPLE_INTERVAL = 1.0

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("max30102")

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _safe_int(value):
    """Safely cast to int, returning None on failure."""
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _safe_float(value):
    """Safely cast to float, returning None on failure."""
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _safe_value(value):
    """Safely cast to int or float, returning None on failure."""
    try:
        return _safe_int(value) if isinstance(value, int) else _safe_float(value)
    except Exception:
        return None


def _init_sensor():
    """Initialize I2C bus and MAX30102 sensor with error handling."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        log.error("Failed to initialize I2C bus: %s", exc)
        return None

    try:
        sensor = adafruit_max30102.MAX30102(i2c)
    except Exception as exc:
        log.error("MAX30102 not detected on I2C bus: %s", exc)
        try:
            i2c.deinit()
        except Exception:
            pass
        return None

    log.info("MAX30102 initialized successfully.")
    return sensor


def _read_sensor(sensor):
    """Read raw IR and RED ADC values; return (ir, red) or (None, None) on error."""
    try:
        ir = sensor.ir
        red = sensor.red
        if ir is None or red is None:
            return None, None
        return ir, red
    except Exception as exc:
        log.error("Error reading sensor data: %s", exc)
        return None, None


def _calculate_bpm(ir_values):
    """Estimate BPM from rolling window of IR peaks; return None if insufficient data."""
    if len(ir_values) < 2:
        return None
    if len(ir_values) < WINDOW_SECONDS:
        return None
    peaks = [v for v in ir_values if v > 0]
    if not peaks:
        return None
    freq = len(peaks) / len(ir_values)
    return max(1.0, freq * 60.0)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = _init_sensor()
    if sensor is None:
        sys.exit(1)

    ir_values = []
    ir_last = None

    try:
        while _running:
            ir, red = _read_sensor(sensor)
            if ir is None:
                time.sleep(SAMPLE_INTERVAL)
                continue

            ir_last = ir
            ir_values.append(ir)

            if len(ir_values) > WINDOW_SECONDS:
                ir_values.pop(0)

            bpm = _calculate_bpm(ir_values)
            if bpm is not None:
                timestamp = datetime.now(timezone.utc).isoformat()
                log.info("HR: %.0f bpm | IR: %d | RED: %d | %s",
                         bpm, ir, red, timestamp)
                print(f"HR: {bpm:.0f} bpm | IR: {ir} | RED: {red} | {timestamp}")

            time.sleep(SAMPLE_INTERVAL)

    except Exception as exc:
        log.error("Unexpected error in main loop: %s", exc)
    finally:
        try:
            i2c = getattr(sensor, "i2c", None)
            if i2c is not None:
                try:
                    i2c.deinit()
                except Exception:
                    pass
        except Exception:
            pass
        log.info("Program terminated cleanly.")


if __name__ == "__main__":
    main()

