import json
import logging
import signal
import sys
import time
from pathlib import Path

from picamera2 import Picamera2
from picamera2.encoders import JpegEncoder
from picamera2.outputs import FileOutput

import config
import indicators
import util
import detectors

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received – shutting down.", signum)
    _running = False


def load_config(path: str = "config.json") -> dict:
    try:
        p = Path(path)
        if not p.is_file():
            raise FileNotFoundError(f"Config file not found: {path}")
        with open(p, "r", encoding="utf-8") as f:
            cfg = json.load(f)
        logger.info("Loaded config from %s", path)
        return cfg
    except (FileNotFoundError, json.JSONDecodeError, OSError) as e:
        logger.error("Error loading config: %s", e)
        raise


def initialize_camera() -> Picamera2:
    try:
        cam = Picamera2()
        cam.configure(
            cam.create_preview_configuration(
                main={"size": (224, 224), "format": "RGB888"}
            )
        )
        cam.start()
        logger.info("Camera initialised at 224x224.")
        return cam
    except Exception as e:
        logger.error("Camera init failed: %s", e)
        raise


def capture_frame(cam: Picamera2) -> bytes:
    try:
        buf = cam.capture_array()
        if buf is None or buf.size == 0:
            logger.warning("Empty frame captured.")
            return None
        return buf.tobytes()
    except Exception as e:
        logger.error("Frame capture failed: %s", e)
        return None


def run_inference(detector, frame_data: bytes) -> bool:
    try:
        img = detector.detect(frame_data)
        logger.info("Detected: %s", img)
        return True
    except Exception as e:
        logger.error("Inference failed: %s", e)
        return False


def indicate_bird(led_pin: int) -> None:
    try:
        indicators.indicate_bird(led_pin)
        time.sleep(1)
    except Exception as e:
        logger.error("indicate_bird failed: %s", e)


def control_feeder_door(cam: Picamera2, door_pin: int, cfg: dict) -> None:
    try:
        if cfg.get("gpio_door_control") is True:
            if cfg.get("door_control") is True:
                util.open_feeder_door(door_pin)
            else:
                util.close_feeder_door(door_pin)
    except Exception as e:
        logger.error("Feeder-door control failed: %s", e)


def main() -> None:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cam = None
    try:
        cfg = load_config()
        led_pin = config.LED_PIN
        door_pin = config.DOOR_PIN

        cam = initialize_camera()
        detector = detectors.get_detector(cfg)

        while _running:
            frame = capture_frame(cam)
            if frame is not None:
                if run_inference(detector, frame):
                    indicate_bird(led_pin)
                    control_feeder_door(cam, door_pin, cfg)

            time.sleep(0.1)

    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        if cam is not None:
            try:
                cam.stop()
                logger.info("Camera released.")
            except Exception as e:
                logger.error("Error releasing camera: %s", e)
        logger.info("Program exited.")


if __name__ == "__main__":
    main()

