#!/usr/bin/env python3
"""Hydroponics control loop for Raspberry Pi.

Drives an SG90 servo on GPIO17 (50 Hz, 1.0–2.0 ms pulse) and reads a
simulated potentiometer on GPIO18.  Configuration is loaded from
config.ini, created with defaults if missing.
"""

import configparser
import logging
import random
import signal
import sys
import time

from gpiozero import Servo, InputDevice

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
SERVO_PIN = 17
POTENTIOMETER_PIN = 18
CONFIG_FILE = "config.ini"
LOG_FILE = "hydroponics.log"
PULSE_MIN_MS = 1.0
PULSE_MAX_MS = 2.0
LOOP_INTERVAL_S = 5.0
TEMP_MIN_C = 20.0
TEMP_MAX_C = 30.0
GREENNESS_MIN = 0
GREENNESS_MAX = 100

# ---------------------------------------------------------------------------
# Globals for signal handling
# ---------------------------------------------------------------------------
_running = True


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _init_servo():
    """Create and return a Servo instance, raising on failure."""
    try:
        return Servo(
            SERVO_PIN,
            min_pulse_width=PULSE_MIN_MS / 1000.0,
            max_pulse_width=PULSE_MAX_MS / 1000.0,
            frame_width=1.0 / 50.0,   # 50 Hz
        )
    except Exception as exc:
        raise RuntimeError(f"Failed to initialise servo on GPIO{SERVO_PIN}: {exc}") from exc


def _read_calibration():
    """Read calibration values from config.ini, creating defaults if missing."""
    config = configparser.ConfigParser()
    try:
        if not config.read(CONFIG_FILE):
            config["CALIBRATION"] = [
                {"min_angle": "0", "max_angle": "90", "min_pot_value": "0.1", "max_pot_value": "0.9"},
            ]
            with open(CONFIG_FILE, "w") as fh:
                config.write(fh)
            logging.warning("config.ini missing; created with defaults.")
    except Exception as exc:
        raise RuntimeError(f"Error reading config file: {exc}") from exc

    return {
        "min_angle": int(config["CALIBRATION"][0]["min_angle"]),
        "max_angle": int(config["CALIBRATION"][0]["max_angle"]),
        "min_pot_value": float(config["CALIBRATION"][0]["min_pot_value"]),
        "max_pot_value": float(config["CALIBRATION"][0]["max_pot_value"]),
    }


def _simulate_temperature():
    """Return a simulated temperature in °C."""
    return random.uniform(TEMP_MIN_C, TEMP_MAX_C)


def _simulate_greenness():
    """Return a simulated greenness score (0–100)."""
    return random.randint(GREENNESS_MIN, GREENNESS_MAX)


def _simulate_potentiometer():
    """Return a simulated potentiometer value in [0.1, 0.9]."""
    return random.uniform(_read_calibration()["min_pot_value"], _read_calibration()["max_pot_value"])


def _map_to_vent_angle(temperature, greenness, pot_value):
    """Map inputs to a vent angle (0–90°)."""
    if temperature < _read_calibration()["min_angle"]:
        angle = 0
    elif temperature > _read_calibration()["max_angle"]:
        angle = 90
    else:
        angle = int(
            (temperature - _read_calibration()["min_angle"]) * 90
            / (_read_calibration()["max_angle"] - _read_calibration()["min_angle"])
        )
    angle += int(
        (greenness - _read_calibration()["min_pot_value"]) * 90
