SCAN_X_START = 0
SCAN_X_END = 640
SCAN_Y_START = 0
SCAN_Y_END = 480
SCAN_STEP_SIZE = 1
IMAGE_DIR = "images"
IMAGE_FILENAME_PREFIX = "scan"
IMAGE_FILENAME_EXTENSION = "jpg"
SAFETY_TIMEOUT = 5.0

_running = True

def signal_handler(signum, frame):
    global _running
    logger.info(f"Signal {signum} received, shutting down gracefully...")
    _running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def setup_camera():
    if Picamera2 is None:
        logger.error("picamera2 library not available.")
        return None
    try:
        cam = Picamera2()
        config = cam.create_still_configuration()
        cam.configure(config)
        cam.start()
        logger.info("Camera initialized successfully.")
        return cam
    except Exception as e:
        logger.error(f"Error initializing camera: {e}")
        return None

def move_steps(motor, direction, steps, delay):
    if motor == MOTOR_X:
        X_DIR.value = direction
        X_STEP.value = direction
    else:
        Y_DIR.value = direction
        Y_STEP.value = direction
    X_ENABLE.off()  # LOW = enable
    Y_ENABLE.off()
    for _ in range(steps):
        if not _running:
            logger.info("Movement interrupted by shutdown signal.")
            return
        time.sleep(delay)
    X_ENABLE.on()  # HIGH = disable
    Y_ENABLE.on()

