    logger.info("Starting homing sequence...")
    x_pos = 0
    y_pos = 0
    timeout = time.time() + SAFETY_TIMEOUT
    while not X_LIMIT.is_active and not Y_LIMIT.is_active:
        if time.time() > timeout:
            logger.error("Homing timeout reached.")
            return
        move_steps(MOTOR_X, 0, 10, STEP_DELAY)
        move_steps(MOTOR_Y, 0, 10, STEP_DELAY)
        x_pos += 10
        y_pos += 10
        time.sleep(0.1)
    x_pos = 0
    y_pos = 0
    logger.info(f"Stage homed to X: {x_pos}, Y: {y_pos}")

