    filename = f"{IMAGE_FILENAME_PREFIX}{x}{SCAN_X_START}{SCAN_DIR}{SCAN_X_END}{SCAN_Y_START}{SCAN_Y_END}{IMAGE_FILENAME_EXTENSION}"
