import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
import os

# Global resources for cleanup
cap = None
ser = None
running = True

def cleanup():
    global cap, ser
    if cap is not None and cap.isOpened():
        cap.release()
    if ser is not None and ser.is_open:
        try:
            ser.close()
        except Exception:
            pass
    cv2.destroyAllWindows()

def signal_handler(sig, frame):
    global running
    running = False

def find_serial_port():
    """Find the first available serial port, preferring /dev/ttyACM0."""
    available = [p.device for p in serial.tools.list_ports.comports()]
    if '/dev/ttyACM0' in available:
        return '/dev/ttyACM0'
    return available[0] if available else None

def init_serial(port):
    global ser
    try:
        ser = serial.Serial(port, 9600, timeout=1)
        return True
    except serial.SerialException as e:
        print(f"Warning: Could not open serial port {port}: {e}")
        ser = None
        return False

def get_ball_center(ball_x, ball_y):
    """Classify ball center based on dead-zone half-extents."""
    half_w = 25
    half_h = 25
    if ball_x > (half_w + 25):
        return 1  # Bottom-Right
    elif ball_x < (half_w - 25):
        return 2  # Top-Right
    if ball_y > (half_h + 25):
        return 3  # Bottom-Left
    elif ball_y < (half_h - 25):
        return 4  # Top-Left
    return 5  # Center

def main():
    global cap, ser, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize camera
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera (index 0).")
        cleanup()
        sys.exit(1)

    # Initialize serial
    port = find_serial_port()
    if port is None:
        print("Warning: No serial port available. Serial output disabled.")
    if not init_serial(port):
        print("Warning: Serial output disabled due to init failure.")

    ball_x = 0
    ball_y = 0
    tracking_enabled = False
    ball_color_min = np.array([0, 0, 0])
    ball_color_max = np.array([255, 255, 255])
    ball_is_tracked = False

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            # Resize for faster processing
            frame = cv2.resize(frame, (500, int(500 * frame.shape[0] / frame.shape[1])))
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)

            if cv2.waitKey(1) & 0xFF == ord('s'):
                min_hue, min_sat, min_val = np.array([0, 0, 0])
                max_hue, max_sat, max_val = np.array([255, 255, 255])
                mask = cv2.inRange(hsv, min_hue, max_hue)
                contours, _ = cv2.findContours(mask, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

                for contour in contours:
                    area = cv2.contourArea(contour)
                    if area > 500:
                        x, y, w, h = cv2.boundingRect(contour)
                        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

                        ball_x = x + w // 2
                        ball_y = y + h // 2

                        if ball_is_tracked:
                            ball_color_min = np.array([hsv[y + h // 2, x + w // 2, 0].astype(int)])
                            ball_color_max = np.array([hsv[y + h // 2, x + w // 2, 2].astype(int)])
                        else:
                            ball_is_tracked = True

                        center = get_ball_center(ball_x, ball_y)
                        if center != 5:
                            print(f"Position: {center}")
                            if ser is not None and ser.is_open:
                                try:
                                    ser.write(chr(center))
                                except serial.SerialException as e:
                                    print(f"Serial write error: {e}")

            if cv2.waitKey(1) & 0xFF == ord('o'):
                tracking_enabled = False
                ball_is_tracked = False

            if cv2.waitKey(1) & 0xFF == 27:
                break

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

