import time
import logging
import json
import signal
import sys
import os
from statistics import median

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DEFAULT_CONFIG = {
    "offset": 0.0,
    "max_distance": 200.0,
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning("Configuration file not found. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def initialize_gpio():
    if GPIO is None:
        logging.warning("RPi.GPIO not available. Running in mock mode.")
        return None
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(17, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(18, GPIO.IN)
    GPIO.setup(22, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(23, GPIO.IN)
    GPIO.setup(24, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(25, GPIO.IN)
    return 17


def get_distance(trigger_pin, echo_pin):
    if GPIO is None:
        return None
    try:
        GPIO.output(trigger_pin, GPIO.LOW)
        time.sleep(0.000002)
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, GPIO.LOW)

        timeout = time.time() + 0.05
        while GPIO.input(echo_pin) == 0:
            if time.time() > timeout:
                return None
        pulse_start = time.time()

        timeout = time.time() + 0.05
        while GPIO.input(echo_pin) == 1:
            if time.time() > timeout:
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150
        return distance
    except Exception as e:
        logging.error(f"Error reading sensor on trigger {trigger_pin}, echo {echo_pin}: {e}")
        return None


def get_water_level():
    distances = []
    for i in range(3):
        dist = get_distance(i + 1, i + 2)
        if dist is not None:
