#!/usr/bin/env python3
"""Voice-controlled greenhouse control system for Raspberry Pi.

Hardware:
  * DHT11 temperature/humidity sensor on BCM pin 4 (1-wire, not I2C)
  * Light relay on BCM pin 17
  * Camera module via CSI
  * Microphone (standard audio bus)

The DHT11 uses a 1-wire protocol; we use gpiozero for the relay and
libcamera for the camera.  Audio is captured via PyAudio.
"""

import argparse
import datetime
import json
import logging
import random
import signal
import sys
import time

# ---------------------------------------------------------------------------
# Optional hardware imports — degrade gracefully if unavailable
# ---------------------------------------------------------------------------
try:
    import gpiozero
    _GPIOZERO_AVAILABLE = True
except Exception:
    _GPIOZERO_AVAILABLE = False

try:
    from gpiozero import OutputDevice
except Exception:
    class _SimulatedOutputDevice:
        def __init__(self, pin, initial_value=False):
            self.pin = pin
            self._value = initial_value
        def on(self):
            pass
        def off(self):
            pass
        def value(self):
            return self._value
        def close(self):
            pass
    OutputDevice = _SimulatedOutputDevice

try:
    from libcamera import Transform
    _LIBCAMERA_AVAILABLE = True
except Exception:
    _LIBCAMERA_AVAILABLE = False

try:
    import pyaudio
    _PYAUDIO_AVAILABLE = True
except Exception:
    _PYAUDIO_AVAILABLE = False

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
DHT_PIN = 4
LIGHT_RELAY_PIN = 17
WAKE_WORD = "Greenhouse"
LISTEN_TIMEOUT = 5  # seconds
TEMP_MIN = 15.0
TEMP_MAX = 35.0
CAMERA_RESOLUTION = (640, 480)
CAMERA_ROTATION = Transform(vflip=True, hflip=True)

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------
_running = True
_camera = None
_light_relay = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    logger.info("Signal %s received – shutting down.", signum)
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


# ---------------------------------------------------------------------------
# Simulated sensor / GPIO helpers
# ---------------------------------------------------------------------------
def _simulate_temperature():
    """Return a plausible temperature in °C when the DHT11 is absent."""
    return round(random.uniform(TEMP_MIN, TEMP_MAX), 1)


def _simulate_dht_read():
    """Return (temperature, humidity) or (None, None) on failure."""
    return _simulate_temperature(), _simulate_temperature()


def _simulate_light_on():
    _light_relay.value = True
    logger.info("Lights turned ON (simulated).")


def _simulate_light_off():
    _light_relay.value = False
    logger.info("Lights turned OFF (simulated).")


# ---------------------------------------------------------------------------
# DHT11 sensor
# ---------------------------------------------------------------------------
def read_temperature():
    """Read temperature (°C) and humidity (%) from the DHT11.

    Returns (temperature, humidity) or (None, None) on failure.
    """
    if _GPIOZERO_AVAILABLE and _light_relay is not None:
        try:
            _light_relay.off()
        except Exception:
            pass

    try:
        import adafruit_dht
        import board
        dht_device = adafruit_dht.DHT11(board.D4)
    except Exception as exc:
        logger.warning("DHT11 init failed (%s) – using simulated data.", exc)
        return _simulate_dht_read()

    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            logger.warning("DHT11 returned None – using simulated data.")
            return _simulate_dht_read()
        return temperature, humidity
    except RuntimeError as exc:
        # DHT11 checksum / timing errors are common; retry once.
        logger.warning("DHT11 read error (%s) – using simulated data.", exc)
        return _simulate_dht_read()
    except Exception as exc:
        logger.error("Unexpected DHT11 error: %s", exc)
        return None, None
    finally:
        try:
            dht_device.exit()
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Camera
# ---------------------------------------------------------------------------
def take_picture():
    """Capture a picture with the CSI camera and save as greenhouse_{ts}.jpg."""
    global _camera
    if _camera is None:
        logger.warning("Camera not initialised – cannot take picture.")
        return

    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        _camera.capture_file(filename)
        logger.info("Picture saved as %s", filename)
    except Exception as exc:
        logger.error("Failed to take picture: %s", exc)


# ---------------------------------------------------------------------------
# Audio
# ---------------------------------------------------------------------------
def record_audio(filename):
    """Record audio from the default microphone and save to *filename*."""
    if not _PYAUDIO_AVAILABLE:
        logger.warning("pyaudio not available – cannot record audio.")
        return

    try:
        p = pyaudio.PyAudio()
        stream = p.open(
            format=pyaudio.paInt16,
            channels=1,
            rate=16000,
            input=True,
            frames_per_buffer=1024,
        )
        logger.info("Recording audio for %s seconds…", filename)
        frames = []
        for _ in range(5):
            data = stream.read(1024, exception_on_overflow=False)
            frames.append(data)
        stream.stop_stream()
        stream.close()
        p.terminate()

        try:
            import wave
            wave.open(filename, "wb").writeframes(bytes(frames))
        except Exception as exc:
            logger.error("Failed to write WAV file: %s", exc)
            try:
                p.terminate()
            except Exception:
                pass
            p = None
    except Exception as exc:
        logger.error("Audio recording failed: %s", exc)
    finally:
        if p is not None:
            try:
                p.terminate()
            except Exception:
                pass


# ---------------------------------------------------------------------------
# Command parsing
# ---------------------------------------------------------------------------
def parse_command(command_text):
    """Return (action, args) or None."""
    if not command_text:
        return None

    parts = command_text.lower().split()
    if not parts:
        return None

    if "turn on the lights" in parts:
        return "light_on", None
    elif "turn off the lights" in parts:
        return "light_off", None
    elif "what is the temperature" in parts:
        return "temperature", None
    elif "take a picture" in parts:
        return "picture", None
    elif "greenhouse" in parts:
        return "wake_up", None
    else:
        return None


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global _camera, _light_relay

    parser = argparse.ArgumentParser(description="Voice-controlled greenhouse system")
    parser.add_argument("--camera_resolution", default=CAMERA_RESOLUTION,
                        help="Camera resolution (width height)")
    parser.add_argument("--camera_rotation", default=CAMERA_ROTATION,
                        help="Camera rotation transform")
    parser.add_argument("--gpio_pin", type=int, default=DHT_PIN,
                        help="BCM GPIO pin for DHT11 data line")
    parser.add_argument("--light_relay_pin", type=int, default=LIGHT_RELAY_PIN,
                        help="BCM GPIO pin for light relay")
    args = parser.parse_args()

    _camera_resolution = tuple(args.camera_resolution)
    _camera_rotation = args.camera_rotation

    # --- GPIO / relay ----------------------------------------------------
    if _GPIOZERO_AVAILABLE and _light_relay is None:
        try:
            _light_relay = OutputDevice(args.light_relay_pin, initial_value=False)
            logger.info("Light relay initialised on BCM %d.", args.light_relay_pin)
        except Exception as exc:
            logger.warning("Could not initialise light relay on BCM %d: %s – simulating.",
                           args.light_relay_pin, exc)
            _light_relay = _SimulatedOutputDevice(args.light_relay_pin, False)

    # --- Camera ----------------------------------------------------------
    if _LIBCAMERA_AVAILABLE:
        try:
            from libcamera import Transform
            from libcamera import Transform
            _camera = Transform(vflip=True, hflip=True)
            _camera.configure(
                _camera.create_still_configuration(
                    main={"size": _camera_resolution},
                    transform=_camera_rotation,
                )
            )
            _camera.start()
            logger.info("Camera initialised at %s.", _camera_resolution)
        except Exception as exc:
            logger.warning("Could not initialise camera: %s – taking pictures disabled.",
                           exc)
            _camera = None
    else:
        logger.warning("libcamera not available – camera disabled.")

    # --- DHT11 -----------------------------------------------------------
    if _GPIOZERO_AVAILABLE and _light_relay is not None:
        try:
            import adafruit_dht
            import board
            dht_device = adafruit_dht.DHT11(board.D4)
            logger.info("DHT11 initialised on BCM %d.", args.gpio_pin)
        except Exception as exc:
            logger.warning("Could not initialise DHT11: %s – using simulated data.", exc)
            dht_device = None

    # --- PyAudio ----------------------------------------------------------
    if not _PYAUDIO_AVAILABLE:
        logger.warning("pyaudio not available – audio disabled.")

    logger.info("Greenhouse control system started.")

    try:
        while _running:
            if not record_audio("wake_word.wav"):
                continue

            audio_data = None
            if _PYAUDIO_AVAILABLE:
                try:
                    p = pyaudio.PyAudio()
                    stream = p.open(
                        format=pyaudio.paInt16,
                        channels=1,
                        rate=16000,
                        input=True,
                        frames_per_buffer=1024,
                    )
                    audio_data = stream.read(5, exception_on_overflow=False)
                    stream.stop_stream()
                    stream.close()
                    p.terminate()
                except Exception as exc:
                    logger.error("PyAudio init failed: %s", exc)
                    continue
                finally:
                    if p is not None:
                        try:
                            p.terminate()
                        except Exception:
                            pass

            if not audio_data:
                continue

            try:
                import speech_recognition as sr
                recognizer = sr.Recognizer()
            except Exception as exc:
                logger.error("speech_recognition import failed: %s", exc)
                continue

            try:
                with sr.Microphone() as source:
                    recognizer.adjust_for_ambient_noise(source, duration=0.5)
                    audio_data = recognizer.listen(source, timeout=LISTEN_TIMEOUT)
            except Exception as exc:
                logger.error("Microphone listen failed: %s", exc)
                continue

            try:
                text = recognizer.recognize_google(audio_data)
                logger.info("Recognised: %s", text)
            except Exception as exc:
                logger.error("Google Speech Recognition error: %s", exc)
                continue

            if WAKE_WORD not in text.lower():
                continue

            command_text = "greenhouse said: "
            command_text += " ".join(token.lower() for token in text.split() if token.lower() != "greenhouse")

            if not command_text:
                continue

            action, args = parse_command(command_text)
            if action is None:
                continue

            if action == "wake_up":
                logger.info("System is now awake.")
            elif action == "light_on":
                _simulate_light_on()
            elif action == "light_off":
                _simulate_light_off()
            elif action == "temperature":
                temperature, humidity = read_temperature()
                if temperature is not None and humidity is not None:
                    logger.info("Temperature: %.1f C, Humidity: %.1f %%", temperature, humidity)
                else:
                    logger.warning("Could not read temperature/humidity.")
            elif action == "picture":
                take_picture()
            else:
                logger.warning("Unknown command: %s", action)

    except Exception as exc:
        logger.error("Unexpected error in main loop: %s", exc)
    finally:
        logger.info("Cleaning up resources.")
        if _light_relay is not None:
            try:
                _light_relay.off()
                _light_relay.close()
            except Exception:
                pass
        if _camera is not None:
            try:
                _camera.stop()
                _camera.close()
            except Exception:
                pass
        logger.info("Greenhouse control system stopped.")


if __name__ == "__main__":
    main()

