import cv2
import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

CAMERA_INDEX = 0
FRAMERATE = 10
RESOLUTION = (640, 480)
ROI = (slice(10, 150), slice(40, 280))
OUTPUT_WINDOW_NAME = "Output Image"
GPIO_PIN = 17
ENTER_KEY = 10

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def setup_gpio(pin: int) -> None:
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO pin %d set to LOW.", pin)
    except (ImportError, RuntimeError) as exc:
        logging.error("Failed to initialize GPIO: %s", exc)
        raise


def setup_camera() -> cv2.VideoCapture:
    try:
        camera = cv2.VideoCapture(CAMERA_INDEX, cv2.CAP_V4L2)
        if not camera.isOpened():
            raise IOError("Cannot open camera at index %d.", CAMERA_INDEX)
        camera.set(cv2.CAP_PROP_FPS, FRAMERATE)
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, RESOLUTION[0])
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, RESOLUTION[1])
        actual_w = int(camera.get(cv2.CAP_PROP_FRAME_WIDTH))
        actual_h = int(camera.get(cv2.CAP_PROP_FRAME_HEIGHT))
        logging.info("Camera opened: %dx%d @ %d fps (requested %dx%d).", actual_w, actual_h, FRAMERATE, RESOLUTION[0], RESOLUTION[1])
        return camera
    except Exception as exc:
        logging.error("Error setting up camera: %s", exc)
        raise


def process_frame(frame: cv2.Mat) -> None:
    try:
        if frame is None or frame.size == 0:
            logging.warning("Empty frame received.")
            return
        if frame.shape[2] == 4:
            frame = cv2.cvtColor(frame, cv2.COLOR_BGRA2BGR)
        h, w = frame.shape[:2]
        if (ROI[0].start, ROI[0].end) != (0, w) or (ROI[1].start, ROI[1].end) != (0, h):
            x1, y1, x2, y2 = ROI
            frame = frame[y1:y2, x1:x2]
        cv2.imshow(OUTPUT_WINDOW_NAME, frame)
    except cv2.error as exc:
        logging.error("OpenCV error processing frame: %s", exc)
    except Exception as exc:
        logging.error("Unexpected error processing frame: %s", exc)


def cleanup(camera: cv2.VideoCapture | None) -> None:
    logging.info("Cleaning up resources...")
    if camera is not None:
        try:
            camera.release()
        except Exception as exc:
            logging.error("Error releasing camera: %s", exc)
    cv2.destroyAllWindows()
    try:
        import RPi.GPIO as GPIO
        GPIO.output(GPIO_PIN, GPIO.LOW)
        GPIO.cleanup(GPIO_PIN)
    except Exception as exc:
        logging.error("Error cleaning up GPIO: %s", exc)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio(GPIO_PIN)
    except Exception:
        sys.exit(1)

    camera = None
    try:
        camera = setup_camera()
        camera.set(cv2.CAP_PROP_POS_FRAMES, 0)
        logging.info("Camera initialized. Press Enter to exit, Ctrl+C to force quit.")

        while _running:
            ret, frame = camera.read()
            if not ret or frame is None:
                logging.error("Failed to grab frame from camera.")
                break
            process_frame(frame)
            if cv2.waitKey(1) & 0xFF == ENTER_KEY:
                logging.info("Exit key pressed. Closing.")
                break

    except IOError as exc:
        logging.error("IOError: %s", exc)
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        cleanup(camera)


if __name__ == "__main__":
    main()

