import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO is not installed. Install with: sudo apt install python3-rpi.gpio", file=sys.stderr)
    sys.exit(1)

# Pin definitions (BCM numbering)
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05  # seconds

# Track the last state of each input so we can detect a new LOW on GPIO 6
_input_states = [False, False, False]

_running = True


def _cleanup():
    """Release GPIO resources cleanly."""
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_gpio():
    """Configure input pins with pull-up resistors and output pins as outputs LOW.

    Returns True on success, False on any error.
    """
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        for pin in INPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        for pin in OUTPUT_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

        return True
    except Exception as exc:
        print(f"GPIO initialization failed: {exc}", file=sys.stderr)
        return False


def _set_output(pin, state):
    """Set an output pin to the given logical state (True=HIGH, False=LOW)."""
    try:
        GPIO.output(pin, GPIO.HIGH if state else GPIO.LOW)
    except Exception as exc:
        print(f"Error writing to GPIO {pin}: {exc}", file=sys.stderr)


def main():
    global _input_states

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _init_gpio():
        _cleanup()
        sys.exit(1)

    # Track the last state of each input so we can detect a new LOW on GPIO 6
    _input_states = [False, False, False]

    try:
        while _running:
            for pin in INPUT_PINS:
                try:
                    state = GPIO.input(pin)
                except Exception as exc:
                    print(f"Error reading GPIO {pin}: {exc}", file=sys.stderr)
                    state = None

                if state is not None and state == GPIO.LOW:
                    _input_states[pin] = True

            # GPIO 4: HIGH when LOW
            if _input_states[0]:
                _set_output(OUTPUT_PINS[0], GPIO.HIGH)

            # GPIO 5: LOW when LOW
            if _input_states[1]:
                _set_output(OUTPUT_PINS[0], GPIO.LOW)

            # GPIO 6: toggle on each new LOW
            if _input_states[2]:
                _set_output(OUTPUT_PINS[1], not _set_output(OUTPUT_PINS[1]))

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

