import os
import time
import logging
import configparser
import threading
import queue
import signal
import sys
import subprocess
from PIL import Image, ImageDraw, ImageFont

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from pyzbar.pyzbar import decode as pyzbar_decode
except ImportError:
    pyzbar_decode = None

DEFAULT_CONFIG = {
    'DEFAULT': {
        'motion_threshold': '10',
        'redundancy_time_window': '5.0',
        'frame_buffer_size': '10',
        'reinit_delay': '2.0',
        'cloud_upload_interval': '60',
        'watchdog_timeout': '30',
    }
}

class CameraHandler:
    def __init__(self, camera_id, camera_config, frame_queue, stop_event):
        self.camera_id = camera_id
        self.camera_config = camera_config
        self.frame_queue = frame_queue
        self.stop_event = stop_event
        self.camera = None
        self.font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 12)
        self.font_small = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 10)
        self.font_large = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 14)
        self.font_xlarge = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 18)
        self.font_color = (0, 0, 255)
        self.font_background = (0, 0, 0)
        self.font_large_color = (0, 0, 255)
        self.font_large_background = (0, 0, 0)
        self.font_xlarge_color = (0, 0, 255)
        self.font_xlarge_background = (0, 0, 0)
        self.motion_detected = False
        self.last_scan_time = 0.0
        self.buffer = []
        self.buffer_size = self.camera_config.getint('DEFAULT', 'frame_buffer_size')
        self.lock = threading.Lock()
        self.running = True

    def initialize(self):
        if Picamera2 is None:
            logging.error("picamera2 library not found. Camera not available.")
            return False
        try:
            self.camera = Picamera2(camera_num=self.camera_id)
            config = self.camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)})
            self.camera.configure(config)
            self.camera.start()
            logging.info(f"Camera {self.camera_id} initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Error initializing camera {self.camera_id}: {e}")
            self.camera = None
            return False

    def capture_frame(self):
        if self.camera is None:
            return None
        try:
            frame = self.camera.capture_array()
            if frame is None:
                logging.warning(f"Camera {self.camera_id} returned None frame.")
                return None
            return frame
        except Exception as e:
            logging.error(f"Error capturing frame from camera {self.camera_id}: {e}")
            return None

    def decode_qr_code(self, image):
        if pyzbar_decode is None:
            logging.warning("pyzbar library not found. QR code decoding disabled.")
            return None
        try:
            decoded_objects = pyzbar_decode(image)
            if decoded_objects:
                return decoded_objects[0].data.decode('utf-8')
            return None
        except Exception as e:
            logging.error(f"Error decoding QR code: {e}")
