import os
import time
import signal
import logging
import configparser
import numpy as np
import cv2
from PIL import Image
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CONFIG_FILE = 'config.txt'
SNAPSHOT_DIR = 'snapshots'

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received.")

def load_config(config_file):
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        raise FileNotFoundError(f"Configuration file not found: {config_file}")
    config.read(config_file)
    return config

def get roi(config):
    try:
        roi_x1 = int(config['ROI']['roi_x1'])
        roi_y1 = int(config['ROI']['roi_y1'])
        roi_x2 = int(config['ROI']['roi_x2'])
        roi_y2 = int(config['ROI']['roi_y2'])
        return roi_x1, roi_y1, roi_x2, roi_y2
    except KeyError as e:
        raise ValueError(f"Missing ROI parameters in config: {e}")
    except ValueError as e:
        raise ValueError(f"Invalid ROI coordinates in config: {e}")

def get_motion_threshold(config):
    try:
        motion_threshold = int(config['MOTION']['motion_threshold'])
        if motion_threshold <= 0:
            raise ValueError("Motion threshold must be positive.")
        return motion_threshold
    except KeyError as e:
        raise ValueError(f"Missing motion threshold in config: {e}")
    except ValueError as e:
        raise ValueError(f"Invalid motion threshold in config: {e}")

def get_temperature_threshold(config):
    try:
        temperature_threshold = int(config['TEMPERATURE']['temperature_threshold'])
        if temperature_threshold <= 0:
            raise ValueError("Temperature threshold must be positive.")
        return temperature_threshold
    except KeyError as e:
        raise ValueError(f"Missing temperature threshold in config: {e}")
    except ValueError as e:
        raise ValueError(f"Invalid temperature threshold in config: {e}")

def get_simulated_temperature():
    return 30.0

def get_cpu_temperature():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (FileNotFoundError, IOError, ValueError) as e:
        logging.warning(f"Failed to read CPU temperature: {e}. Using simulated temperature.")
        return get_simulated_temperature()

def detect_motion(frame1, frame2, roi, motion_threshold):
    try:
        roi1 = frame1[roi_y1:roi_y2, roi_x1:roi_x2]
        roi2 = frame2[roi_y1:roi_y2, roi_x1:roi_x2]
        diff = cv2.absdiff(roi1, roi2)
        thresh = cv2.threshold(diff, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        motion_pixels = 0
        for contour in contours:
            if cv2.contourArea(contour) < 500:
                continue
            motion_pixels += cv2.contourArea(contour)
        return motion_pixels > (roi_x2 * roi_y2 * motion_threshold / 10000.0)
    except Exception as e:
        logging.error(f"Error during motion detection: {e}")
        return False

def save_snapshot(frame, timestamp, directory):
    try:
        os.makedirs(directory, exist_ok=True)
        filename = os.path.join(directory, f"motion_{timestamp}.jpg")
        success = cv2.imwrite(filename, frame)
        if success:
            logging.info(f"Saved snapshot: {filename}")
        else:
            logging.error(f"Failed to save snapshot: {filename}")
    except Exception as e:
        logging.error(f"Error saving snapshot: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)

    config = None
    try:
        config = load_config(CONFIG_FILE)
        roi, motion_threshold = get_roi(config), get_motion_threshold(config)
        temperature_threshold = get_temperature_threshold(config)
        simulated_temperature = config.getboolean('SIMULATED', 'temperature')
        picam2 = Picamera2()

        if not simulated_temperature:
            try:
                picam2.configure(picam2.create_preview_configuration(main={"format": 'RGB888', "size": (64, 64)}))
                picam2.start()
                time.sleep(2)
                logging.info("Camera initialized successfully.")
            except Exception as e:
                logging.error(f"Failed to initialize camera: {e}")
                return

        while running:
            try:
                frame1 = picam2.capture_array()
                if frame1 is None:
                    logging.warning("Failed to capture first frame.")
                    time.sleep(0.1)
                    continue
                time.sleep(0.1)
                frame2 = picam2.capture_array()
                if frame2 is None:
                    logging.warning("Failed to capture second frame.")
                    time.sleep(0.1)
                    continue

                if detect_motion(frame1, frame2, roi, motion_threshold):
                    logging.info("Motion detected!")
                    timestamp = time.strftime("%Y%m%d_%H%M%S")
                    save_snapshot(frame1, timestamp, SNAPSHOT_DIR)
                    time.sleep(confirnation_delay)
                    logging.info("Alert sent!")

                cpu_temp = get_cpu_temperature()
                if cpu_temp > temperature_threshold:
                    logging.warning(f"Temperature alert: CPU temperature is {cpu_temp:.1f}°C")

                time.sleep(0.1)

            except Exception as e:
                logging.error(f"Error in main loop: {e}")
                time.sleep(1)

    except FileNotFoundError as e:
        logging.error(f"File not found: {e}")
    except ValueError as e:
        logging.error(f"Invalid configuration: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if config is not None:
            try:
                picam2.stop()
                logging.info("Camera stopped.")
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

