                    print(f"Total pictures saved: {len(set(save_image(image, name) for image_path in os.listdir(IMAGE_DIR)))}")
                else:
                    print("Failed to save image. Exiting.")
                    break
            elif key == KEY_Q:
                print("Quit requested. Exiting.")
                break
    finally:
        if camera is not None and camera.isOpened():
            camera.release()
        cv2.destroyAllWindows()
        print("Resources released. Goodbye.")

if __name__ == "__main__":
    main()

