import sys
import time

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera(camera_id=0):
    """Initialize the camera with error handling."""
    try:
        camera = cv2.VideoCapture(camera_id)
        if not camera.isOpened():
            raise IOError(f"Cannot open camera {camera_id}")
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def load_face_detector(cascade_path="haarcascade_frontalface_default.xml"):
    """Load the Haar Cascade Classifier with error handling."""
    try:
        detector = cv2.CascadeClassifier(cascade_path)
        if detector.empty():
            raise IOError(f"Cannot load face cascade classifier: {cascade_path}")
        return detector
    except Exception as e:
        print(f"Error loading face detector: {e}", file=sys.stderr)
        return None

def process_frame(frame, detector):
    """Process a single frame for face detection."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        faces = detector.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5)
        return gray, faces
    except Exception as e:
        print(f"Error processing frame: {e}", file=sys.stderr)
        return None, None

def draw_face_rectangles(frame, faces):
    """Draw rectangles around detected faces."""
    try:
        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
        return frame
    except Exception as e:
        print(f"Error drawing rectangles: {e}", file=sys.stderr)
        return frame

def display_frame(frame, window_title="Real-time Face Detection"):
    """Display the frame in a named window."""
    try:
        cv2.imshow(window_title, frame)
        return True
    except Exception as e:
        print(f"Error displaying frame: {e}", file=sys.stderr)
        return False

def main():
    """Main function for real-time face detection."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = initialize_camera(0)
    if camera is None:
        sys.exit(1)

    face_detector = load_face_detector()
    if face_detector is None:
        camera.release()
        sys.exit(1)

    try:
        while _running:
            ret, frame = camera.read()
            if not ret:
                print("Failed to grab frame", file=sys.stderr)
                break

            gray, faces = process_frame(frame, face_detector)
            if gray is None:
                continue

            frame_with_rectangles = draw_face_rectangles(frame, faces)
            if frame_with_rectangles is None:
                continue

            if len(faces) > 0:
                print("Face detected!")

            if not display_frame(frame_with_rectangles):
                break

            key = cv2.waitKey(1) & 0xFF
            if key == ord('q'):
                break
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

