import asyncio
import signal
import logging
import numpy as np
import cv2
import imutils
from general import WebSocketHandler  # custom module

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class StreamingOutput:
    def __init__(self):
        self.frame = None
        self.lock = threading.Lock()

    def write(self, data):
        try:
            with self.lock:
                self.frame = data
        except Exception as e:
            logger.error(f"Error writing frame: {e}")

class CameraHandler:
    def __init__(self, detect_motion_function):
        self.detect_motion_function = detect_motion_function
        self.camera = None
        self.streams = []
        self.output = StreamingOutput()
        self.lock = threading.Lock()
        self._running = True

    def _init_camera(self):
        try:
            self.camera = cv2.VideoCapture(0)
            if not self.camera.isOpened():
                raise IOError("Cannot open webcam")
            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
            self.camera.set(cv2.CAP_PROP_FPS, 10)
            self.camera.set(cv2.CAP_PROP_CONVERT_RGB, True)
            self.camera.set(cv2.CAP_PROP_BRIGHTNESS, 0.5)
            self.camera.set(cv2.CAP_PROP_CONTRAST, 1.0)
            self.camera.set(cv2.CAP_PROP_SATURATION, 1.0)
            self.camera.set(cv2.CAP_PROP_EXPOSURE, 500)
            self.camera.set(cv2.CAP_PROP_GAIN, 1.0)
            self.camera.set(cv2.CAP_PROP_ZOOM, 1.0)
            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, 320)
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 240)
            self.camera.set(cv2.CAP_PROP_FPS, 64)
            logger.info("Camera initialized successfully")
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            self.camera = None

    def _read_frame(self):
        if not self.camera:
            return None
        try:
            ret, frame = self.camera.read()
            if not ret or frame is None:
                return None
            return frame
        except Exception as e:
            logger.error(f"Error reading frame: {e}")
            return None

    def _convert_to_gray(self, frame):
        try:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            return gray
        except Exception as e:
            logger.error(f"Error converting to grayscale: {e}")
            return None

    def _detect_motion(self, prev_frame, curr_frame):
        try:
            gray_prev = self._convert_to_gray(prev_frame)
            gray_curr = self._convert_to_gray(curr_frame)
            if gray_prev is None or gray_curr is None:
                return None
            frame_delta = cv2.absdiff(gray_prev, gray_curr)
            thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
            thresh = cv2.dilate(thresh, None, iterations=2)
            cnts, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            if cnts:
                largest = max(cnts, key=cv2.contourArea)
                (x, y, w, h) = cv2.boundingRect(largest)
                return (int(x), int(y), int(w), int(h))
            return None
        except Exception as e:
            logger.error(f"Error detecting motion: {e}")
            return None

    def _process_frame(self, frame):
        try:
            gray = self._convert_to_gray(frame)
            if gray is None:
                return None
            ret, jpeg = cv2.imencode('.jpg', frame)
            if not ret or jpeg is None:
                return None
            frame_data = jpeg.tobytes()
            return (frame_data, gray)
        except Exception as e:
            logger.error(f"Error processing frame: {e}")
            return None

    def _send_to_clients(self, data):
        try:
            if self.streams:
                self.streams[0].write(data)
        except Exception as e:
            logger.error(f"Error sending data to clients: {e}")

    def _motion_callback(self, frame):
        if frame is None:
            return
        try:
            ret, prev_frame = self._read_frame()
            if ret is None:
                return
            curr_frame, gray = self._process_frame(prev_frame)
            if gray is None:
                return
            motion = self.detect_motion_function(prev_frame, gray)
            if motion:
                logger.info(f"Motion detected: {motion}")
            self._send_to_clients(curr_frame)
        except Exception as e:
            logger.error(f"Error in motion callback: {e}")

    def run(self):
        if not self.camera:
            logger.error("Camera not initialized. Exiting.")
            return

        self._init_camera()

        if not self.has_connections():
            logger.info("No WebSocket connections. Exiting broadcast loop.")
            return

        try:
            while self._running:
                frame = self._read_frame()
                if frame is None:
                    logger.warning("Failed to read frame from camera. Retrying...")
                    continue
                self._motion_callback(frame)
        except Exception as e:
            logger.error(f"Unexpected error in main loop: {e}")
        finally:
            self.stop()

    def stop(self):
        self._running = False
        if self.camera:
            self.camera.release()
            self.camera = None
        logger.info("Camera resources released.")

async def handle_client(connection, handler):
    logger.info("New WebSocket connection established.")
    try:
        await handler.broadcast({'event': 'connect', 'id': connection})
    except Exception as e:
        logger.error(f"Error handling connection: {e}")
    finally:
        connection.close()
        logger.info("WebSocket connection closed.")

async def main():
    handler = CameraHandler(detect_motion_function=CameraHandler._detect_motion)
    loop = asyncio.get_running_loop()
    stop_event = asyncio.Event()

    def signal_handler():
        logger.info("Shutdown signal received.")
        stop_event.set()

    for sig in (signal.SIGINT, signal.SIGTERM):
        loop.add_signal_handler(sig, signal_handler)

    handler.streams = [WebSocketHandler()]
    handler.streams[0].start_listening()
    await stop_event.wait()

    try:
        await handle_client(None, handler.streams[0])
    except asyncio.CancelledError:
        pass
    finally:
        handler.stop()
        loop.close()
        logger.info("Application stopped.")

if __name__ == "__main__":
    asyncio.run(main())

