        except Exception as e:
            logger.error(f"Error converting to grayscale: {e}")
            return None

    def _detect_motion(self, prev_frame, curr_frame):
        try:
            gray_prev = self._convert_to_gray(prev_frame)
            gray_curr = self._convert_to_gray(curr_frame)
            if gray_prev is None or gray_curr is None:
                return None
            frame_delta = cv2.absdiff(gray_prev, gray_curr)
            thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
            thresh = cv2.dilate(thresh, None, iterations=2)
            cnts, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            if cnts:
                largest = max(cnts, key=cv2.contourArea)
                (x, y, w, h) = cv2.boundingRect(largest)
                return (int(x), int(y), int(w), int(h))
            return None
        except Exception as e:
            logger.error(f"Error detecting motion: {e}")
            return None

    def _process_frame(self, frame):
        try:
            gray = self._convert_to_gray(frame)
            if gray is None:
                return None
            ret, jpeg = cv2.imencode('.jpg', frame)
            if not ret or jpeg is None:
                return None
            frame_data = jpeg.tobytes()
            return (frame_data, gray)
        except Exception as e:
            logger.error(f"Error processing frame: {e}")
            return None

    def _send_to_clients(self, data):
        try:
            if self.streams:
                self.streams[0].write(data)
        except Exception as e:
            logger.error(f"Error sending data to clients: {e}")

    def _motion_callback(self, frame):
        if frame is None:
            return
        try:
            ret, prev_frame = self._read_frame()
            if ret is None:
                return
            curr_frame, gray = self._process_frame(prev_frame)
            if gray is None:
                return
            motion = self.detect_motion_function(prev_frame, gray)
            if motion:
                logger.info(f"Motion detected: {motion}")
            self._send_to_clients(curr_frame)
        except Exception as e:
            logger.error(f"Error in motion callback: {e}")

    def run(self):
        if not self.camera:
            logger.error("Camera not initialized. Exiting.")
            return

        self._init_camera()

        if not self.has_connections():
            logger.info("No WebSocket connections. Exiting broadcast loop.")
            return

        try:
            while self._running:
                frame = self._read_frame()
                if frame is None:
                    logger.warning("Failed to read frame from camera. Retrying...")
                    continue
                self._motion_callback(frame)
        except Exception as e:
            logger.error(f"Unexpected error in main loop: {e}")
        finally:
            self.stop()

    def stop(self):
        self._running = False
        if self.camera:
            self.camera.release()
            self.camera = None
        logger.info("Camera resources released.")

async def handle_client(connection, handler):
    logger.info("New WebSocket connection established.")
    try:
        await handler.broadcast({'event': 'connect', 'id': connection})
    except Exception as e:
        logger.error(f"Error handling connection: {e}")
    finally:
        connection.close()
        logger.info("WebSocket connection closed.")

async def main():
    handler = CameraHandler(detect_motion_function=CameraHandler._detect_motion)
    loop = asyncio.get_running_loop()
    stop_event = asyncio.Event()

    def signal_handler():
        logger.info("Shutdown signal received.")
        stop_event.set()

    for sig in (signal.SIGINT, signal.SIGTERM):
        loop.add_signal_handler(sig, signal_handler)

    handler.streams = [WebSocketHandler()]
    handler.streams[0].start_listening()
    await stop_event.wait()

    try:
        await handle_client(None, handler.streams[0])
    except asyncio.CancelledError:
        pass
    finally:
        handler.stop()
        loop.close()
        logger.info("Application stopped.")

if __name__ == "__main__":
    asyncio.run(main())

