import io
import logging
import numpy as np
from typing import Callable, Optional

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class CameraStreamBuffer:
    """Buffers MJPEG frames from the Raspberry Pi camera driver and forwards them to a sink."""

    def __init__(self, camera: 'CameraBase', output: Optional[io.BufferedIOBase] = None):
        self.camera = camera
        self.output = output
        self.buffer = io.BytesIO()
        self._frame_complete = False
        self._h264_type = 1

    def write(self, data: bytes) -> int:
        """Append *data* to the internal buffer and signal a complete frame when ready."""
        self.buffer.write(data)
        if data.endswith(b'\xff\xd9'):
            self._frame_complete = True
            self._h264_type = 1 if b'\xff' in data[-2:] else 0
        return len(data)

    def flush(self) -> None:
        """Forward the accumulated buffer to the output sink, ignoring I/O errors."""
        if self.output is None:
            return
        try:
            self.output.write(self.buffer.getvalue())
            self.buffer.seek(0)
            self.buffer.truncate()
        except (OSError, IOError) as e:
            logging.error('Error flushing camera buffer: %s', e)


class MotionDetectionBuffer:
    """Parses an MJPEG stream, decodes each JPEG, and invokes a callback on motion detection."""

    def __init__(self, callback: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(callback):
            raise TypeError('callback must be callable')
        self.callback = callback
        self.buffer = io.BytesIO()
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None

    def write(self, data: bytes) -> int:
        """Parse MJPEG data, decode frames, and invoke the motion callback."""
        try:
            self.buffer.write(data)
            if data.endswith(b'\xff\xd9'):
                self.buffer.seek(0)
                jpg_bytes = self.buffer.read()
                if not jpg_bytes:
                    return 0

                raw = np.frombuffer(jpg_bytes, dtype=np.uint8)
                if raw.size < 2:
                    logging.warning('Incomplete JPEG frame received')
                    return 0

                self.buffer.seek(0)
                self.buffer.truncate()

                if raw[0:2] == b'\xff\xd8':
                    self.buffer.seek(0)
                    self.buffer.truncate()
                    self.previous_frame = self.current_frame
                    self.current_frame = np.asarray(raw, dtype=np.uint8)
                    self._process_frame()
                else:
                    self._process_frame()

            return len(data)

        except (OSError, IOError) as e:
            logging.error('Error processing camera buffer: %s', e)
            return 0
        except Exception as e:
            logging.error('Unexpected error in MotionDetectionBuffer: %s', e)
            return 0

    def _process_frame(self) -> None:
        """Decode the current frame and invoke the motion callback."""
        try:
            if self.previous_frame is not None and self.current_frame is not None:
                self.callback(self.previous_frame, self.current_frame)
            self.previous_frame = self.current_frame
            self.current_frame = None
        except Exception as e:
            logging.error('Error in motion detection callback: %s', e)


def _noop(frame1: np.ndarray, frame2: np.ndarray) -> None:
    """No-op callback for demonstration."""
    pass


def main() -> None:
    from PIL import Image
    import numpy as np

    camera = 'camera1'
    output = None

    try:
        from picamera2 import Picamera2
        from picamera2.encoders import MJPEGEncoder
        from picamera2.outputs import FileOutput
        from picamera2.controls import Controls

        picam2 = Picamera2(camera)
        config = picam2.create_video_configuration(
            main={'size': (640, 480), 'format': 'RGB888'},
            lores={'size': (320, 240), 'format': 'YUV420'},
            encode='mjpeg',
        )
        picam2.configure(config)

        output = FileOutput('stream.mjpg')
        picam2.start_recording(MJPEGEncoder(), output)
        logging.info('Camera recording started. Press Ctrl+C to stop.')

        buffer = CameraStreamBuffer(picam2, output)
        buffer.flush()

        buffer2 = MotionDetectionBuffer(_noop)

        for frame in picam2.capture_array():
            if frame is None:
                continue
            buffer2.write(frame.tobytes())

    except Exception as e:
        logging.error('Camera error: %s', e)
    finally:
        try:
            if 'picam2' in locals():
                picam2.stop_recording()
                picam2.close()
        except Exception as e:
            logging.error('Error closing camera: %s', e)


if __name__ == '__main__':
    main()

