import signal
import sys
import time

import smbus2
from ssd1306 import SSD1306_I2C

I2C_BUS = 1
BH1750_ADDR = 0x3C
BH1750_CONV_DELAY_S = 0.12
UPDATE_INTERVAL_S = 1.0

running = True
bus = None
display = None


def handle_signal(signum, frame):
    global running
    running = False


def read_bh1750_lux(bus):
    """Trigger a conversion and return lux, or None on error."""
    try:
        bus.write_byte(BH1750_ADDR, 0x01)
        time.sleep(BH1750_CONV_DELAY_S)
        data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        if raw & 0x8000:
            raw -= 1 << 16
        return raw / 1.2
    except OSError:
        return None


def lux_to_contrast(lux):
    """Map lux to display contrast byte (0-255), clamped."""
    if lux is None:
        return 0
    return max(0, min(255, int(round(lux * 255.0 / 10000.0))))


def cleanup():
    global display
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception:
            pass


def main():
    global bus, display

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        display = SSD1306_I2C(128, I2C_BUS, rotate=0)
        display.fill(0)
        display.show()
    except Exception as e:
        print(f"Error: SSD1306 display not found on bus {I2C_BUS}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    last_contrast = 0

    try:
        while running:
            lux = read_bh1750_lux(bus)
            contrast = lux_to_contrast(lux)
            if contrast != last_contrast:
                last_contrast = contrast
                try:
                    display.contrast(contrast)
                    display.show()
                except Exception as e:
                    print(f"Warning: display update failed: {e}", file=sys.stderr)
            time.sleep(UPDATE_INTERVAL_S)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

