import signal
import sys
import time
import board
import busio
import adafruit_ssd1306
from adafruit_bme280 import basic as adafruit_bme280
from adafruit_tsl2561 import TSL2561

# --- Configuration -----------------------------------------------------------
OLED_WIDTH = 128
OLED_HEIGHT = 64
UPDATE_INTERVAL_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
oled = None
i2c = None
bme280 = None
light_sensor = None
running = True


def cleanup():
    """Release every resource we hold."""
    global oled, i2c, bme280, light_sensor
    if oled is not None:
        try:
            oled.fill(0)
            oled.show()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    # bme280 and light_sensor do not hold open files or hardware handles
    # that need explicit cleanup, but we null them for clarity.


def handle_sigint(signum, frame):
    """Graceful shutdown on Ctrl-C."""
    global running
    running = False


def init_i2c():
    """Initialize the hardware I2C bus on GPIO2/GPIO3."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error: I2C bus initialization failed: {exc}", file=sys.stderr)
        return None


def init_oled(i2c_bus):
    """Initialize the SSD1306 OLED display."""
    try:
        return adafruit_ssd1306.SSD1306_I2C(
            OLED_WIDTH, OLED_HEIGHT, i2c_bus, addr=0x3C
        )
    except Exception as exc:
        print(f"Error: SSD1306 OLED initialization failed: {exc}", file=sys.stderr)
        return None


def init_bme280(i2c_bus):
    """Initialize the BME280 sensor."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(i2c_bus)
    except Exception as exc:
        print(f"Error: BME280 initialization failed: {exc}", file=sys.stderr)
        return None


def init_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return TSL2561(i2c_bus)
    except Exception as exc:
        print(f"Error: TSL2561 initialization failed: {exc}", file=sys.stderr)
        return None


def read_sensor_data(bme280_sensor, light_sensor):
    """Read temperature, humidity, pressure, and light from sensors."""
    temp = bme280_sensor.temperature
    hum = bme280_sensor.humidity
    pres = bme280_sensor.pressure
    lux = light_sensor.lux
    return temp, hum, pres, lux


def display_data(oled, temp, hum, pres, lux):
    """Render sensor data on the OLED display."""
    oled.fill(0)
    oled.text(f"Temp: {temp:.1f} C", 0, 0, 1)
    oled.text(f"Hum: {hum:.1f} %", 0, 16, 1)
    oled.text(f"Pres: {pres:.1f} hPa", 0, 32, 1)
    oled.text(f"Light: {lux:.1f} lux", 0, 48, 1)
    oled.show()


def main():
    global oled, i2c, bme280, light_sensor, running

    signal.signal(signal.SIGINT, handle_sigint)

    i2c = init_i2c()
    if i2c is None:
        sys.exit(1)

    oled = init_oled(i2c)
    if oled is None:
        sys.exit(1)

    bme280 = init_bme280(i2c)
    if bme280 is None:
        sys.exit(1)

    light_sensor = init_light_sensor(i2c)
    if light_sensor is None:
        sys.exit(1)

    print("Sensors initialized. Reading data every 1 second (Ctrl-C to quit).")

    try:
        while running:
            try:
                temp, hum, pres, lux = read_sensor_data(bme280, light_sensor)
                display_data(oled, temp, hum, pres, lux)
            except Exception as exc:
                # Transient I2C read error: log and continue rather than crash
                print(f"Warning: sensor read error: {exc}", file=sys.stderr)
            time.sleep(UPDATE_INTERVAL_S)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

