            raise RuntimeError("Sensor returned None for temperature or humidity")
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 sensors often throw checksum or timing errors; retry once
        time.sleep(0.5)
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is None or humidity is None:
                raise RuntimeError("Sensor still returned None")
            return temperature, humidity
        except RuntimeError as retry_e:
            print(f"DHT22 read error (attempt 1): {e}", file=sys.stderr)
            return None, None
        except Exception as e:
            print(f"Unexpected DHT22 error: {e}", file=sys.stderr)
            return None, None
    except Exception as e:
        print(f"Error reading DHT22 sensor: {e}", file=sys.stderr)
        return None, None

def display_data(lcd, temperature, humidity):
