    if i2c_bus is None:
        print("Exiting due to I2C initialization failure.", file=sys.stderr)
        sys.exit(1)

    lcd = initialize_lcd(i2c_bus)
    if lcd is None:
        print("Exiting due to LCD initialization failure.", file=sys.stderr)
