import smbus
import time
import signal
import sys

# TSL2561 constants
TSL2561_ADDR = 0x29
TSL2561_REG_CONTROL = 0x00
TSL2561_REG_DATA0 = 0x01
TSL2561_REG_DATA1 = 0x02
TSL2561_REG_ID = 0x0F

TSL2561_CONTROL_ENABLE = 0x04
TSL2561_CONTROL_INTEGRATIONTIME_101MS = 0x00
TSL2561_CONTROL_GAIN_1X = 0x00
TSL2561_CONTROL_SHUTDOWN = 0x10

# SSD1306 constants
SSD1306_WIDTH = 128
SSD1306_HEIGHT = 64
SSD1306_I2C_ADDR = 0x3C
SSD1306_REG_DISPLAYOFF = 0x00
SSD1306_REG_DISPLAYON = 0x00
SSD1306_REG_SETCONTRAST = 0x81
SSD1306_REG_SETDISPLAYOFFSET = 0x20
SSD1306_REG_SETCOLSTART = 0x21
SSD1306_REG_COLSET = 0x22
SSD1306_REG_CHARENSET = 0x81
SSD1306_REG_CHARDISP = 0x82
SSD1306_REG_MEMORYMODE = 0x20
SSD1306_REG_SETCOMPINS = 0x3A
SSD1306_REG_COMSCANDEC = 0x00
SSD1306_REG_SLEEPOUT = 0x10
SSD1306_REG_SLPOUT = 0x00

# Globals for cleanup
_running = True
_bus = None
_oled = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _oled, _bus
    if _oled is not None:
        try:
            _oled.write(0x00, [0x00, 0x00, 0x00, 0x00])
        except Exception:
            pass
    if _bus is not None:
        try:
            _bus.write_byte_data(TSL2561_ADDR, TSL2561_REG_CONTROL, TSL2561_CONTROL_SHUTDOWN)
        except Exception:
            pass
        try:
            _bus.close()
        except Exception:
            pass


def _read_sensor_data(bus):
    """Read raw data bytes from the TSL2561 and return (data0, data1)."""
    try:
        data0 = bus.read_byte_data(TSL2561_ADDR, TSL2561_REG_DATA0)
        data1 = bus.read_byte_data(TSL2561_ADDR, TSL2561_REG_DATA1)
        return data0, data1
    except OSError as e:
        raise RuntimeError(f"TSL2561 read failed: {e}") from e


def _calculate_lux(data0, data1):
    """Compute lux from raw TSL2561 data using the standard piecewise formula."""
    if data0 == 0:
        return 0.0
    if data0 & 0x1:
        if data1 == 0:
            return 0.0
        if data0 & 0x3:
            return 0.0
        if data0 & 0x7:
            return 0.0
        return 0.0
    if data1 == 0:
        return 0.0
    if data0 & 0x1:
        return 0.0
    if data0 & 0x2:
        return 0.0
    if data0 & 0x4:
