import signal
import sys
import time

import RPi.GPIO as GPIO

# --- Pin assignments (BCM numbering) ---
TRIG_PIN = 17
ECHO_PIN = 27
LED_PIN = 22

# --- Constants ---
SPEED_OF_SOUND_CM_S = 34300.0
DISTANCE_FACTOR = SPEED_OF_SOUND_CM_S / 2.0  # round trip
MAX_DISTANCE_CM = 400.0
MIN_DISTANCE_CM = 2.0
SETTLE_DELAY_S = 0.00005
ECHO_TIMEOUT_S = 0.03
MEASUREMENT_DELAY_S = 0.5
TRIGGER_PULSE_S = 1e-5

# --- Globals for cleanup ---
_running = True
_gpio_ready = False


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _gpio_ready
    if _gpio_ready:
        try:
            GPIO.output(LED_PIN, GPIO.LOW)
        except Exception:
            pass
        try:
            GPIO.cleanup()
        except Exception:
            pass
        _gpio_ready = False


def _safe_gpio_setup():
    global _gpio_ready
    GPIO.setwarnings(False)
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(TRIG_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(ECHO_PIN, GPIO.IN)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    _gpio_ready = True


def _safe_gpio_output(pin, state):
    try:
        GPIO.output(pin, state)
    except Exception as exc:
        raise RuntimeError(f"Failed to set GPIO{pin} to {state}: {exc}") from exc


def _safe_gpio_input(pin):
    try:
        return GPIO.input(pin)
    except Exception as exc:
        raise RuntimeError(f"Failed to read GPIO{pin}: {exc}") from exc


def measure_distance():
    """
    Trigger the HC-SR04 and return distance in cm, or None on timeout / error.
    """
    # Ensure trigger is low before starting
    _safe_gpio_output(TRIG_PIN, GPIO.LOW)
    time.sleep(SETTLE_DELAY_S)

    # Send 10 µs trigger pulse
    _safe_gpio_output(TRIG_PIN, GPIO.HIGH)
    time.sleep(TRIGGER_PULSE_S)
    _safe_gpio_output(TRIG_PIN, GPIO.LOW)

    # Wait for echo to rise (with timeout)
    deadline = time.time() + ECHO_TIMEOUT_S
    while _safe_gpio_input(ECHO_PIN) == GPIO.LOW:
        if time.time() > deadline:
            return None

    pulse_start = time.time()

    # Wait for echo to fall
    deadline = time.time() + ECHO_TIMEOUT_S
    while _safe_gpio_input(ECHO_PIN) == GPIO.HIGH:
        if time.time() > deadline:
            return None

    pulse_end = time.time()
    pulse_duration = pulse_end - pulse_start

    distance = (pulse_duration * DISTANCE_FACTOR) / 2.0
    return round(distance, 2)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _safe_gpio_setup()
    except Exception as exc:
        print(f"GPIO initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            distance = measure_distance()

            if distance is None:
                print("Warning: echo timeout — sensor not responding or out of range.")
                _safe_gpio_output(LED_PIN, GPIO.LOW)
            else:
                print(f"Distance: {distance} cm")

                if distance < 20:
                    _safe_gpio_output(LED_PIN, GPIO.HIGH)
                else:
                    _safe_gpio_output(LED_PIN, GPIO.LOW)

            time.sleep(MEASUREMENT_DELAY_S)
    except RuntimeError as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

