import time
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x40
DHT20_STATUS_REG = 0x7e
DHT20_MEASURE_REG = 0x74
DHT20_POWER_UP_DELAY = 0.5
DHT20_MEASURE_DELAY = 0.1
DHT20_MAX_RETRIES = 5
DHT20_RETRY_DELAY = 2.0

DHT20_STATUS_MEASURE_READY = 0x00
DHT20_STATUS_MEASURE_IN_PROGRESS = 0x80
DHT20_STATUS_ERROR = 0x00
DHT20_STATUS_NO_ERROR = 0x00

DHT20_HUMIDITY_COEFFICIENT = 0x100
DHT20_TEMPERATURE_COEFFICIENT = 0x200

DHT20_HUMIDITY_MASK = 0x8000
DHT20_TEMPERATURE_MASK = 0x0000
DHT20_TEMP_SHIFT = 12
DHT20_HUMIDITY_SHIFT = 8

DHT20_HUMIDITY_BITS = 20
DHT20_TEMPERATURE_BITS = 20


class DHT20:
    def __init__(self, i2c_bus=1):
        self.i2c_bus_num = i2c_bus
        self.bus = None
        try:
            self.bus = smbus2.SMBus(self.i2c_bus)
            time.sleep(DHT20_POWER_UP_DELAY)
            status = self._read_register(DHT20_STATUS_REG, 1)[0]
            if (status & DHT20_STATUS_MEASURE_READY) != DHT20_STATUS_NO_ERROR:
                raise RuntimeError(f"DHT20 not ready (status=0x{status:02x})")
            logging.info("DHT20 initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing DHT20: {e}")
            self.close()
            raise

    def _read_register(self, register, length):
        if not self.bus:
            raise RuntimeError("I2C bus not initialized.")
        try:
            return self.bus.read_i2c_block_data(DHT20_I2C_ADDRESS, register, length)
        except Exception as e:
            logging.error(f"I2C read error at register 0x{register:02x}: {e}")
            raise

    def _calculate_crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0xA1) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_raw_data(self):
        data = self._read_register(DHT20_MEASURE_REG, 7)
        if len(data) != 7:
            raise RuntimeError(f"Expected 7 bytes from DHT20, got {len(data)}.")

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0x1FFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        humidity = humidity_raw / DHT20_HUMIDITY_COEFFICIENT
        temperature = temperature_raw / DHT20_TEMPERATURE_COEFFICIENT

        return temperature, humidity

    def read(self):
        for attempt in range(1, DHT20_MAX_RETRIES + 1):
            try:
                status = self._read_register(DHT20_STATUS_REG, 1)[0]
                if (status & DHT20_STATUS_MEASURE_READY) == DHT20_STATUS_NO_ERROR:
                    temperature, humidity, crc_error = self._read_raw_data()
                    crc = self._calculate_crc8(data[:6])
                    if crc != self._calculate_crc8(data[:6]):
                        logging.warning(f"CRC mismatch: calculated 0x{crc:02x}, received 0x{crc_error:02x}")
                        return False, humidity, crc_error
                    logging.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                    return True, humidity, False
                if status & DHT20_STATUS_MEASURE_IN_PROGRESS:
                    time.sleep(DHT20_MEASURE_DELAY)
                else:
                    logging.warning(f"DHT20 status error (attempt {attempt}/{DHT20_MAX_RETRIES}): 0x{status:02x}")
            except Exception as e:
                logging.error(f"Error reading DHT20 (attempt {attempt}/{DHT20_MAX_RETRIES}): {e}")
            if attempt < DHT20_MAX_RETRIES:
                time.sleep(DHT20_RETRY_DELAY)
        logging.error("Failed to read DHT20 after all retries.")
        return False, None, True

    def close(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

    def __del__(self):
        self.close()


if __name__ == "__main__":
    try:
        dht20 = DHT20(i2c_bus=1)
        temperature, humidity, crc_error = dht20.read()
        if temperature is not None and humidity is not None and not crc_error:
            print(f"Temperature: {temperature:.2f}°C")
            print(f"Humidity: {humidity:.2f}%")
        else:
            print("Failed to read DHT20.")
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if 'dht20' in locals():
            dht20.close()

