"""Greenhouse control system for Raspberry Pi.

Controls 433 MHz PT2262-style outlets via a 433 MHz transmitter and reads
a DHT22 sensor on GPIO4.  Uses asyncio for concurrency and a rotating log
file.  All GPIO access is performed via the gpiozero library.
"""

import asyncio
import json
import logging
import logging.handlers
import signal
import sys
import time
from pathlib import Path

import gpiozero
from gpiozero import DigitalOutputDevice

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
LOG_FILE = "greenhouse.log"
LOG_MAX_BYTES = 1_048_576  # 1 MB
LOG_BACKUP_COUNT = 5

logger = logging.getLogger("greenhouse")
logger.setLevel(logging.INFO)
handler = logging.handlers.RotatingFileHandler(
    LOG_FILE, maxBytes=LOG_MAX_BYTES, backupCount=LOG_BACKUP_COUNT
)
formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
handler.setFormatter(formatter)
logger.addHandler(handler)

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
shutdown_event = asyncio.Event()
transmitter: DigitalOutputDevice | None = None
dht22_sensor: DigitalOutputDevice | None = None
outlet_codes: dict[str, dict] = {}
config: dict = {}
running = True


def load_config(path: str = "greenhouse_config.json") -> dict:
    """Load and validate greenhouse_config.json, falling back to defaults."""
    global config
    try:
        with open(path, "r") as f:
            loaded = json.load(f)
