            config["outlet_configurations"] = {}
        if "system_code" not in config["outlet_configurations"]:
            config["outlet_configurations"]["system_code"] = "10101"
        if "unit_codes" not in config["outlet_configurations"]:
            config["outlet_configurations"]["unit_codes"] = ["1", "2", "3"]
        if "transmitter_pin" not in config["gpio_transmitter_pin"]:
            config["gpio_transmitter_pin"] = 17
        if "dht22_pin" not in config["gpio_dht22_pin"]:
            config["gpio_dht22_pin"] = 4
        if "transmitter_pulse_width" not in config:
            config["transmitter_pulse_width"] = 300
        if "transmitter_retries" not in config:
            config["transmitter_retries"] = 3
        if "transmitter_retries_delay" not in config:
            config["transmitter_retries_delay"] = 0.1
        if "transmitter_debounce_delay" not in config:
            config["transmitter_debounce_delay"] = 0.5
        if "dht22_retry_delay" not in config:
            config["dht22_retry_delay"] = 2.0
        if "dht22_retry_count" not in config:
            config["dht22_retry_count"] = 3
        if "dht22_read_interval" not in config:
            config["dht22_read_interval"] = 60
        if "log_file" not in config:
            config["log_file"] = LOG_FILE
        if "transmitter_pin" not in config["gpio_transmitter_pin"]:
            config["gpio_transmitter_pin"] = 17
        if "dht22_pin" not in config["gpio_dht22_pin"]:
            config["gpio_dht22_pin"] = 4
        if "transmitter_pulse_width" not in config:
            config["transmitter_pulse_width"] = 300
        if "transmitter_retries" not in config:
            config["transmitter_retries"] = 3
        if "transmitter_retries_delay" not in config:
            config["transmitter_retries_delay"] = 0.1
        if "transmitter_debounce_delay" not in config:
            config["transmitter_debounce_delay"] = 0.5
        if "dht22_retry_delay" not in config:
