        if "dht22_read_interval" not in config:
            config["dht22_read_interval"] = 60
        if "log_file" not in config:
            config["log_file"] = LOG_FILE
        return config
    except (json.JSONDecodeError, OSError) as e:
        logger.warning("Config load failed (%s); using defaults.", e)
        config = {}
    return config


def validate_config(config: dict) -> None:
    """Validate that required config keys exist."""
    required = [
        "gpio_transmitter_pin", "gpio_dht22_pin",
        "dht22_read_interval", "log_file",
        "outlet_configurations", "system_code",
        "unit_codes", "transmitter_pin",
        "transmitter_pulse_width", "transmitter_retries",
        "transmitter_retries_delay", "transmitter_debounce_delay",
        "dht22_retry_delay", "dht22_retry_count",
        "dht22_read_interval", "log_file",
