    transmitter: DigitalOutputDevice, pulse_width: float
) -> None:
    """Send a single 433 MHz pulse (long-high + short-low) with the given width."""
    half = pulse_width / 2.0
    transmitter.on()
    time.sleep(half)
    transmitter.off()
    time.sleep(half)


def send_transmitter_code(
    transmitter: DigitalOutputDevice, code: str, outlet_name: str
) -> bool:
    """Send a PT2262-style code to the given outlet with retries and debounce."""
    if outlet_name not in outlet_codes:
        logger.error("Outlet '%s' not configured.", outlet_name)
