        return False
    code = outlet_codes[outlet_name]["system_code"]
    unit_codes = outlet_codes[outlet_name]["unit_codes"]
    state = "1" if outlet_name == "Outlet1" else "0"
    sync = "1"
    for attempt in range(config["transmitter_retries"]):
        try:
            for bit in code:
                if bit == "1":
                    send_transmitter_pulse(transmitter, config["transmitter_pulse_width"])
                else:
                    send_transmitter_pulse(transmitter, config["transmitter_pulse_width"] / 2.0)
                for unit in unit_codes:
                    if unit == state:
                        break
                else:
                    send_transmitter_pulse(transmitter, config["transmitter_pulse_width"] / 2.0)
            send_transmitter_pulse(transmitter, config["transmitter_pulse_width"])
            send_transmitter_pulse(transmitter, config["transmitter_pulse_width"])
            logger.info("Outlet '%s' turned %s", outlet_name, state)
            return True
        except Exception as e:
            logger.error("Error sending code to '%s': %s", outlet_name, e)
            if attempt < config["transmitter_retries"] - 1:
                time.sleep(config["transmitter_retries_delay"])
            else:
                logger.error("Max retries reached for '%s'.", outlet_name)
                return False
    return False


def read_dht22_sensor(dht22_sensor: DigitalOutputDevice) -> tuple:
    """Read temperature and humidity from the DHT22 sensor with retries."""
    for attempt in range(config["dht22_retry_count"]):
        try:
            dht22_sensor.on()
            time.sleep(0.018)  # DHT22 requires >=18 ms low
            data = dht22_sensor.read()
            if data is not None:
                temp = data.temperature
                hum = data.humidity
                if temp is not None and hum is not None:
                    return temp, hum
                logger.warning("DHT22 returned None values.")
            else:
                logger.warning("DHT22 read returned None.")
        except (RuntimeError, OSError) as e:
            logger.warning("DHT22 read error (attempt %d/%d): %s", attempt + 1, config["dht22_retry_count"], e)
        except Exception as e:
            logger.error("Unexpected DHT22 error: %s", e)
        time.sleep(config["dht22_retry_delay"])
    logger.error("DHT22 read failed after %d attempts.", config["dht22_retry_count"])
    return None, None


async def sensor_reading_task(dht22_sensor: DigitalOutputDevice) -> None:
    """Asynchronous task to read the DHT22 sensor at a configurable interval."""
    while running:
        try:
            temp, hum = read_dht22_sensor(dht22_sensor)
            if temp is not None and hum is not None:
                logger.info("Temperature: %.1f C, Humidity: %.1f %%", temp, hum)
            else:
                logger.warning("DHT22 reading failed; skipping this cycle.")
        except Exception as e:
            logger.error("Sensor reading task error: %s", e)
        await asyncio.sleep(config["dht22_read_interval"])


async def control_outlet_task(transmitter: DigitalOutputDevice) -> None:
    """Asynchronous task to control remote outlets via the 433 MHz transmitter."""
    while running:
        try:
            await asyncio.sleep(config["transmitter_debounce_delay"])
            for outlet_name in outlet_codes:
                if outlet_name == "Outlet1":
                    await send_transmitter_code(transmitter, "1", outlet_name)
                elif outlet_name == "Outlet2":
                    await send_transmitter_code(transmitter, "0", outlet_name)
                elif outlet_name == "Outlet3":
                    await send_transmitter_code(transmitter, "0", outlet_name)
            logger.info("Outlet control loop completed.")
        except Exception as e:
            logger.error("Outlet control task error: %s", e)
        await asyncio.sleep(1)


def cleanup() -> None:
    """Release GPIO resources and shut down logging."""
    global running, transmitter, dht22_sensor
    running = False
    logger.info("Cleaning up GPIO and logging...")
    if transmitter is not None:
        try:
            transmitter.close()
        except Exception:
            pass
        transmitter = None
    if dht22_sensor is not None:
        try:
            dht22_sensor.close()
        except Exception:
            pass
        dht22_sensor = None
    logging.shutdown()


def signal_handler(sig, frame) -> None:
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logger.info("Received signal %s; shutting down.", sig)
    cleanup()
    sys.exit(0)


def main() -> None:
    global running
    config = load_config()
    try:
        validate_config(config)
    except ValueError as e:
        print(f"Configuration error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        setup_gpio(config)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        asyncio.create_task(sensor_reading_task(dht22_sensor))
        asyncio.create_task(control_outlet_task(transmitter))
        logger.info("Greenhouse control system started.")
        while running:
            await asyncio.sleep(1)
    except Exception as e:
        logger.error("Main loop error: %s", e)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

