import signal
import sys
import time
import logging

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("dht20")

DHT20_I2C_ADDR = 0x40
DHT20_STATUS_REG = 0x7e
DHT20_MEASURE_REG = 0x74
DHT20_TIMEOUT = 0.1
DHT20_POLL_INTERVAL = 0.01

DHT20_STATUS_OK = 0x00
DHT20_STATUS_ERROR = 0x80
DHT20_STATUS_MEAS_INIT = 0x20
DHT20_STATUS_MEAS_READY = 0x00
DHT20_STATUS_MEAS_WAIT = 0x10

DHT20_DATA_LEN = 8
DHT20_CRC_POLY = 0x31
DHT20_CRC_INIT = 0x00


class DHT20:
    def __init__(self, i2c_bus=1):
        self._bus = None
        self._addr = DHT20_I2C_ADDR
        self._crc_error = False
        try:
            self._bus = self._open_bus(i2c_bus)
            if self._bus is None:
                raise IOError("Failed to open I2C bus")
            self._verify_sensor()
        except Exception as exc:
            log.error("DHT20 initialization failed: %s", exc)
            self._bus = None

    def _open_bus(self, bus_num):
        try:
            import smbus
            return smbus.SMBus(bus_num)
        except Exception as exc:
            log.error("Failed to open I2C bus %d: %s", bus_num, exc)
            return None

    def _verify_sensor(self):
        try:
            data = self._read_register(DHT20_STATUS_REG, 1)
            if data is None:
                raise IOError("Sensor not responding to status register")
            if data[0] != DHT20_STATUS_OK:
                if data[0] == DHT20_STATUS_ERROR:
                    raise IOError("Sensor reported an error")
                if data[0] == DHT20_STATUS_MEAS_INIT:
                    log.info("Sensor in measurement-init state")
                else:
                    log.warning("Sensor not ready (status 0x%02x)", data[0])
                return
            log.info("Sensor verified")
        except Exception as exc:
            log.error("Sensor verification failed: %s", exc)
            self._bus = None

    def _read_register(self, reg, length):
        if self._bus is None:
            return None
        try:
            return self._bus.read_i2c_block_data(self._addr, reg, length)
        except Exception as exc:
            log.error("I2C read error at register 0x%02x: %s", reg, exc)
            return None

    def _write_register(self, reg, value):
        if self._bus is None:
            return False
        try:
            self._bus.write_i2c_block_data(self._addr, reg, [value])
            return True
        except Exception as exc:
            log.error("I2C write error at register 0x%02x: %s", reg, exc)
            return False

    def measure(self):
        if self._bus is None:
            log.error("I2C bus not initialized")
            return None, None, True

        try:
            self._write_register(DHT20_MEASURE_REG, 0)
        except Exception as exc:
            log.error("Failed to initiate measurement: %s", exc)
            return None, None, True

        deadline = time.monotonic() + DHT20_TIMEOUT
        while True:
            data = self._read_register(DHT20_STATUS_REG, 1)
            if data is None:
                return None, None, True
            if data[0] == DHT20_STATUS_MEAS_READY:
                break
            if data[0] == DHT20_STATUS_MEAS_WAIT:
                time.sleep(DHT20_POLL_INTERVAL)
            if time.monotonic() >= deadline:
                log.error("Measurement timed out")
                return None, None, True
        return self._read_raw_data()

    def _read_raw_data(self):
        data = self._read_register(DHT20_STATUS_REG, DHT20_DATA_LEN)
        if data is None:
            return None, None, True
        if data[0] != DHT20_STATUS_OK:
            return None, None, True
        if len(data) < 6:
            return None, None, True
        humidity_raw = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
        temp_raw = (data[3] & 0x0f) << 16 | (data[4] << 8) | data[5]
        crc_error = self._check_crc(humidity_raw, temp_raw)
        if crc_error:
            return None, None, True
        temp_c = temp_raw / 5242.88
        humidity = (humidity_raw / 2**20) * 100.0
        return temp_c, humidity, False

    def _check_crc(self, data, crc_init=0):
        crc = crc_init
        for byte in data[:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20_CRC_POLY) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc == data[6]

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except Exception:
                pass
            self._bus = None


_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    log.info("Signal %d received, shutting down", signum)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    sensor = DHT20(i2c_bus=1)
    try:
        temp, hum, err = sensor.measure()
        if err:
            log.error("Measurement failed: %s", err)
        else:
            print(f"Temperature: {temp:.2f} C  Humidity: {hum:.2f} %")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

