import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants for sensor addresses
BME280_I2C_ADDRESS = 0x77
TSL2591_I2C_ADDRESS = 0x5C

# Global flag for graceful shutdown
running = True


def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    running = False


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm devices are present
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()
        if TCA9548A_I2C_ADDRESS not in devices:
            print(f"Error: TCA9548A multiplexer not found at 0x{TCA9548A_I2C_ADDRESS:02X}")
            return None
        if BME280_I2C_ADDRESS not in devices:
            print(f"Error: BME280 not found at 0x{BME280_I2C_ADDRESS:02X}")
            return None
        if TSL2591_I2C_ADDRESS not in devices:
            print(f"Error: TSL2591 not found at 0x{TSL2591_I2C_ADDRESS:02X}")
            return None
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_bme280(multiplexer):
    """Initialize the BME280 sensor."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=BME280_I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        return None


def initialize_tsl2591(multiplexer):
    """Initialize the TSL2591 sensor."""
    try:
        return adafruit_tsl2591.TSL2591(multiplexer[1])
    except Exception as e:
        print(f"Error initializing TSL2591: {e}")
        return None


def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Read data from BME280 and TSL2591 sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None


def main():
    """Main function to read and display sensor data."""
    signal.signal(signal.SIGINT, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(multiplexer)
    if bme280_sensor is None:
        return

    tsl2591_sensor = initialize_tsl2591(multiplexer)
    if tsl2591_sensor is None:
        return

    print("Starting sensor readings. Press Ctrl+C to exit.")

    try:
        while running:
            temperature, humidity, light_intensity = read_sensor_data(
                bme280_sensor, tsl2591_sensor
            )

            if temperature is not None and humidity is not None and light_intensity is not None:
                print(f"Temperature: {temperature:.2f} C")
                print(f"Humidity: {humidity:.2f} %")
                print(f"Light Intensity: {light_intensity:.2f} lux")
            else:
                print("Failed to read sensor data.")

            time.sleep(2)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("\nExiting program.")


if __name__ == "__main__":
    main()

