db_conn = None
db_cursor = None


def signal_handler(signum, frame):
    global running
    logger.info('Signal received, shutting down...')
    running = False


def setup_gpio():
    global led
    if gpiozero is None:
        logger.warning('gpiozero not available; LED control disabled.')
        return
    try:
        led = gpiozero.LED(LED_PIN)
        led.off()
        logger.info(f'GPIO {LED_PIN} setup successful (gpiozero).')
    except Exception as e:
        logger.error(f'GPIO setup failed: {e}')
        led = None


def setup_database():
    global db_conn, db_cursor
    try:
        db_conn = sqlite3.connect(DATABASE_NAME)
        db_cursor = db_conn.cursor()
        db_cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                vibration REAL,
                temperature REAL
            )
        ''')
        db_conn.commit()
        logger.info('Database setup successful.')
    except sqlite3.Error as e:
        logger.error(f'Database setup failed: {e}')
        raise


def simulate_vibration():
    return round(random.uniform(0.1, 0.9), 2)


def simulate_temperature():
    return round(random.uniform(30.0, 70.0), 2)


def calculate_degradation(vibration_data, temperature_data):
    if not vibration_data or not temperature_data:
        return 0.0, 0.0
    avg_vibration = sum(vibration_data) / len(vibration_data)
    avg_temp = sum(temperature_data) / len(temperature_data)
    return avg_vibration, avg_temp


def calculate_rul(vibration_avg, temp_avg):
    return 10000.0 / (1.0 + vibration_avg + temp_avg)


def check_alerts(vibration_avg, temp_avg):
    if vibration_avg > 0.6 or temp_avg > 60.0:
        return True, vibration_avg, temp_avg
    return False, vibration_avg, temp_avg


def store_data(vibration, temperature):
    if db_cursor is None or db_conn is None:
        return
    try:
        db_cursor.execute('''
            INSERT INTO sensor_data (vibration, temperature)
            VALUES (?, ?)
        ''', (vibration, temperature))
        db_conn.commit()
    except sqlite3.Error as e:
        logger.error(f'Data storage failed: {e}')


def update_led(state):
    if led is None:
        return
    try:
        if state:
            led.on()
        else:
            led.off()
    except Exception as e:
        logger.error(f'LED control failed: {e}')


def cleanup():
    global db_conn, led
    logger.info('Cleaning up resources...')
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None
    if db_conn is not None:
        try:
            db_conn.close()
        except Exception:
            pass
        db_conn = None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    setup_gpio()
    setup_database()

    vibration_data = []
    temperature_data = []

    try:
        for i in range(ITERATIONS):
            if not running:
                break

            vibration = simulate_vibration()
            temperature = simulate_temperature()

            if not (0.0 <= vibration <= 1.0):
                logger.warning(f'Invalid vibration value: {vibration}')
                vibration = 0.0
            if not (30.0 <= temperature <= 70.0):
                logger.warning(f'Invalid temperature value: {temperature}')
                temperature = 50.0

            vibration_data.append(vibration)
            temperature_data.append(temperature)

            if len(vibration_data) > VIBRATION_WINDOW:
                vibration_data.pop(0)
            if len(temperature_data) > TEMP_WINDOW:
                temperature_data.pop(0)

            degradation, vibration_avg, temp_avg = calculate_degradation(vibration_data, temperature_data)
            rul = calculate_rul(vibration_avg, temp_avg)

            alert, alert_vibration, alert_temp = check_alerts(vibration_avg, temp_avg)

            if alert:
                logger.warning(f'Alert: RUL={rul:.2f}h, V={vibration_avg:.2f}, T={alert_temp:.2f}')
                update_led(True)
                store_data(vibration, temperature)
                update_led(False)

            time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        logger.error(f'Unexpected error: {e}')
    finally:
        cleanup()


if __name__ == '__main__':
    main()

