#!/usr/bin/env python3
"""
CPU temperature monitor for Raspberry Pi 4 Model B.

Reads the on-board thermal sensor every 5 seconds, prints the value to
two decimal places, and handles missing thermal files, I/O errors, and
KeyboardInterrupt cleanly.
"""

import time
import sys

try:
    from libcamera import CPUTemperature
except ImportError:
    CPUTemperature = None


def read_cpu_temp() -> float:
    """
    Lazily create the CPUTemperature object and read the CPU temperature.

    Returns the temperature in degrees Celsius, or None on any error.
    """
    if CPUTemperature is None:
        print("Error: libcamera is not installed or not importable.")
        return None

    try:
        sensor = CPUTemperature()
        return float(sensor.get_temperature())
    except FileNotFoundError:
        print("Error: Thermal sensor file not found.")
        return None
    except Exception as exc:
        print(f"Error reading CPU temperature: {exc}")
        return None


def main() -> int:
    print("Starting CPU temperature monitoring...")

    try:
        while True:
            cpu_temp = read_cpu_temp()
            if cpu_temp is not None:
                print(f"CPU Temperature: {cpu_temp:.2f} °C")
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram terminated")
        return 0
    except Exception as exc:
        print(f"An unexpected error occurred: {exc}")
        return 1


if __name__ == "__main__":
    sys.exit(main())

