import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 18
PWM_FREQ = 50.0
POLL_INTERVAL = 1.0

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
        fan = None

def handle_signal(signum, frame):
    global running
    running = False

def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def main():
    global fan
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Error initializing PWM on BCM pin {FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"PWM fan control started on BCM pin {FAN_PIN} at {PWM_FREQ} Hz.")
    print("Press Ctrl+C to exit.\n")

    try:
        while running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = temp / 1000.0
                fan.value = duty
                print(f"CPU Temp: {temp:.1f}C  |  Fan Duty: {duty*100:.0f}%")
            else:
                print("Skipping iteration due to temperature read error.", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("PWM stopped and resources released.")

if __name__ == '__main__':
    main()

