import csv
import os
import signal
import sys
import time
from datetime import datetime

try:
    import serial
except ImportError:
    print("Error: pyserial is not installed. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/ttyACM0"
BAUD_RATE = 115200
TIMEOUT = 1.0
LOG_FILE = "temperature_log.csv"

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
            write_timeout=timeout,
        )
        if not ser.is_open:
            print(f"Error: serial port {port} did not open.", file=sys.stderr)
            return None
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening {port}: {e}", file=sys.stderr)
        return None

def read_temperature(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        return ser.read_temperature()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading temperature: {e}", file=sys.stderr)
        return None

def convert_to_fahrenheit(celsius):
    return (celsius * 9.0 / 5.0) + 32.0

def append_to_log(log_file, timestamp, celsius, fahrenheit):
    try:
        with open(log_file, "a", newline="") as f:
            writer = csv.writer(f)
            if f.tell() == 0:
                writer.writerow(["Timestamp", "Temperature_C", "Temperature_F"])
            writer.writerow([timestamp, fahrenheit, celsius])
    except OSError as e:
        print(f"Error writing to log file {log_file}: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        print("Failed to initialize serial communication. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            celsius = read_temperature(ser)
            if celsius is not None:
                fahrenheit = convert_to_fahrenheit(celsius)
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                append_to_log(LOG_FILE, timestamp, celsius, fahrenheit)
                print(f"Logged: {timestamp}  {celsius:.2f}°C  {fahrenheit:.2f}°F")
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

