        print(f"Warning: Invalid humidity reading: {humidity:.2f}%.". Discarding.")
        return False
    return True

def calculate_moving_average(data, window_size=5):
    if not data:
        return None
    if len(data) > window_size:
        data = data[-window_size:]
    return sum(data) / len(data)

def generate_simulated_data():
    temperature = 25 + (time.time() % 10)
    humidity = 65 + (time.time() % 15)
    return temperature, humidity

def send_webhook(url, payload, max_retries=3):
    for attempt in range(max_retries):
        try:
            data = json.dumps(payload).encode('utf-8')
            req = urllib.request.Request(url, data=data, headers={'Content-Type': 'application/json'})
            with urllib.request.urlopen(req, timeout=10) as response:
                if 200 <= response.status < 300:
                    print(f"Webhook sent successfully. Status: {response.status}")
                    return True
                else:
                    print(f"Webhook failed with status: {response.status}")
        except urllib.error.URLError as e:
            print(f"Webhook request failed: {e}")
        except Exception as e:
            print(f"Webhook error: {e}")
        if attempt < max_retries - 1:
            print(f"Retrying in {2**attempt} seconds...")
            time.sleep(2**attempt)
    print("Webhook failed after multiple retries.")
    return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    webhook_url = config.get("webhook_url", "http://example.com/webhook")
    dht_pin = config.get("dht_pin", board.D4)
    sensor_interval = config.get("sensor_interval", 60)
    moving_average_window = config.get("moving_average_window", 5)

    dht_device = None
    try:
        dht_device = adafruit_dht.DHT22(dht_pin, use_pulseio=False)
        print("DHT22 sensor initialized.")
    except Exception as e:
        print(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    temperature_data = []
    humidity_data = []
    consecutive_failures = 0
    last_sensor_reading_time = time.time()

    try:
        while running:
            try:
                temperature, humidity = read_dht22(dht_device)
                temperature_data.append(temperature)
                humidity_data.append(humidity)

                if validate_data(temperature, humidity):
                    print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                    moving_average_temperature = calculate_moving_average(temperature_data)
                    moving_average_humidity = calculate_moving_average(humidity_data)

                    if moving_average_temperature is not None and moving_average_humidity is not None:
                        payload = {
                            "timestamp": datetime.datetime.now().isoformat(),
                            "temperature": round(moving_average_temperature, 2),
                            "humidity": round(moving_average_humidity, 2)
                        }
                        print(f"Sending webhook with payload: {json.dumps(payload)}")
                        send_webhook(webhook_url, payload)
                    else:
                        print("Failed to calculate moving average. Skipping webhook.")
                else:
                    print("Invalid sensor data. Skipping webhook.")
                    try:
                        temperature = generate_simulated_data()
                        humidity = generate_simulated_data()
                        print(f"Using simulated data: Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                    except Exception as e:
                        print(f"Error generating simulated data: {e}")

                if moving_average_temperature is not None and moving_average_humidity is not None:
                    print(f"Moving Average Temperature: {moving_average_temperature:.2f}°C")
                    print(f"Moving Average Humidity: {moving_average_humidity:.2f}%")

                if time.time() - last_sensor_reading_time >= sensor_interval:
                    try:
                        temperature, humidity = read_dht22(dht_device)
                        temperature_data.append(temperature)
                        humidity_data.append(humidity)
                        moving_average_temperature = calculate_moving_average(temperature_data)
                        moving_average_humidity = calculate_moving_average(humidity_data)
                        print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
                        last_sensor_reading_time = time.time()
                    except RuntimeError as e:
                        print(f"Sensor read error: {e}")
                        consecutive_failures += 1
                        if consecutive_failures >= 3:
                            print("Too many consecutive sensor failures. Pausing sensor readings.")
                            running = False
                            time.sleep(300)
                            consecutive_failures = 0
                else:
                    time.sleep(1)

            except RuntimeError as e:
                print(f"Sensor read error: {e}")
                consecutive_failures += 1
                if consecutive_failures >= 3:
                    print("Too many consecutive sensor failures. Pausing sensor readings.")
                    running = False
                    time.sleep(300)
                    consecutive_failures = 0
            except Exception as e:
                print(f"Unexpected error: {e}")
                consecutive_failures += 1
                if consecutive_failures >= 3:
                    print("Too many consecutive errors. Pausing sensor readings.")
                    running = False
                    time.sleep(300)
                    consecutive_failures = 0

    finally:
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass
        print("Cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

