import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_BUS = 1
BASELINE_DURATION = 10      # seconds
BASELINE_INTERVAL = 1        # seconds between baseline reads
READ_INTERVAL = 1            # seconds between altitude reads
NUM_EXCLUDE_READINGS = 2     # exclude first two baseline readings


def initialize_i2c():
    """Initialize the I2C bus on GPIO2 (SDA) / GPIO3 (SCL)."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Probe for a device to confirm the bus is functional.
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()
        if not devices:
            print("Error: No I2C devices found on bus.")
            return None
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_bmp280(i2c_bus):
    """Initialize the BMP280 sensor on the I2C bus."""
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=0x77)
        # Configure sea-level pressure for altitude calculation.
        sensor.sea_level_pressure = 1013.25
        return sensor
    except ValueError as e:
        print(f"Error: BMP280 not found on I2C bus (address 0x77): {e}")
        return None
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None


def read_baseline_pressure(sensor, num_reads=BASELINE_NUM_READINGS):
    """Read baseline pressure, excluding the first few readings for stability."""
    total = 0
    valid = 0
    for i in range(num_reads):
        try:
            total += sensor.pressure
            valid += 1
        except OSError as e:
            print(f"Error reading pressure during baseline: {e}")
        except Exception as e:
            print(f"Unexpected error reading pressure: {e}")
        if i < num_reads - 1:
            time.sleep(BASELINE_INTERVAL)

    if valid == 0:
        print("Error: No valid pressure readings collected for baseline.")
        return None

    baseline = total / valid
    print(f"Baseline pressure: {baseline:.2f} hPa")
    return baseline


def read_altitude(sensor):
    """Read and display the relative altitude from the BMP280."""
    try:
        altitude = sensor.altitude
        print(f"Relative altitude: {altitude:.2f} meters")
        return altitude
    except OSError as e:
        print(f"Error reading altitude: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading altitude: {e}")
        return None


def main():
    """Main loop: initialize sensor, collect baseline, then read altitude continuously."""
    i2c = initialize_i2c()
    if i2c is None:
        return

    sensor = initialize_bmp280(i2c)
    if sensor is None:
        return

    try:
        baseline_pressure = read_baseline_pressure(sensor)
        if baseline_pressure is None:
            return

        while True:
            altitude = read_altitude(sensor)
            if altitude is None:
                time.sleep(READ_INTERVAL)
                continue
            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        print("Exiting program.")


if __name__ == "__main__":
    main()

