import signal
import sys
import time
import random
import RPi.GPIO as GPIO

# Pin assignments (BCM numbering)
X_DIR_PIN = 17
X_STEP_PIN = 18
X_ENC_A_PIN = 22
X_ENC_B_PIN = 23
Y_DIR_PIN = 27
Y_STEP_PIN = 4
Y_ENC_A_PIN = 24
Y_ENC_B_PIN = 25

# Soft limits (mm)
X_MIN = 0.0
X_MAX = 50.0
Y_MIN = 0.0
Y_MAX = 50.0

# Global state
x_position = 0.0
y_position = 0.0
x_direction = 0
y_direction = 0
scan_start = None
scan_end = None
scan_params = {
    "x_min": X_MIN,
    "x_max": X_MAX,
    "y_min": Y_MIN,
    "y_max": Y_MAX,
}

_running = True


def _cleanup(signum=None, frame=None):
    global _running
    _running = False
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def _read_encoder(channel):
    """Read quadrature encoder state and update position."""
    global x_position, y_position
    if channel == X_ENC_A_PIN:
        b = GPIO.input(X_ENC_B_PIN)
        if b == GPIO.HIGH:
            x_direction += 1
        else:
            x_direction -= 1
    elif channel == Y_ENC_A_PIN:
        b = GPIO.input(Y_ENC_B_PIN)
        if b == GPIO.HIGH:
            y_direction += 1
        else:
            y_direction -= 1
    if x_direction != 0:
        x_position += 0.01
    if y_direction != 0:
        y_position += 0.01


def _setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(X_DIR_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(X_STEP_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(Y_DIR_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(Y_STEP_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(X_ENC_A_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(X_ENC_B_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(Y_ENC_A_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(Y_ENC_B_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.add_event_detect(X_ENC_A_PIN, GPIO.RISING, callback=lambda ch: _read_encoder(ch))
    GPIO.add_event_detect(Y_ENC_A_PIN, GPIO.RISING, callback=lambda ch: _read_encoder(ch))


def _move_to(x, y):
    global x_direction, y_direction
    if x < X_MIN:
        x_direction = -1
    elif x > X_MAX:
        x_direction = 1
    else:
        x_direction = 0
    if y < Y_MIN:
        y_direction = -1
    elif y > Y_MAX:
        y_direction = 1
    else:
        y_direction = 0
    GPIO.output(X_DIR_PIN, x_direction)
    GPIO.output(Y_DIR_PIN, y_direction)
    while abs(x_position - x) > 0.5:
        GPIO.output(X_STEP_PIN, GPIO.HIGH)
        time.sleep(0.001)
        GPIO.output(X_STEP_PIN, GPIO.LOW)
        time.sleep(0.001)
    while abs(y_position - y) > 0.5:
        GPIO.output(Y_STEP_PIN, GPIO.HIGH)
        time.sleep(0.001)
        GPIO.output(Y_STEP_PIN, GPIO.LOW)
        time.sleep(0.001)


def _scan_loop():
    global scan_start, scan_end, scan_params
    while _running:
        x = x_position
        y = y_position
        if scan_start is not None and scan_end is not None:
            if x >= scan_start["x_min"] and x <= scan_start["x_max"] and y >= scan_start["y_min"] and y <= scan_start["y_max"]:
                scan_start = None
                scan_end = (x, y)
                print(f"Scan complete: {x:.2f}, {y:.2f}")
                break
        if scan_start is None and scan_end is None:
            if scan_params:
                scan_start = {"x_min": scan_params["x_min"], "y_min": scan_params["y_min"]}
                scan_end = None
            else:
                scan_start = None
                scan_end = None
        time.sleep(0.1)


def _report():
    print(f"X: {x_position:.2f}  Y: {y_position:.2f}")


def main():
    global x_position, y_position, x_direction, y_direction, scan_start, scan_end, scan_params
    _setup_gpio()
    signal.signal(signal.SIGINT, _cleanup)
    try:
        while _running:
            cmd = input("Enter command (or 'exit'): ").strip().lower()
            if cmd == "x" and len(sys.argv) == 2:
                try:
                    x = float(sys.argv[1])
                    _move_to(x, y_position)
                except ValueError:
                    print("Invalid X value.")
            elif cmd == "y" and len(sys.argv) == 2:
                try:
                    y = float(sys.argv[1])
                    _move_to(x_position, y)
                except ValueError:
                    print("Invalid Y value.")
            elif cmd == "scan":
                scan_start = {"x_min": x_position, "y_min": y_position}
                scan_end = None
                scan_params = scan_start
                print("Scan initiated.")
                _scan_loop()
            elif cmd == "return":
                _move_to(X_MIN, Y_MIN)
                print("Returned to origin.")
            elif cmd == "report":
                _report()
            elif cmd == "exit":
                break
            else:
                print("Unknown command.")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

