import time
import logging
import signal
import sys

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor over I2C."""

    REG_ID = 0x0F
    REG_STATUS = 0x0F
    REG_MEASURE = 0x00
    REG_CALIB = 0x1E

    def __init__(self, bus_id=1, retry_attempts=5, retry_delay=0.01, min_interval=2.0):
        self._bus_id = bus_id
        self._retry_attempts = retry_attempts
        self._retry_delay = retry_delay
        self._min_interval = min_interval
        self._bus = None
        self._running = True
        self._cache = {"temperature": None, "humidity": None, "valid": False}
        self._last_read_time = 0.0

    def __enter__(self):
        self._open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False

    def _open(self):
        try:
            self._bus = smbus.SMBus(self._bus_id)
        except OSError as e:
            logger.error("Failed to open I2C bus %d: %s", self._bus_id, e)
            raise

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def _signal_handler(self, signum, frame):
        logger.info("Signal %d received, shutting down...", signum)
        self._running = False

    def _read_register(self, reg, length=1):
        try:
            return self._bus.read_i2c_block_data(self._bus_id, reg, length)
        except OSError as e:
            logger.warning("I2C read error at register 0x%02X: %s", reg, e)
            return None

