import time
import datetime
import logging
import fcntl
import os
import random
import signal
import sys
import board
import adafruit_dht

# Configuration
HIGH_HUMIDITY_THRESHOLD = 75.0
LOW_HUMIDITY_THRESHOLD = 45.0
DHT22_PIN_1 = board.D17
DHT22_PIN_2 = board.D27
DATA_LOG_FILE = "retail_data.csv"
ALERT_LOG_FILE = "retail_alerts.log"
CLOUD_LOG_FILE = "cloud_log.log"
ERROR_LOG_FILE = "error.log"
RETRY_COUNT = 3
RETRY_DELAY = 2
DEBOUNCE_TIME = 30 * 60  # 30 minutes
LOG_INTERVAL = 60  # seconds

# Global state
high_humidity_alerts = {1: False, 2: False}
low_humidity_alerts = {1: False, 2: False}
last_alert_time = {1: 0, 2: 0}
running = True

# Logging setup
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler(ERROR_LOG_FILE),
        logging.StreamHandler()
    ]
)

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def setup_logging():
    """Configure file locking for the data log file."""
    try:
        with open(DATA_LOG_FILE, 'a') as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
    except Exception as e:
        logging.error(f"Failed to acquire lock for {DATA_LOG_FILE}: {e}")
        raise

def ensure_directory():
    """Create the data directory if it does not exist."""
    try:
        os.makedirs("data", exist_ok=True)
    except OSError as e:
        logging.error(f"Cannot create data directory: {e}")
        raise

def read_dht22(pin):
    """Read temperature and humidity from a DHT22 sensor with retries."""
    for attempt in range(RETRY_COUNT):
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logging.warning(f"DHT22 on pin {pin} returned None (attempt {attempt + 1})")
        except RuntimeError as e:
            logging.warning(f"DHT22 on pin {pin} read error (attempt {attempt + 1}): {e}")
        except Exception as e:
            logging.error(f"Unexpected error reading DHT22 on pin {pin} (attempt {attempt + 1}): {e}")
        finally:
            try:
                sensor.exit()
            except Exception:
                pass
        if attempt < RETRY_COUNT - 1:
            time.sleep(RETRY_DELAY)
    logging.error(f"Failed to read DHT22 on pin {pin} after {RETRY_COUNT} attempts")
    return None, None

def validate_data(temperature, humidity):
    """Validate temperature and humidity readings."""
    if temperature is None or humidity is None:
        return False
    if not (0 <= temperature <= 35):
        logging.warning(f"Temperature {temperature}°C out of range")
        return False
    if not (0 <= humidity <= 100):
        logging.warning(f"Humidity {humidity}% out of range")
        return False
    return True

def log_data(temperature, humidity, sensor_id):
    """Log sensor data to CSV with file locking."""
    try:
        setup_logging()
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d")
        filename = f"retail_data_{timestamp}.csv"
        file_exists = os.path.isfile(filename)
        with open(filename, 'a') as f:
            if not file_exists:
                f.write("Timestamp,Sensor ID,Temp (C),Humidity (%)\n")
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            f.write(f"{timestamp},{sensor_id},{temperature:.2f},{humidity:.2f}\n")
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
        logging.info(f"Data logged: Temp={temperature:.2f}°C, Humidity={humidity:.2f}%")
    except Exception as e:
        logging.error(f"Error logging data: {e}")

def check_alerts(sensor_id, temperature, humidity):
    """Check and trigger alerts based on humidity thresholds."""
    global high_humidity_alerts, low_humidity_alerts, last_alert_time
    now = time.time()
    if temperature is None or humidity is None:
        return
    if humidity > HIGH_HUMIDITY_THRESHOLD:
        if not high_humidity_alerts[sensor_id]:
            if now - last_alert_time[sensor_id] > DEBOUNCE_TIME:
                logging.warning(f"High Humidity Alert: Sensor {sensor_id}, Temp={temperature:.2f}°C, Humidity={humidity:.2f}%")
                high_humidity_alerts[sensor_id] = True
                last_alert_time[sensor_id] = now
    elif humidity < LOW_HUMIDITY_THRESHOLD:
        if not low_humidity_alerts[sensor_id]:
            if now - last_alert_time[sensor_id] > DEBOUNCE_TIME:
                logging.warning(f"Low Humidity Alert: Sensor {sensor_id}, Temp={temperature:.2f}°C, Humidity={humidity:.2f}%")
                low_humidity_alerts[sensor_id] = True
                last_alert_time[sensor_id] = now
    else:
        high_humidity_alerts[sensor_id] = False
        low_humidity_alerts[sensor_id] = False

def simulate_cloud_push(sensor_id, temperature, humidity):
    """Simulate sending data to a cloud service with an 80% success rate."""
    if random.random() < 0.8:
        logging.info(f"Simulated Cloud Push: Sensor {sensor_id}, Temp={temperature:.2f}°C, Humidity={humidity:.2f}%")
    else:
        logging.error(f"Cloud Push failed for Sensor {sensor_id}")

def main():
    global running
    ensure_directory()
    logging.info("Starting DHT22 monitoring system...")
    try:
        while running:
            temperature1, humidity1 = read_dht22(DHT22_PIN_1)
            temperature2, humidity2 = read_dht22(DHT22_PIN_2)
            if temperature1 is not None and humidity1 is not None:
                if validate_data(temperature1, humidity1):
                    log_data(temperature1, humidity1, 1)
                    check_alerts(1, temperature1, humidity1)
                    simulate_cloud_push(1, temperature1, humidity1)
            else:
                logging.warning("Failed to read data from sensor 1")
            if temperature2 is not None and humidity2 is not None:
                if validate_data(temperature2, humidity2):
                    log_data(temperature2, humidity2, 2)
                    check_alerts(2, temperature2, humidity2)
                    simulate_cloud_push(2, temperature2, humidity2)
            else:
                logging.warning("Failed to read data from sensor 2")
            for _ in range(LOG_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Cleaning up GPIO...")
        try:
            import board
            import adafruit_dht
            dht_devices = []
            for pin in (DHT22_PIN_1, DHT22_PIN_2):
                try:
                    dht_devices.append(adafruit_dht.DHT22(pin, use_pulseio=False))
                except Exception:
                    pass
            for dht in dht_devices:
                try:
                    dht.exit()
                except Exception:
                    pass
        except Exception as e:
            logging.error(f"GPIO cleanup error: {e}")
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

