#!/usr/bin/env python3
"""PWM fan controller for Raspberry Pi.

Fan PWM signal on GPIO14 (BCM), 100 Hz, duty cycle adjusted by CPU temperature.
"""

import logging
import signal
import subprocess
import sys
import time

from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

FAN_PIN = 14
PWM_FREQ = 100.0
POLL_INTERVAL = 5.0
DEFAULT_DUTY = 100
TEMP_THRESHOLD = 70.0

fan: PWMOutputDevice | None = None
last_duty = DEFAULT_DUTY
running = True


def get_cpu_temp() -> float:
    """Return CPU temperature in °C via vcgencmd.

    Raises:
        RuntimeError: if the subprocess fails or output cannot be parsed.
    """
    result = subprocess.run(
        ["vcgencmd", "measure_temp"],
        capture_output=True,
        text=True,
        timeout=5,
    )
    if result.returncode != 0:
        raise RuntimeError(f"vcgencmd exited with {result.returncode}: {result.stderr.strip()}")
    out = result.stdout.strip()
    if not out.startswith("temp="):
        raise RuntimeError(f"Unexpected vcgencmd output: {out!r}")
    return float(out.split("=", 1)[1].split("'")[0])


def duty_for_temp(temp: float) -> int:
    """Map temperature to a stepped duty-cycle value."""
    if temp <= TEMP_THRESHOLD:
        return 0
    if temp <= 50:
        return 25
    if temp <= 70:
        return 50
    if temp <= 90:
        return 75
    return 100


def cleanup(signum: int | None = None, frame=None) -> None:
    """Stop PWM and release GPIO resources."""
    global fan, running
    running = False
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception as exc:
            logger.warning("Error during fan cleanup: %s", exc)
    if signum is not None:
        logger.info("Received signal %s, exiting.", signum)
        sys.exit(0)


def main() -> None:
    global fan, last_duty

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as exc:
        logger.error("Failed to initialize PWM on GPIO%d: %s", FAN_PIN, exc)
        sys.exit(1)

    try:
        while running:
            try:
                temp = get_cpu_temp()
                duty = duty_for_temp(temp)
                if duty != last_duty:
                    fan.value = duty / 100.0
                    last_duty = duty
                    logger.info("CPU %.1f°C -> fan duty %d%%", temp, duty)
                else:
                    logger.debug("CPU %.1f°C -> fan duty unchanged at %d%%", temp, duty)
            except RuntimeError as exc:
                logger.error("Temperature read failed: %s", exc)
                # Retain last known duty cycle as fail-safe
                if last_duty != DEFAULT_DUTY:
                    try:
                        fan.value = last_duty / 100.0
                    except Exception:
                        pass
                else:
                    fan.value = DEFAULT_DUTY / 100.0
            except Exception as exc:
                logger.error("Unexpected error in control loop: %s", exc)

            time.sleep(POLL_INTERVAL)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

