import smbus
import time
import signal
import sys

I2C_BUS = 1
I2C_ADDR = 0x5C
MEASURE_DELAY_S = 0.08
READ_INTERVAL_S = 5.0

running = True

def _signal_handler(signum, frame):
    global running
    running = False

def _crc8(data: bytes) -> int:
    crc = 0xFF
    for b in data:
        crc ^= b
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ 0xA1) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def _write_cmd(bus: smbus.SMBus, cmd: int) -> None:
    bus.write_byte(I2C_ADDR, cmd)

def _read_data(bus: smbus.SMBus, n: int) -> bytes:
    return bytes(bus.read_i2c_block_data(I2C_ADDR, n))

def _read_sensor(bus: smbus.SMBus) -> None:
    _write_cmd(bus, 0x33)  # reset
    time.sleep(MEASURE_DELAY_S)
    _write_cmd(bus, 0x00)  # start measurement
    time.sleep(0.01)
    data = _read_data(bus, 7)
    if len(data) != 7:
        raise IOError(f"Short read: expected 7 bytes, got {len(data)}")
    if _crc8(data) != data[6]:
        raise IOError("CRC mismatch")
    status = data[0]
    if status & 0x18:
        raise IOError("Sensor not ready")
    temp_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
    hum_raw = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]
    humidity = (hum_raw / 2**20) * 100.0
    temp_c = temp_raw / 2**20 * 200.0 - 50.0
    return temp_c, humidity

def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        bus = smbus.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.")
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied. Run with sudo or add user to the 'i2c' group.")
        sys.exit(1)
    except OSError as e:
        print(f"Error: Cannot open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                temp_c, humidity = _read_sensor(bus)
                ts = time.strftime("%Y-%m-%d %H:%M:%S")
                print(f"[{ts}] Temp: {temp_c:.2f} C / {temp_c * 9/5 + 32:.2f} F  Humidity: {humidity:.2f}%")
            except IOError as e:
                print(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] Error: {e}")
            except Exception as e:
                print(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] Unexpected error: {e}")
            for _ in range(READ_INTERVAL_S):
                if not running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")

