SUPPLY_INA219 = 0x00
BATTERY_INA219 = 0x01
I2C_BUS = 1
SHUNT_SUPPLY = 0.00725
SHUNT_BATTERY = 0.005
POLL_INTERVAL = 2.0

_running = True


def _handle_signal(signum, _frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


