    try:
        voltage = ina.voltage()
        current = ina.current()
        return voltage, current
    except DeviceRangeError:
        log.error("INA219 %s out of range: voltage=%s, current=%s", label, voltage, current)
        return None, None
    except OSError as exc:
        log.error("I2C error reading %s: %s", label, exc)
        return None, None
    except Exception as exc:
        log.error("Unexpected error reading %s: %s", label, exc)
        return None, None


def read_ups():
    try:
        data = UPS.read()
        return data["Proc"], data["Battery_Port"], data["Temp"], data["Capacity"]
    except OSError as exc:
        log.error("I2C error reading UPS: %s", exc)
        return None, None, None, None
    except Exception as exc:
        log.error("Unexpected error reading UPS: %s", exc)
        return None, None, None, None


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    supply_ina = None
    battery_ina = None
    try:
        supply_ina = INA219(SUPPLY_INA219, bus=I2C_BUS)
        battery_ina = INA219(BATTERY_INA219, bus=I2C_BUS)
    except OSError as exc:
        log.error("Failed to initialise INA219 on bus %d: %s", I2C_BUS, exc)
        sys.exit(1)
    except Exception as exc:
        log.error("Unexpected error initialising INA219: %s", exc)
        sys.exit(1)

    try:
        while _running:
            supply_v, supply_a = read_ina219(supply_ina, "Supply", SHUNT_SUPPLY)
            battery_v, battery_a = read_ina219(battery_ina, "Battery", SHUNT_BATTERY)

            if supply_v is not None and supply_a is not None:
                print(f"Supply: {supply_v:.3f} V, {supply_a:.3f} mA")

            if battery_v is not None and battery_a is not None:
                print(f"Battery: {battery_v:.3f} V, {battery_a:.3f} mA")

            ups_data = read_ups()
            if ups_data is not None:
