                      f"Battery Port {ups_data[1]:.1f}mV, "
                      f"Temp {ups_data[2]:.1f}C, Capacity {ups_data[3]:.1f}%")

            time.sleep(POLL_INTERVAL)
    finally:
        for ina in (supply_ina, battery_ina):
            if ina is not None:
                try:
                    ina.close()
                except Exception:
                    pass


if __name__ == "__main__":
    main()

