    global fan
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        fan = OutputDevice(FAN_PIN)
        fan.off()
        for i in range(NUM_READINGS):
            if not running:
                break
            temp = read_temp()
            print(f"Reading {i + 1}/{NUM_READINGS} - Simulated Temperature: {temp}°C")
