import signal
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero library not found. Install with: pip install gpiozero")
    sys.exit(1)

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
LED_PIN = 17
PPM_THRESHOLD = 500
SLEEP_INTERVAL = 5  # seconds

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False
    logging.info("Shutdown signal received. Terminating...")

def get_temperature():
    """Simulates reading temperature from a sensor."""
    return round(random.uniform(20.00, 30.00), 2)

def get_humidity():
    """Simulates reading humidity from a sensor."""
    return round(random.uniform(40.00, 60.00), 2)

def get_ppm():
    """Simulates reading PM2.5 concentration from a sensor."""
    return random.randint(0, 800)

def main():
    """Main function to simulate air quality monitoring."""
    global _running

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    led = None
    try:
        # Initialize LED (placeholder for physical LED)
        led = LED(LED_PIN)
        led.off()  # Ensure LED starts off

        while _running:
            try:
                temperature = get_temperature()
                humidity = get_humidity()
                ppm = get_ppm()

                logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}")

                if ppm > PPM_THRESHOLD:
                    logging.warning(
                        "ALERT! PPM level exceeded threshold. Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}"
                    )

                # Toggle LED state every iteration
                if led.is_lit:
                    led.off()
                else:
                    led.on()

                time.sleep(SLEEP_INTERVAL)

            except Exception as e:
                logging.error(f"An error occurred during monitoring: {e}")
                break

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except GPIOZeroError as e:
        logging.error(f"GPIO error occurred: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure LED is turned off and resources are released
        if led is not None:
            try:
                led.off()
                led.close()
                logging.info("LED resource closed.")
            except Exception as e:
                logging.error(f"Error closing LED resource: {e}")
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

