#!/usr/bin/env python3
"""
Soil moisture monitor for Raspberry Pi 4 (Bookworm).

Reads an Adafruit Capacitive Soil Moisture Sensor (SEESAW-based) over I2C
every 10 seconds, drives a water pump on GPIO17 (BCM) when moisture < 300,
and cleanly releases the pump and I2C bus on exit.
"""

import signal
import sys
import time

import board
import busio
import adafruit_seesaw.seesaw
import digitalio

PUMP_PIN = 17
MOISTURE_THRESHOLD = 300
READ_INTERVAL_S = 10
MAX_RETRIES = 3

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        return None


def initialize_sensor(i2c_bus):
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus)
        return sensor
    except Exception as exc:
        print(f"Error initializing soil moisture sensor: {exc}", file=sys.stderr)
        return None


def initialize_pump(pin):
    try:
        return digitalio.DigitalInOut(pin)
    except Exception as exc:
        print(f"Error initializing pump on GPIO{pin}: {exc}", file=sys.stderr)
        return None


def read_moisture(sensor):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return sensor.moisture_read()
        except Exception as exc:
            print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {exc}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(1)
    return None


def control_pump(pump, moisture_level, threshold):
    if moisture_level is None:
        return
    if moisture_level < threshold:
        pump.on()
        print("Water Pump ON: Soil too dry")
    else:
        pump.off()
        print("Water Pump OFF: Soil moisture sufficient")


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        sys.exit(1)

    pump = initialize_pump(PUMP_PIN)
    if pump is None:
        i2c_bus.deinit()
        sys.exit(1)

    try:
        while _running:
            moisture = read_moisture(sensor)
            control_pump(pump, moisture, MOISTURE_THRESHOLD)
            print(f"Soil Moisture: {moisture}")
            time.sleep(READ_INTERVAL_S)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        try:
            pump.off()
            pump.deinit()
        except Exception:
            pass
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Program finished.")


if __name__ == "__main__":
    main()

