import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
_running = True
_gpio_ready = False


def _cleanup():
    """Release GPIO resources exactly once."""
    global _gpio_ready
    if _gpio_ready:
        try:
            GPIO.cleanup()
        except Exception:
            pass
        _gpio_ready = False


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


