import signal
import sys
import time
import json
import requests
from requests.auth import HTTPBasicAuth

try:
    import gpiozero
    from gpiozero import Button
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

# Configuration
SENSOR_PIN = 4
SERVER_URL = 'http://localhost:5000/sensor'
USERNAME = 'user'
PASSWORD = 'password'
POLL_INTERVAL = 5  # seconds

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    _running = False

def initialize_gpio():
    """Initialize the GPIO peripheral and configure the sensor pin."""
    try:
        # pull_up=False  -> internal pull-down disabled (floating input)
        # bounce_time is ignored on a plain digital input
        sensor = Button(SENSOR_PIN, pull_up=False, bounce_time=None)
        return sensor
    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected GPIO initialization error: {e}")
        return None

def read_sensor_value(sensor):
    """Read the current digital value from the sensor."""
    try:
        return int(sensor.value)
    except DeviceClosed:
        print("Error: sensor device is closed.")
        return None
    except GPIOZeroError as e:
        print(f"Error reading sensor: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}")
        return None

def send_data_to_server(url, data):
    """Send JSON data to the server using Basic Authentication."""
    try:
        response = requests.post(
            url,
            json=data,
            auth=HTTPBasicAuth(USERNAME, PASSWORD),
            timeout=10
        )
        response.raise_for_status()
        print(f"Server response: {response.status_code} - {response.text}")
    except requests.exceptions.Timeout:
        print("Error: Request timed out.")
    except requests.exceptions.ConnectionError as e:
        print(f"Error: Connection failed: {e}")
    except requests.exceptions.HTTPError as e:
        print(f"Error: HTTP request failed: {e}")
    except requests.exceptions.RequestException as e:
        print(f"Error: Request failed: {e}")

def main():
    """Main loop: read sensor and send data every POLL_INTERVAL seconds."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = initialize_gpio()
    if sensor is None:
        print("Failed to initialize GPIO. Exiting.")
        sys.exit(1)

    print(f"Sensor initialized on GPIO{SENSOR_PIN} (pull_up=False). Polling every {POLL_INTERVAL}s.")

    try:
        while _running:
            value = read_sensor_value(sensor)
            if value is not None:
                data = {'sensor': 'digital_input', 'value': value}
                send_data_to_server(SERVER_URL, data)
            else:
                print("Skipping submission due to sensor read failure.")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < POLL_INTERVAL:
                time.sleep(0.1)
                slept += 0.1

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        # gpiozero cleans up GPIO automatically on close()
        try:
            sensor.close()
        except Exception:
            pass
        print("GPIO cleanup completed. Exiting.")

if __name__ == "__main__":
    main()

