import sys
import time
import signal
import threading
import traceback

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("ERROR: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

try:
    import DOG
except ImportError:
    print("ERROR: The DOG library is not installed. Please install it first.")
    sys.exit(1)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
POLL_INTERVAL = 0.1          # seconds between DOG.receive() calls
FILE_PATH = "data.log"
GPIO_PIN = 17                # BCM pin used by DOG (placeholder; library may use its own)

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------
_help_displayed = False
_stop_event = threading.Event()
_thread = None
_dog = None
_gpio_initialized = False


def _cleanup(signum=None, frame=None):
    """Signal handler / cleanup routine that ensures the DOG API call is
    invoked and GPIO resources are released on every exit path."""
    global _thread, _dog, _gpio_initialized

    if _stop_event.is_set():
        return

    # --- Signal handling -------------------------------------------------
    if signum is not None:
        print(f"\nReceived signal {signum}; shutting down.")
        _stop_event.set()

    # --- Ensure the DOG API call is invoked --------------------------------
    if _dog is not None:
        try:
            _dog.DOG_api_call()
        except Exception as exc:
            print(f"Warning: error while invoking DOG API call: {exc}")

    # --- GPIO cleanup -----------------------------------------------------
    if _gpio_initialized:
        try:
            GPIO.cleanup()
        except Exception as exc:
            print(f"Warning: error during GPIO cleanup: {exc}")
        finally:
            _gpio_initialized = False

    # --- Thread termination ------------------------------------------------
    if _thread is not None and _thread.is_alive():
        _thread.join(timeout=2.0)
        if _thread.is_alive():
            print("Warning: receive thread did not terminate cleanly.")

    print("GPIO cleanup completed. Exiting.")


def _signal_handler():
    _cleanup()


def _log_error(msg):
    print(f"ERROR: {msg}", file=sys.stderr)


def _log_info(msg):
    print(f"INFO: {msg}")


def _display_help():
    """Display help information for the available commands."""
    global _help_displayed
    if _help_displayed:
        return
    _help_displayed = True

    print("\nAvailable commands:")
    print("  help <command>  - display help for a specific command")
    print("  start <filename> - start logging data to a file")
    print("  stop            - stop logging and exit")
    print("  display         - display the contents of the log file")
    print("  send <data>     - send data via DOG.send()")
    print("  write <data>    - append data directly to the log file")
    print("  exit            - stop logging and exit")


def _parse_args(args):
    """Parse command-line arguments and return (command, args)."""
    if len(args) < 2:
        _log_error("Usage: <command> [args]")
        return None, None

    command = args[0].lower()
    if command == "help":
        if len(args) < 2:
            _log_error("Usage: help <command>")
            return None, None
        return "help", args[1]
    elif command == "start":
        if len(args) < 2:
            _log_error("Usage: start <filename>")
            return None, None
        return "start", args[1]
    elif command == "stop":
        return "stop", None
    elif command == "display":
        return "display", None
    elif command == "send":
        if len(args) < 2:
            _log_error("Usage: send <data>")
            return None, None
        return "send", args[1]
    elif command == "write":
        if len(args) < 2:
            _log_error("Usage: write <data>")
            return None, None
        return "write", args[1]
    elif command == "exit":
        return "exit", None
    else:
        _log_error(f"Unknown command: {command}")
        return None, None


def _start_logging(filename):
    """Start logging data to a file and launch the receive thread."""
    global _thread, _dog, _gpio_initialized

    if _stop_event.is_set():
        _log_error("Logging has been stopped; cannot start.")
        return

    if _thread is not None and _thread.is_alive():
        _log_error("Logging thread already running.")
        return

    try:
        _gpio_initialized = True
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(GPIO_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

        _dog = DOG.DOG()
        _dog.DOG_setPinFactory(DOG.PiFactoryDefault)

        _dog.DOG_setMode(DOG.DOG_MODE_FILE)
        _dog.DOG_setLogFile(filename)
        _dog.DOG_setLogMaxLines(1000)

        _dog.DOG_setReceiveTimeout(0.1)
        _dog.DOG_setReceiveCallback(_dog.receive)

        _thread = threading.Thread(target=_dog.DOG_receive, daemon=True)
        _thread.start()

        _log_info(f"Started logging to {filename}")
    except Exception as exc:
        _log_error(f"Error starting logging: {exc}")
        _cleanup()
        return


def _receive_loop():
    """Background thread: poll DOG.receive() and write results to file."""
    global _stop_event
    while not _stop_event.is_set():
        try:
            data = _dog.DOG_receive(timeout=0.1)
            if data is not None:
                try:
                    with open(FILE_PATH, "a") as f:
                        f.write(data + "\n")
                except OSError as exc:
                    _log_error(f"Error writing to log file: {exc}")
        except Exception as exc:
            _log_error(f"Error in receive loop: {exc}")
            break
        _stop_event.wait(POLL_INTERVAL)


def _stop_logging():
    """Stop logging and clean up resources."""
    global _thread, _dog, _gpio_initialized

    if _stop_event.is_set():
        return

    _log_info("Stopping logging...")
    _stop_event.set()

    if _thread is not None and _thread.is_alive():
        _thread.join(timeout=2.0)
        if _thread.is_alive():
            _log_error("Receive thread did not terminate cleanly.")

    _thread = None
    _dog = None
    _gpio_initialized = False

    try:
        GPIO.cleanup()
    except Exception as exc:
        _log_error(f"Error during GPIO cleanup: {exc}")


def _display_log():
    """Display the contents of the log file."""
    try:
        with open(FILE_PATH, "r") as f:
            print(f.read())
    except OSError as exc:
        _log_error(f"Error displaying log file: {exc}")


def _send_data(data):
    """Send data via DOG.send() (placeholder implementation)."""
    try:
        _dog.DOG_send(data)
        _log_info(f"Sent: {data}")
    except Exception as exc:
        _log_error(f"Error sending data: {exc}")


def _write_data(data):
    """Append data directly to the log file."""
    try:
        with open(FILE_PATH, "a") as f:
            f.write(data + "\n")
        _log_info(f"Wrote to log: {data}")
    except OSError as exc:
        _log_error(f"Error writing to log file: {exc}")


def main():
    """Entry point: parse arguments, execute command, then clean up."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    args = sys.argv[1:]
    command, args_for_command = _parse_args(args)

    if command is None:
        _log_error("Invalid arguments.")
        return

    if command == "help":
        _display_help()
        return

    if command == "start":
        _start_logging(args_for_command[0])
    elif command == "stop":
        _stop_logging()
    elif command == "display":
        _display_log()
    elif command == "send":
        _send_data(args_for_command[0])
    elif command == "write":
        _write_data(args_for_command[0])
    elif command == "exit":
        _stop_logging()
        sys.exit(0)
    else:
        _log_error(f"Unknown command: {command}")


if __name__ == "__main__":
    main()

