    except Exception as exc:
        _log_error(f"Error sending data: {exc}")


def _write_data(data):
    """Append data directly to the log file."""
    try:
        with open(FILE_PATH, "a") as f:
            f.write(data + "\n")
        _log_info(f"Wrote to log: {data}")
    except OSError as exc:
        _log_error(f"Error writing to log file: {exc}")


def main():
    """Entry point: parse arguments, execute command, then clean up."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    args = sys.argv[1:]
    command, args_for_command = _parse_args(args)

    if command is None:
        _log_error("Invalid arguments.")
        return

    if command == "help":
        _display_help()
        return

    if command == "start":
        _start_logging(args_for_command[0])
    elif command == "stop":
        _stop_logging()
    elif command == "display":
        _display_log()
    elif command == "send":
        _send_data(args_for_command[0])
    elif command == "write":
        _write_data(args_for_command[0])
    elif command == "exit":
        _stop_logging()
        sys.exit(0)
    else:
        _log_error(f"Unknown command: {command}")


if __name__ == "__main__":
    main()

