import signal
import sys
import time

from gpiozero import Button, LED
from gpiozero.exc import GPIOZeroError

BUTTON_PIN = 4
LED_PIN = 17
POLL_DELAY = 0.1

button = None
led = None

def cleanup():
    """Release GPIO resources and ensure the LED is turned off."""
    global button, led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
    if button is not None:
        try:
            button.close()
        except Exception:
            pass

def handle_sigterm(signum, frame):
    """Handle SIGTERM (e.g. systemd stop) for graceful shutdown."""
    raise KeyboardInterrupt

def main():
    global button, led

    # Register SIGTERM handler so systemd / kill can terminate cleanly
    signal.signal(signal.SIGTERM, handle_sigterm)

    try:
        button = Button(BUTTON_PIN, pull_up=False, bounce_time=0.05)
        led = LED(LED_PIN)
        led.off()

        print("Monitoring button on GPIO 4; press Ctrl+C to exit.")

        while True:
            if button.is_pressed:
                led.on()
            else:
                led.off()
            time.sleep(POLL_DELAY)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

