import signal
import time
import logging
import zmq

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

logger = logging.getLogger(__name__)


class SubscriptionError(Exception):
    pass


class SubscriptionHandler:
    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger(__name__)
        self.subscriptions = {}
        self.sub_list = []
        self._shutdown = False

    def handle(self, cmd, sub_sock, flags, logger=None):
        try:
            if cmd == 'SUBSCRIBE':
                self._subscribe(sub_sock, flags, logger)
            elif cmd == 'UNSUBSCRIBE':
                self._unsubscribe(sub_sock, flags, logger)
            elif cmd == 'SET':
                self._set_flag(flags, logger)
            elif cmd == 'REMOVE':
                self._remove_flag(flags, logger)
            elif cmd == 'RESET':
                self._reset_flag(flags, logger)
            else:
                self.logger.error(f"Unknown command: {cmd}")
        except Exception as e:
            self.logger.error(f"Error handling command: {e}")

    def _subscribe(self, sub_sock, flags, logger):
        try:
            self.subscriptions[flags] = []
            self.sub_list.append(sub_sock)
            sub_sock.setsockopt_string(zmq.SUBSCRIBE, flags)
            self.logger.info(f"Subscribed to: {flags}")
        except zmq.ZMQError as e:
            self.logger.error(f"ZMQError subscribing to {flags}: {e}")
            raise SubscriptionError(f"Failed to subscribe to {flags}: {e}") from e
        except Exception as e:
            self.logger.error(f"Error subscribing to {flags}: {e}")
            raise SubscriptionError(f"Failed to subscribe to {flags}: {e}") from e

    def _unsubscribe(self, sub_sock, flags, logger):
        try:
            if flags in self.subscriptions:
                self.subscriptions[flags].remove(sub_sock)
                self.sub_list.remove(sub_sock)
                sub_sock.setsockopt_string(zmq.UNSUBSCRIBE, flags)
                self.logger.info(f"Unsubscribed from: {flags}")
        except zmq.ZMQError as e:
            self.logger.error(f"ZMQError unsubscribing from {flags}: {e}")
            raise SubscriptionError(f"Failed to unsubscribe from {flags}: {e}") from e
        except Exception as e:
            self.logger.error(f"Error unsubscribing from {flags}: {e}")
            raise SubscriptionError(f"Failed to unsubscribe from {flags}: {e}") from e

    def _set_flag(self, flags, logger=None):
        if not self.subscriptions.get(flags):
            self.logger.error(f"Invalid flag: {flags}")
            return
        try:
            self.subscriptions[flags].append(0)
            self._update_callback(flags, 0)
        except Exception as e:
            self.logger.error(f"Error setting flag {flags}: {e}")

    def _remove_flag(self, flags, logger=None):
        if not self.subscriptions.get(flags):
            self.logger.error(f"Invalid flag: {flags}")
            return
        try:
            self.subscriptions[flags].remove(sub_sock)
            self.sub_list.remove(sub_sock)
            self.logger.info(f"Removed flag: {flags}")
        except Exception as e:
            self.logger.error(f"Error removing flag {flags}: {e}")

    def _reset_flag(self, flags, logger=None):
        if not self.subscriptions.get(flags):
            self.logger.error(f"Invalid flag: {flags}")
            return
        try:
            self.subscriptions[flags] = [0]
            self._update_callback(flags, 0)
        except Exception as e:
            self.logger.error(f"Error resetting flag {flags}: {e}")

    def _update_callback(self, flags, state):
        for cb in self.subscriptions[flags]:
            try:
                cb(state)
            except Exception as e:
                self.logger.error(f"Error in callback for flag {flags}: {e}")

    def reset_all(self, logger=None):
        for flags in self.subscriptions:
            self._reset_flag(flags, logger)
        self._update_callback(flags, 0)
        self._shutdown = True

    def cleanup(self, logger=None):
        for flags in self.subscriptions:
            self._remove_flag(flags, logger)
        self.subscriptions.clear()
        self.sub_list.clear()


class PIDHandler:
    def __init__(self, logger=None):
        self.logger = logger or logging.getLogger(__name__)
        self.global_err_state = 0.0
        self.pwm = False
        self.pwm_pin = 18
        self.digital_pin = 15
        self.pwm_frequency = 1000
        self.last_time = time.time()
        self.last_msg = time.time()
        self.sub_list = []
        self.zmq_socket = None
        self.pwm_channel = None
        self.digital_channel = None
        self._shutdown = False

    def initialize(self, logger=None):
        if GPIO is None:
            self.logger.error("RPi.GPIO module not available. Cannot initialize GPIO.")
