#!/usr/bin/env python3
"""Raspberry Pi GPIO output pin wrapper with robust error handling.

Uses the modern gpiozero library (or its underlying RPi.GPIO driver) to
drive a single BCM GPIO pin as an output.  Includes full validation,
error handling, and clean shutdown semantics.
"""

from typing import Optional
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError as exc:
    raise RuntimeError(
        "RPi.GPIO is not available. Install with: sudo apt install python3-rpi.gpio"
    ) from exc


class GPIOOutputError(Exception):
    """Custom exception for GPIO output errors."""
    pass


class OutputPin:
    """Represents a single GPIO pin configured as an output.

    Attributes:
        pin_number (int): BCM GPIO pin number (0-31).
        initial_value (int): Initial output value (0 or 1).
        _gpio_channel: Underlying RPi.GPIO channel handle.
        _closed: True when the driver connection has been shut down.
    """

    def __init__(self, pin_number: int, initial_value: int) -> None:
        if not isinstance(pin_number, int) or not (0 <= pin_number <= 31):
            raise ValueError(
                f"Invalid pin number: {pin_number!r}. Must be an integer in 0-31."
            )
        if initial_value not in (0, 1):
            raise ValueError(
                f"Invalid initial value: {initial_value!r}. Must be 0 or 1."
            )

        self.pin_number = pin_number
        self.initial_value = initial_value
        self._closed = False
        self._gpio_channel: Optional[int] = None

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            self._gpio_channel = GPIO.setup(
                pin_number, GPIO.OUT, initial=initial_value
            )
        except Exception as exc:
            raise GPIOOutputError(
                f"Failed to initialize GPIO {pin_number}: {exc}"
            ) from exc

    def set_value(self, value: int) -> None:
        """Sets the output value, validating it first.

        Args:
            value: The desired output value (0 or 1).

        Raises:
            ValueError: If value is not 0 or 1.
            GPIOOutputError: If the underlying driver call fails.
        """
        if value not in (0, 1):
            raise ValueError(f"Invalid value: {value!r}. Must be 0 or 1.")
        if self._closed:
            raise GPIOOutputError("Pin has been closed; cannot set value.")

        try:
            GPIO.output(self.pin_number, value)
        except Exception as exc:
            raise GPIOOutputError(
                f"Failed to set GPIO {self.pin_number} to {value}: {exc}"
            ) from exc

    def shutdown(self) -> None:
        """Safely returns the pin to INPUT mode and closes the driver connection.

        Safe to call even if initialization failed.
        """
        if self._closed:
            return
        try:
            GPIO.output(self.pin_number, GPIO.LOW)
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.cleanup(self.pin_number)
        except Exception as exc:
            print(f"Warning: cleanup of GPIO {self.pin_number} failed: {exc}", file=sys.stderr)
        finally:
            self._closed = True

    def __repr__(self) -> str:
        return (
            f"OutputPin(pin={self.pin_number}, value={self.initial_value})"
        )


def _signal_handler(signum: int, frame) -> None:
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}; shutting down.")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        output_pin = OutputPin(pin_number=17, initial_value=1)
        print("GPIO 17 output HIGH. Toggling every 0.5 s for 5 seconds...")
        start = time.monotonic()
        while time.monotonic() - start < 5.0:
            output_pin.set_value(0)
            time.sleep(0.5)
            output_pin.set_value(1)
            time.sleep(0.5)
        print("Done.")
    except GPIOOutputError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if 'output_pin' in locals():
            output_pin.shutdown()

