import signal
import sys
import time
import logging
from functools import partial

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("rotary_encoder")

# Quadrature state table: (DT, CLK) -> state index (0-3)
# States are ordered: 0, 1, 2, 3 for a single full quadrature cycle
QUADRATURE_TABLE = [
    (0, 0, 0),
    (0, 1, 1),
    (1, 0, 2),
    (1, 1, 3),
]

# Internal counter maintained by the encoder
_state = 0
_last_clk_state = 0
_last_dt_state = 0
_clk_pin = None
_dt_pin = None
_callback = None
_running = True


class RotaryEncoder:
    """Quadrature rotary encoder decoder with optional callback."""

    def __init__(self, clk_pin, dt_pin, callback=None, debounce_ms=20):
        self.callback = callback
        self.debounce_ms = debounce_ms
        self._last_clk_state = 0
        self._last_dt_state = 0
        self._state = 0
        self._install_signal_handlers()
        self._setup_gpio(clk_pin, dt_pin)

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._signal_handler)
            except (ValueError, OSError):
                # Not in main thread or signal not supported
                pass

    def _signal_handler(self, signum, frame):
        log.info("Received signal %s, shutting down...", signum)
        self.cleanup()
        sys.exit(0)

    def _setup_gpio(self, clk_pin, dt_pin):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            log.info("GPIO pins %d (CLK) and %d (DT) configured as inputs with pull-ups.", clk_pin, dt_pin)
        except Exception as e:
            log.error("Failed to initialize GPIO: %s", e)
            self.cleanup()
            raise

    def _read_states(self):
        """Read current levels of CLK and DT pins."""
        try:
            return GPIO.input(self.clk_pin), GPIO.input(self.dt_pin)
        except Exception as e:
            log.error("Error reading GPIO pins: %s", e)
            return self._last_clk_state, self._last_dt_state

    def _update_state(self, clk_state, dt_state):
        """Update internal state based on quadrature table."""
        if clk_state != self._last_clk_state:
            new_state = QUADRATURE_TABLE[self._last_dt_state][clk_state]
        else:
            new_state = QUADRATURE_TABLE[self._last_dt_state][self._last_clk_state]
        if new_state != self._state:
            self._state = new_state
            self._last_clk_state = clk_state
            self._last_dt_state = dt_state
            log.debug("State changed to %d", self._state)

    def _increment(self):
        self._state = (self._state + 1) % 4
        log.info("Counter incremented to %d", self._state)

    def _decrement(self):
        self._state = (self._state - 1) % 4
        log.info("Counter decremented to %d", self._state)

    def _handle_event(self):
        """Process a rising edge on either pin and update counter."""
        clk_state, dt_state = self._read_states()
        self._update_state(clk_state, dt_state)
        if self.callback:
            try:
                self.callback(self._state)
            except Exception as e:
                log.error("Callback raised exception: %s", e)

    def cleanup(self):
        """Remove event detections and release GPIO resources."""
        try:
            if self._callback is callable:
                self._callback(None)
            self._callback = None
        except Exception as e:
            log.error("Error clearing callback: %s", e)
        try:
            if self._clk_pin is not None:
                GPIO.remove_event_detect(self._clk_pin)
            if self._dt_pin is not None:
                GPIO.remove_event_detect(self._dt_pin)
        except Exception as e:
            log.error("Error removing event detection: %s", e)
        try:
            GPIO.cleanup()
        except Exception as e:
            log.error("Error during GPIO cleanup: %s", e)
        self._clk_pin = None
        self._dt_pin = None
        self._last_clk_state = 0
        self._last_dt_state = 0
        self._state = 0


def main():
    global _running
    encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=partial(print, "Counter: "))

    def on_change(new_val):
        nonlocal _running
        if not _running:
            return
        print(f"Counter: {new_val}")
        _running = True

    encoder.callback = on_change

    try:
        while _running:
            time.sleep(0.05)
    except KeyboardInterrupt:
        pass
    finally:
        encoder.cleanup()


if __name__ == "__main__":
    main()

