import http.server
import socketserver
import signal
import sys

try:
    from gpiozero import LED
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

LED_PIN = 18
LED = None

class LEDRequestHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/led/on':
            try:
                LED.on()
                self.send_response(200)
                self.send_header('Content-type', 'text/plain')
                self.end_headers()
                self.wfile.write(b'LED is ON')
            except Exception as e:
                self.send_error_response(500, f'Internal Server Error: {e}')
        elif self.path == '/led/off':
            try:
                LED.off()
                self.send_response(200)
                self.send_header('Content-type', 'text/plain')
                self.end_headers()
                self.wfile.write(b'LED is OFF')
            except Exception as e:
                self.send_error_response(500, f'Internal Server Error: {e}')
        else:
            self.send_error_response(404, 'Not Found')

    def log_message(self, fmt, *args):
        # Suppress default stderr logging to keep the console clean
        pass

class ThreadedHTTPServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads = True

def cleanup(signum=None, frame=None):
    global LED
    if LED is not None:
        try:
            LED.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        LED = LED()
    except Exception as e:
        print(f'Failed to initialize GPIO{LED_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        with ThreadedHTTPServer(('0.0.0.0', 8000), LEDRequestHandler) as httpd:
            print('Serving LED control on http://0.0.0.0:8000/led/on and http://0.0.0.0:8000/led/off')
            httpd.serve_forever()
    except OSError as e:
        print(f'Socket bind error: {e}', file=sys.stderr)
        cleanup()
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
        cleanup()
    finally:
        cleanup()

