import time
import signal
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17
BLINK_INTERVAL = 0.5

led = None
running = True

def cleanup():
    global led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global led

    signal.signal(signal.SIGTERM, handle_signal)

    try:
        led = LED(LED_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize GPIO{LED_PIN}: {e}")
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied accessing GPIO. Run as root or add user to gpio group.")
        sys.exit(1)
    except Exception as e:
