#!/usr/bin/env python3
"""
Rainbow HAT binary counter.

Touchpads A (GPIO5), B (GPIO6), C (GPIO12) toggle the three MSB, MSB, LSB
bits of bit_states.  After each toggle the discrete LEDs, 14-segment display,
APA102 strip (index 0), and buzzer are updated.

Wiring (Rainbow HAT):
  Touchpad A  -> GPIO5 (BCM)
  Touchpad B  -> GPIO6 (BCM)
  Touchpad C  -> GPIO12 (BCM)
  APA102 data -> GPIO10 (BCM)
  APA102 clock-> GPIO11 (BCM)
  Buzzer       -> GPIO13 (BCM)
  Green LED    -> GPIO7  (BCM)
  Blue LED     -> GPIO8  (BCM)

Requires: rainbowhat (pip install rainbowhat)
"""

import signal
import sys
import time

from rainbowhat import RainbowHat

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
NUM_BITS = 3
DIM_WHITE = (0, 0, 0)
ALL_WHITE = (255, 255, 255)
RED = (255, 0, 0)
GREEN = (0, 255, 0)
BLUE = (0, 0, 255)

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
bit_states = [0] * NUM_BITS
_running = True


def _cleanup() -> None:
    """Turn off all outputs and release hardware resources."""
    try:
        if RainbowHat.is_initialized():
            for i in range(NUM_BITS):
                try:
                    RainbowHat.DISCRETE_LEDS[i].off()
                except Exception:
                    pass
            RainbowHat.DISCRETE_LEDS.clear()
            try:
                RainbowHat.DISPLAY.clear()
            except Exception:
                pass
    except Exception as exc:
        print(f"Warning: display cleanup failed: {exc}", file=sys.stderr)

    try:
        RainbowHat.APA102.set_pixel(0, DIM_WHITE)
    except Exception:
        pass

    try:
        RainbowHat.BUZZER.off()
    except Exception:
        pass

    try:
        RainbowHat.GREEN_LED.off()
        RainbowHat.BLUE_LED.off()
    except Exception:
        pass


def _signal_handler(signum, frame) -> None:
    global _running
    _running = False


def _update_display() -> None:
    """Write the decimal value (0-7) to the 14-segment display over I2C."""
    try:
        value = int(bit_states)
    except Exception as exc:
        print(f"Warning: display value out of range: {exc}", file=sys.stderr)
        return

    try:
        RainbowHat.DISPLAY.clear()
        RainbowHat.DISPLAY.print_hex(value)
    except Exception as exc:
        print(f"Warning: display update failed: {exc}", file=sys.stderr)


def _update_leds() -> None:
    """Turn on the onboard green and blue LEDs as needed."""
    try:
        if bit_states[0]:
            RainbowHat.GREEN_LED.on()
        if bit_states[1]:
            RainbowHat.BLUE_LED.on()
    except Exception as exc:
        print(f"Warning: LED update failed: {exc}", file=sys.stderr)


def _update_apa102() -> None:
    """Show a dim white pixel at index 0 when value is 0, all white when 7,
    or a single red/green/blue pixel at index value when 1-6."""
    try:
        if bit_states == (0, 0, 0):
            RainbowHat.APA102.set_pixel(0, DIM_WHITE)
        elif bit_states == (7, 7, 7):
            RainbowHat.APA102.set_pixel(0, ALL_WHITE)
        else:
            idx = bit_states
            red = RED if bit_states[0] else GREEN if bit_states[1] else BLUE
            try:
                RainbowHat.APA102.set_pixel(idx, red)
            except Exception as exc:
                print(f"Warning: APA102 pixel {idx} update failed: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Warning: APA102 update failed: {exc}", file=sys.stderr)


def _update_buzzer() -> None:
    """Sound a 0.5 s tone on the buzzer."""
    try:
        RainbowHat.BUZZER.on()
        time.sleep(0.5)
        RainbowHat.BUZZER.off()
    except Exception as exc:
        print(f"Warning: buzzer tone failed: {exc}", file=sys.stderr)


def _toggle_bit(bit_num: int, value: int) -> None:
    """Toggle the given bit and update all outputs."""
    if value == 1:
        bit_states[bit_num] ^= 1
    else:
        bit_states[bit_num] = 1 if bit_states[bit_num] else 0

    _update_leds()
    _update_display()
    _update_apa102()
    _update_buzzer()


def main() -> None:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        hat = RainbowHat()
    except Exception as exc:
        print(f"Error: could not initialize Rainbow HAT: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        hat.set_display_brightness(100)
    except Exception as exc:
        print(f"Warning: display brightness set failed: {exc}", file=sys.stderr)

    try:
        hat.set_apa102Brightness(50)
    except Exception as exc:
        print(f"Warning: APA102 brightness set failed: {exc}", file=sys.stderr)

    try:
        hat.set_pixel(0, DIM_WHITE)
    except Exception as exc:
        print(f"Warning: APA102 init pixel 0 failed: {exc}", file=sys.stderr)

    print("Binary counter running.  Press Ctrl-C to exit.")
    print("Touchpad A (GPIO5) -> MSB, Touchpad B (GPIO6) -> MSB, "
          "Touchpad C (GPIO12) -> LSB.  Value 0-7.")

    while _running:
        try:
            if hat.touch_is_pressed(0):
                _toggle_bit(0, bit_states[0])
            if hat.touch_is_pressed(1):
                _toggle_bit(1, bit_states[1])
            if hat.touch_is_pressed(2):
                _toggle_bit(2, bit_states[2])
        except Exception as exc:
            print(f"Warning: touch read failed: {exc}", file=sys.stderr)

        time.sleep(0.05)


if __name__ == "__main__":
    try:
        main()
    finally:
        _cleanup()
        print("Exited cleanly.")

