import signal
import sys
import time

LED_PIN = 25  # BCM 25 (physical pin 22) with current-limiting resistor


class LEDController:
    """Blink an LED on a Raspberry Pi GPIO pin with robust error handling."""

    def __init__(self, pin: int):
        if not isinstance(pin, int) or pin < 0:
            raise ValueError(f"Invalid pin number: {pin!r}")
        self.pin = pin
        self._running = True
        self._old_handlers = {}

    def _install_signal_handlers(self):
        """Install SIGINT and SIGTERM handlers for graceful shutdown."""
        for sig in (signal.SIGINT, signal.SIGTERM):
            self._old_handlers[sig] = signal.getsignal(sig)
            signal.signal(sig, self._handle_signal)

    def _handle_signal(self, signum, frame):
        """Turn the LED off and exit on SIGINT/SIGTERM."""
        print(f"\nReceived signal {signum}; shutting down...")
        self._running = False
        self.off()
        if self._old_handlers[signal.SIGINT] is not None:
            self._old_handlers[signal.SIGINT](signum, frame)
        if self._old_handlers[signal.SIGTERM] is not None:
            self._old_handlers[signal.SIGTERM](signum, frame)
        sys.exit(0)

    def on(self):
        """Turn the LED on."""
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.pin, GPIO.OUT, initial=GPIO.LOW)
            GPIO.output(self.pin, GPIO.HIGH)
        except Exception as exc:
            print(f"Error turning LED on: {exc}")
            raise

    def off(self):
        """Turn the LED off."""
        try:
            import RPi.GPIO as GPIO
            GPIO.output(self.pin, GPIO.LOW)
        except Exception as exc:
            print(f"Error turning LED off: {exc}")
            raise

    def blink(self, on_duration: float, off_duration: float):
        """Blink the LED for on_duration seconds, then off_duration seconds."""
        if on_duration < 0 or off_duration < 0:
            raise ValueError("on_duration and off_duration must be non-negative")
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.pin, GPIO.OUT, initial=GPIO.LOW)
            GPIO.output(self.pin, GPIO.HIGH)
            time.sleep(on_duration)
            GPIO.output(self.pin, GPIO.LOW)
            time.sleep(off_duration)
        except Exception as exc:
            print(f"Error during blink cycle: {exc}")
            raise

    def cleanup(self):
        """Release GPIO resources."""
        try:
            import RPi.GPIO as GPIO
            GPIO.cleanup(self.pin)
        except Exception:
            pass


def main():
    controller = LEDController(LED_PIN)
    controller._install_signal_handlers()

    try:
        while controller._running:
            controller.blink(on_duration=1.0, off_duration=0.5)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        controller.off()
        controller.cleanup()
        print("LED turned off and GPIO cleaned up.")


if __name__ == "__main__":
    main()

