import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PIR_PIN = 23
DEBOUNCE_MS = 200
POLL_INTERVAL_S = 10
RUN_DURATION_S = 60
SENSOR_TIMEOUT_S = 30


class MotionCounter:
    """Monitors an HC-SR501 PIR motion sensor on a Raspberry Pi."""

    def __init__(self, pin: int, debounce_ms: int, poll_interval_s: int,
                 run_duration_s: int, sensor_timeout_s: int):
        self.pin = pin
        self.debounce_ms = debounce_ms
        self.poll_interval_s = poll_interval_s
        self.run_duration_s = run_duration_s
        self.sensor_timeout_s = sensor_timeout_s
        self.visitor_count = 0
        self._running = True
        self._last_motion_time = time.monotonic()
        self._setup_gpio()

    def _setup_gpio(self) -> None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info("GPIO %d configured as input (pull-down).", self.pin)
        except Exception as exc:
            logging.error("Failed to initialize GPIO %d: %s", self.pin, exc)
            raise

    def _read_sensor(self) -> bool:
        """Return True if the PIR output is HIGH (motion detected)."""
        try:
            return GPIO.input(self.pin) == GPIO.HIGH
        except Exception as exc:
            logging.error("Error reading GPIO %d: %s", self.pin, exc)
            return False

    def _update_last_motion_time(self) -> None:
        self._last_motion_time = time.monotonic()

    def _check_sensor_absent(self) -> bool:
        """Return True if no motion has been detected for the timeout window."""
        if self._last_motion_time is None:
            return False
        return (time.monotonic() - self._last_motion_time) > self.sensor_timeout_s

    def _debounce(self) -> bool:
        """Return True only if the current reading survives the debounce window."""
        time.sleep(self.debounce_ms / 1000.0)
        return self._read_sensor()

    def _tally_visitor(self) -> None:
        self.visitor_count += 1
        logging.info("Visitor %d", self.visitor_count)

    def _cleanup(self) -> None:
        self._running = False
        try:
            GPIO.cleanup(self.pin)
            logging.info("GPIO %d cleaned up.", self.pin)
        except Exception as exc:
            logging.error("Error during GPIO cleanup: %s", exc)

    def run(self) -> None:
        """Poll the PIR sensor, tally visitors, and clean up on exit."""
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        try:
            while self._running and (time.monotonic() < self.run_duration_s):
                if self._check_sensor_absent():
                    logging.warning("Sensor timeout: no motion detected for %.1f s.",
                                    self.sensor_timeout_s)
                else:
                    if self._debounce():
                        self._update_last_motion_time()
                        self._tally_visitor()
                time.sleep(self.poll_interval_s)
        except Exception as exc:
            logging.error("Unexpected error in run loop: %s", exc)
        finally:
            self._cleanup()


def _signal_handler(signum, frame):
    logging.info("Received signal %d, shutting down.", signum)
    sys.exit(0)


if __name__ == "__main__":
    counter = MotionCounter(PIR_PIN, DEBOUNCE_MS, POLL_INTERVAL_S,
                           RUN_DURATION_S, SENSOR_TIMEOUT_S)
    counter.run()

