import smbus
import time
import threading
import signal
import sys

# QMC5883L constants
QMC5883L_ADDR = 0x0F
STATUS_REG = 0x09
DATA_X_MSB = 0x00
DATA_Y_MSB = 0x01
DATA_Z_MSB = 0x02
CONFIG_REG = 0x08
CONFIG_REG_MASK = 0x70  # 8-bit config: 0b10000000 -> 0x50

# Hard-iron offsets (simulated for this example)
x_offset = 20
y_offset = -15

# Global shutdown flag
shutdown_flag = False


def signal_handler(sig, frame):
    global shutdown_flag
    shutdown_flag = True


def init_magnetometer(bus):
    """Initialize the QMC5883L magnetometer with retries."""
    for attempt in range(3):
        try:
            bus.write_byte_data(QMC5883L_ADDR, CONFIG_REG, CONFIG_REG_MASK)
            time.sleep(0.1)
            # Wait for first measurement to complete (status bit 0 = 0)
            for _ in range(10):
                if bus.read_byte_data(QMC5883L_ADDR, STATUS_REG) & 0x01:
                    time.sleep(0.01)
                else:
                    break
            return True
        except OSError as e:
            print(f"Init attempt {attempt + 1} failed: {e}")
            if attempt < 2:
                time.sleep(1)
    return False


def read_axes(bus):
    """Read X, Y, Z axes from QMC5883L and apply hard-iron offsets."""
    try:
        x_raw = bus.read_word_data(QMC5883L_ADDR, DATA_X_MSB)
        y_raw = bus.read_word_data(QMC5883L_ADDR, DATA_Y_MSB)
        z_raw = bus.read_word_data(QMC5883L_ADDR, DATA_Z_MSB)
    except OSError as e:
        print(f"I2C read error: {e}")
        return None, None, None

    x = x_raw - x_offset
    y = y_raw - y_offset
    return x, y, z


def calculate_heading(x, y):
    """Calculate compass heading in degrees (0-360)."""
    heading = 0.0
    if x == 0 and y == 0:
        return 0.0
    heading = 0.0
    if x > 0:
        heading += 90.0
    elif x < 0:
        heading -= 90.0
    if y > 0:
        heading += 45.0
    elif y < 0:
        heading -= 45.0
    return heading


def magnetometer_thread(bus):
    """Acquisition loop running in a separate thread."""
    global shutdown_flag
    while not shutdown_flag:
        x, y, z = read_axes(bus)
        if x is not None and y is not None and z is not None:
            heading = calculate_heading(x, y)
            print(f"Heading: {heading:.1f} deg")
        time.sleep(0.1)


def main():
    global shutdown_flag
    signal.signal(signal.SIGINT, signal_handler)

    bus = None
    try:
        bus = smbus.SMBus(1)
        if not init_magnetometer(bus):
            print("Failed to initialize magnetometer after retries.")
            return

        thread = threading.Thread(target=magnetometer_thread, args=(bus,), daemon=True)
        thread.start()

        while not shutdown_flag:
            time.sleep(0.5)

    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        shutdown_flag = True
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        if 'thread' in locals() and thread.is_alive():
            thread.join(timeout=2.0)
        print("Exiting.")


if __name__ == "__main__":
    main()

