import smbus
import time
import signal
import sys
from collections import Counter

# TCS34725 constants
TCS34725_I2C_ADDR = 0x00
TCS34725_COMMAND_BIT = 0x80
TCS34725_INTEGRATION_TIME_50MS = 0x00
TCS34725_GAIN_4X = 0x04
TCS34725_RGB_INTERFACE = 0x00

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c_bus():
    try:
        bus = smbus.SMBus(1)
        return bus
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C via raspi-config.")
        return None
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to i2c group.")
        return None
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_color_sensor(bus):
    try:
        bus.write_byte_data(TCS34725_I2C_ADDR, TCS34725_COMMAND_BIT | TCS34725_INTEGRATION_TIME_50MS, TCS34725_INTEGRATION_TIME_50MS)
        bus.write_byte_data(TCS34725_I2C_ADDR, TCS34725_COMMAND_BIT | TCS34725_GAIN_4X, TCS34725_GAIN_4X)
        return True
    except OSError as e:
        print(f"Error initializing TCS34725 (sensor absent or bus error): {e}")
        return False

def read_color_data(bus):
    try:
        # Write RGB interface command
        bus.write_byte_data(TCS34725_I2C_ADDR, TCS34725_COMMAND_BIT | TCS34725_RGB_INTERFACE, TCS34725_RGB_INTERFACE)
        # Read 4 bytes of color data
        data = bus.read_i2c_block_data(TCS34725_I2C_ADDR, TCS34725_COMMAND_BIT | TCS34725_RGB_INTERFACE, 4)
        if len(data) != 4:
            print("Error: Incomplete color data read.")
            return (0, 0, 0, 0)
        red = data[0] | (data[1] << 8)
        green = data[2] | (data[3] << 8)
        blue = data[4] | (data[5] << 8)
        return red, green, blue, 0
    except OSError as e:
        print(f"Error reading color data: {e}")
        return (0, 0, 0, 0)

def get_dominant_color(image_path, width=100, height=100):
    try:
        with open(image_path, 'rb') as f:
            image_data = f.read()
    except FileNotFoundError:
        print(f"Error: Image file not found at {image_path}")
        return (0, 0, 0)
    except OSError as e:
        print(f"Error reading image file: {e}")
        return (0, 0, 0)

    try:
        resized_image = image_data.resize((width, height), Image.LANCZOS)
        colors = resized_image.getcolors(width * height)
        if not colors:
            print("Error: No colors found in the image.")
            return (0, 0, 0)
        dominant_red, dominant_green, dominant_blue = max(colors, key=lambda item: item[0])[0]
        return dominant_red, dominant_green, dominant_blue
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def cleanup(bus):
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = initialize_i2c_bus()
    if bus is None:
        sys.exit(1)

    if not initialize_color_sensor(bus):
        cleanup(bus)
        sys.exit(1)

    try:
        while _running:
            red, green, blue, _ = read_color_data(bus)
            print(f"Raw Color Data: R={red}, G={green}, B={blue}")

            dominant_red, dominant_green, dominant_blue = get_dominant_color("image.jpg")

            print(f"Dominant Color: R={dominant_red}, G={dominant_green}, B={dominant_blue}")
            print("-" * 50)

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup(bus)

if __name__ == "__main__":
    main()

