DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_moisture_level():
    """Simulate a soil-moisture reading between 0 and 100 inclusive."""
    return random.randint(0, 100)

def control_water_pump(moisture_level, pump_pin):
    """Drive the pump HIGH if moisture is below threshold, else LOW."""
    if moisture_level < MOISTURE_THRESHOLD:
        print("Water Pump ON: Soil too dry")
        try:
            import RPi.GPIO as GPIO
            GPIO.output(pump_pin, GPIO.HIGH)
        except Exception as e:
            print(f"Error turning pump ON: {e}")
    else:
        print("Water Pump OFF: Soil moist enough")
        try:
            import RPi.GPIO as GPIO
            GPIO.output(pump_pin, GPIO.LOW)
        except Exception as e:
            print(f"Error turning pump OFF: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(WATER_PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    try:
        for i in range(1, ITERATIONS + 1):
            if not _running:
                break
            moisture = read_moisture_level()
            print(f"Iteration {i}: Soil Moisture = {moisture}%")
            control_water_pump(moisture, WATER_PUMP_PIN)
            if i < ITERATIONS and _running:
