import smbus
import time
import signal
import sys

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LIS3DH_ADDR = 0x48

LED_PIN = 21
BUZZER_PIN = 20

THRESHOLD_LOW = 0.3   # g  -> LED on
THRESHOLD_HIGH = 0.7  # g -> LED + buzzer on

SAMPLE_INTERVAL = 0.1
REPORT_INTERVAL = 1.0

# --- Globals for cleanup -----------------------------------------------------
bus = None
led_state = False
buzzer_state = False
running = True


def cleanup():
    """Turn off outputs and release hardware resources on every exit path."""
    global led_state, buzzer_state, bus
    try:
        if led_state:
            led_state = False
            if bus is not None:
                bus.write_byte(LIS3DH_ADDR, 0x00)
    except Exception:
        pass
    try:
        if buzzer_state:
            buzzer_state = False
            if bus is not None:
                bus.write_byte(LIS3DH_ADDR, 0x00)
    except Exception:
        pass
    try:
        if bus is not None:
            bus.close()
    except Exception:
        pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    global running
    running = False


def init_hardware():
    """Initialize GPIO and I2C bus. Returns True on success, False otherwise."""
    global bus, led_state, buzzer_state

    # --- GPIO setup ----------------------------------------------------------
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUZZER_PIN, GPIO.OUT, initial=GPIO.LOW)
        led_state = False
        buzzer_state = False
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        return False

    # --- I2C bus setup -------------------------------------------------------
    try:
        bus = smbus.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        cleanup()
        return False

    # --- LIS3DH WHO_AM_I verification ---------------------------------------
    try:
        who_am_i = bus.read_byte_data(LIS3DH_ADDR, 0x0D)
        if who_am_i != 0x1D:
            print(
                f"Error: LIS3DH not found at 0x{LIS3DH_ADDR:02X} "
                f"(WHO_AM_I=0x{who_am_i:02X}, expected 0x1D).",
                file=sys.stderr,
            )
            cleanup()
            return False
    except Exception as e:
        print(f"Error reading WHO_AM_I from LIS3DH: {e}", file=sys.stderr)
        cleanup()
        return False

    return True


def read_acceleration():
    """Read X-axis acceleration from the LIS3DH and return signed 16-bit value in g."""
    try:
        data = bus.read_i2c_block_data(LIS3DH_ADDR, 0x08, 2)
        raw = (data[0] << 8) | data[1]
        if raw >= 0x8000:
            raw -= 0x10000
        return raw * 0.0039
    except Exception as e:
        print(f"Error reading acceleration: {e}", file=sys.stderr)
        return None


def main():
    global running

    signal.signal(signal.SIGTERM, signal_handler)

    if not init_hardware():
        sys.exit(1)

    print("LIS3DH X-axis acceleration monitor started. Press Ctrl+C to exit.")

    try:
        while running:
            accel_x = read_acceleration()

            if accel_x is None:
                # I2C read error: turn off outputs for safety
                led_state = False
                buzzer_state = False
                time.sleep(SAMPLE_INTERVAL)
                continue

            # --- Threshold logic --------------------------------------------
            if abs(accel_x) > THRESHOLD_HIGH:
                if not led_state:
                    GPIO.output(LED_PIN, GPIO.HIGH)
                    led_state = True
                if not buzzer_state:
                    GPIO.output(BUZZER_PIN, GPIO.HIGH)
                    buzzer_state = True
                time.sleep(0.05)  # short delay after threshold activation
            elif abs(accel_x) > THRESHOLD_LOW:
                if led_state:
                    GPIO.output(LED_PIN, GPIO.LOW)
                    led_state = False
            else:
                if led_state:
                    GPIO.output(LED_PIN, GPIO.LOW)
                    led_state = False
                if buzzer_state:
                    GPIO.output(BUZZER_PIN, GPIO.LOW)
                    buzzer_state = False

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        cleanup()
        print("Program exited cleanly.")


if __name__ == "__main__":
    main()

