except ImportError:
    print("Error: RPi.GPIO is not installed. Install with: sudo apt install python3-rpi.gpio", file=sys.stderr)
    sys.exit(1)

DOOR_LOCK_PIN = 27
UNLOCK_DURATION = 5.0
LOOP_DELAY = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio(pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio(pin):
    try:
        GPIO.output(pin, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    setup_gpio(DOOR_LOCK_PIN)
    try:
        GPIO.output(DOOR_LOCK_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Error setting initial pin state: {e}", file=sys.stderr)
        cleanup_gpio(DOOR_LOCK_PIN)
        sys.exit(1)

    try:
        while _running:
            if not _running:
                break
            try:
                if not _simulate_authorization():
                    time.sleep(LOOP_DELAY)
                    continue
                print("Authorized. Unlocking door...")
