                    GPIO.output(DOOR_LOCK_PIN, GPIO.HIGH)
                except Exception as e:
                    print(f"Error setting pin HIGH: {e}", file=sys.stderr)
                    break
                time.sleep(UNLOCK_DURATION)
                try:
                    GPIO.output(DOOR_LOCK_PIN, GPIO.LOW)
                except Exception as e:
                    print(f"Error setting pin LOW: {e}", file=sys.stderr)
                    break
                print("Door locked.")
            except Exception as e:
                print(f"Error during loop iteration: {e}", file=sys.stderr)
                break
            time.sleep(LOOP_DELAY)
    finally:
        cleanup_gpio(DOOR_LOCK_PIN)
        print("GPIO cleanup completed.")

def _simulate_authorization():
    return True

if __name__ == "__main__":
