import smbus
import time
import math
import signal
import sys

# MPU6050 constants
MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_SCALE = 16384.0  # LSB/g at ±2 g range
THRESHOLD_MAGNITUDE = 2.5
THRESHOLD_VARIANCE = 0.4
NUM_SAMPLES = 8
SAMPLE_DELAY = 0.01  # 10 ms between samples

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def init_mpu6050(bus):
    """Initialize the MPU6050: wake from sleep and configure accelerometer range."""
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        time.sleep(0.1)  # Wait for sensor to stabilize
        bus.write_byte_data(MPU6050_ADDR, 0x1B, 0x00)  # ±2 g range
        time.sleep(0.01)
    except OSError as e:
        raise RuntimeError(f"Failed to initialize MPU6050: {e}")


def read_raw_accel(bus):
    """Read raw 6-axis data from the MPU6050 and return the X-axis acceleration."""
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, ACCEL_XOUT_H, 6)
        accel_x = (data[0] << 8) | data[1]
        return accel_x
    except OSError as e:
        raise RuntimeError(f"Failed to read accelerometer data: {e}")


def calculate_rms_magnitude(samples):
    """Calculate the RMS magnitude of a list of acceleration values."""
    if not samples:
        return 0.0
    return math.sqrt(sum(x * x for x in samples) / len(samples))


def calculate_variance(samples):
    """Calculate the sample variance of a list of acceleration values."""
    if not samples:
        return 0.0
    mean = sum(samples) / len(samples)
    return sum((x - mean) ** 2 for x in samples) / len(samples)


def evaluate_part(bus, num_samples):
    """Sample the accelerometer and classify the part as PASS or DEFECTIVE."""
    samples = []
    for _ in range(num_samples):
        try:
            raw = read_raw_accel(bus)
            samples.append(raw)
        except RuntimeError:
            return "ERROR", "Sensor read failed"
        time.sleep(SAMPLE_DELAY)

    magnitude = calculate_rms_magnitude(samples)
    variance = calculate_variance(samples)

    if magnitude > THRESHOLD_MAGNITUDE or variance > THRESHOLD_VARIANCE:
        return "DEFECTIVE", "Vibration exceeds threshold"
    return "PASS", "Vibration within acceptable range"


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = smbus.SMBus(1)
        init_mpu6050(bus)
        print("MPU6050 initialized successfully.")

        for i in range(NUM_SAMPLES):
            if not _running:
                print("Interrupted by user.")
                break
            part_status, reason = evaluate_part(bus, NUM_SAMPLES)
            print(f"Part {i + 1}/{NUM_SAMPLES}: {part_status} - {reason}")
            if part_status == "DEFECTIVE":
                print("Defect detected! Stopping production.")
                break

    except RuntimeError as e:
        print(f"Error: {e}")
    except OSError as e:
        print(f"I2C bus error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

