        duty_cycle = abs(duty_cycle)

        if duty_cycle == self._last_duty:
            return  # skip redundant writes

        if duty_cycle == 0:
            self.stop()
            return

        if self._inverted:
            duty_cycle = -duty_cycle

        try:
            self._motor.setSpeed(duty_cycle)
        except Exception as exc:
            raise RuntimeError(
                f"Failed to set duty cycle for motor {self.motor_num}: {exc}"
            ) from exc

        self._last_duty = duty_cycle

    def stop(self):
        """Stop the motor (duty cycle 0)."""
        self.set_dc(0)

    # ------------------------------------------------------------------
    # Status
    # ------------------------------------------------------------------
    def get_status(self):
        """Return a snapshot of the motor's current configuration."""
        return {
            "motor_num": self.motor_num,
            "pwm_frequency": self.get_pwm_freq(),
            "invert": self._inverted,
            "last_duty_cycle": self._last_duty,
        }

    # ------------------------------------------------------------------
    # Cleanup
    # ------------------------------------------------------------------
    def close(self):
        """Release the motor and mark it as closed."""
        if self._closed:
            return
        try:
            self.stop()
        except Exception as exc:
            print(f"Warning: error while stopping motor {self.motor_num}: {exc}",
                  file=sys.stderr)
        finally:
            self._closed = True

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass


# ----------------------------------------------------------------------
# Signal handling for clean shutdown
# ----------------------------------------------------------------------
_hat = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM by releasing all motors and exiting."""
    global _hat
    print(f"\nSignal {signum} received – shutting down cleanly.")
    if _hat is not None:
        for m in _hat.motors.values():
            try:
                m.close()
            except Exception:
                pass
    sys.exit(0)


def _release_all_motors():
    """Release every motor that has been created."""
    for m in list(_hat.motors.values()):
        try:
            m.close()
        except Exception:
            pass


# ----------------------------------------------------------------------
# Main entry point
# ----------------------------------------------------------------------
_hat = None


def main():
    """Demonstrate motor control with ramping and clean shutdown."""
    global _hat

    # --- Initialize I2C bus and HAT -------------------------------------------------
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Failed to initialize I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _hat = DCMotorHATExtra(i2c, address=0x40)
    except Exception as exc:
        print(f"Failed to initialize DC Motor HAT at 0x40: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- Create motor #1 ----------------------------------------------------------
    try:
        m = DCMotor(_hat, motor_num=1, freq=60, invert=False)
    except Exception as exc:
        print(f"Failed to create motor 1: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- Ramp forward and backward ----------------------------------------------
    print("Ramping motor 1 forward...")
    for dc in range(0, 256, 5):
        m.set_dc(dc)
        time.sleep(0.05)
    m.set_dc(0)
    time.sleep(0.5)

    print("Ramping motor 1 backward...")
    for dc in range(0, -256, -5):
        m.set_dc(dc)
        time.sleep(0.05)
    m.set_dc(0)
    time.sleep(0.5)

    # --- Clean shutdown ---------------------------------------------------------
    _release_all_motors()
    if _hat is not None:
        _hat = None


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    atexit.register(_release_all_motors)
    main()

