    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(LEFT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(RIGHT_MOTOR_PIN, GPIO.OUT, initial=GPIO.LOW)

def read_sensors():
    try:
        return GPIO.input(LEFT_SENSOR_PIN), GPIO.input(RIGHT_SENSOR_PIN)
    except Exception as e:
        print(f"Sensor read error: {e}", file=sys.stderr)
        return None, None

def control_motors(left_state, right_state):
    try:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.HIGH if left_state else GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.HIGH if right_state else GPIO.LOW)
    except Exception as e:
        print(f"Motor control error: {e}", file=sys.stderr)

def steer(left_state, right_state):
    if left_state and not right_state:
        control_motors(0, 1)
    elif right_state and not left_state:
        control_motors(1, 0)
    elif left_state and right_state:
        control_motors(0, 0)
    else:
        control_motors(0, 0)

def cleanup_gpio():
    try:
        GPIO.output(LEFT_MOTOR_PIN, GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        cleanup_gpio()
        sys.exit(1)

    iteration = 0
    try:
        while _running and iteration < 20:
            left_state, right_state = read_sensors()
            if left_state is None or right_state is None:
                time.sleep(0.1)
                continue
            steer(left_state, right_state)
            iteration += 1
            time.sleep(0.1)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
