import logging
from enum import Enum
from typing import Optional

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")

try:
    from library import MotorDriver
except ImportError:
    MotorDriver = None

class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass

class MotorDirection(Enum):
    """Direction constants for the motor."""
    FORWARD = 1
    BACKWARD = 2
    STOP = 3

class Motor:
    """
    A class to control a DC motor using a driver library.

    Args:
        driver_library (MotorDriver): The driver library instance.
        pin_number (int): The BCM pin number connected to the motor driver.
    """

    def __init__(self, driver_library: MotorDriver, pin_number: int):
        if not isinstance(driver_library, MotorDriver):
            raise MotorError("driver_library must be a MotorDriver instance")
        if not isinstance(pin_number, int) or pin_number < 0:
            raise MotorError("pin_number must be a non-negative integer")

        self.driver_library = driver_library
        self.pin_number = pin_number
        self._closed = False

        try:
            self.driver_library.set_pin_as_output(self.pin_number)
            self.set_frequency(1000)
            self.set_duty_cycle(0)
        except Exception as e:
            logging.error(f"Error initializing motor on pin {self.pin_number}: {e}")
            raise MotorError(f"Failed to initialize motor on pin {self.pin_number}") from e

    def set_frequency(self, frequency: int) -> None:
        """Sets the PWM frequency."""
        if not isinstance(frequency, int):
            raise MotorError("frequency must be an integer")
        if frequency <= 0:
            raise MotorError("frequency must be positive")
        try:
            self.driver_library.set_pwm_frequency(self.pin_number, frequency)
        except Exception as e:
            logging.error(f"Error setting frequency to {frequency} Hz: {e}")
            raise MotorError(f"Failed to set frequency to {frequency} Hz") from e

    def set_duty_cycle(self, duty_cycle: int) -> None:
        """
        Sets the motor duty cycle.

        Args:
            duty_cycle (int): The duty cycle value (0-255).

        Raises:
            MotorError: If the duty cycle value is out of range or the
                driver call fails.
        """
        if not isinstance(duty_cycle, int):
            raise MotorError("duty_cycle must be an integer")
        if not 0 <= duty_cycle <= 255:
            raise MotorError("duty_cycle must be between 0 and 255")
        try:
            self.driver_library.set_pwm_duty_cycle(self.pin_number, duty_cycle)
        except Exception as e:
            logging.error(f"Error setting duty cycle to {duty_cycle}: {e}")
            raise MotorError(f"Failed to set duty cycle to {duty_cycle}") from e

    def stop(self) -> None:
        """Stops the motor by setting the duty cycle to 0."""
        try:
            self.set_duty_cycle(0)
        except MotorError as e:
            logging.error(f"Error stopping motor: {e}")

    def close(self) -> None:
        """Releases the motor resources."""
        if self._closed:
            return
        try:
            self.stop()
        except MotorError as e:
            logging.error(f"Error during stop during close: {e}")
        finally:
            self._closed = True

    def __del__(self):
        """Destructor to ensure the motor is stopped and resources are released."""
        try:
            self.close()
        except Exception as e:
            logging.error(f"Error during __del__ cleanup: {e}")

