import serial
import time
import signal
import sys

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is required. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQUENCY = 50  # Hz
DUTY_CYCLE_MIN = 1.0 / 1000.0   # 1 ms
DUTY_CYCLE_MAX = 2.0 / 1000.0   # 2 ms

running = True
serial_connection = None
servo = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global serial_connection, servo
    if servo is not None:
        try:
            servo.close()
        except Exception:
            pass
        servo = None
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
        except Exception:
            pass
        serial_connection = None


def set_servo_angle(angle):
    if servo is None:
        print("Error: Servo not initialized.", file=sys.stderr)
        return
    try:
        duty_cycle = DUTY_CYCLE_MIN + (angle / 180.0) * (DUTY_CYCLE_MAX - DUTY_CYCLE_MIN)
        servo.value = duty_cycle
        time.sleep(1)
        servo.value = 0
    except Exception as e:
        print(f"Error setting servo angle: {e}", file=sys.stderr)


def main():
    global serial_connection, servo

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        servo = PWMOutputDevice(SERVO_PIN, frequency=PWM_FREQUENCY, initial_value=0)
        print(f"PWM initialized on BCM pin {SERVO_PIN} at {PWM_FREQUENCY} Hz.")
    except Exception as e:
        print(f"Error initializing servo PWM: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_connection.readline()
                if not raw:
                    continue
                angle_str = raw.decode('ascii', errors='replace').strip()
                if not angle_str:
                    continue
                angle = int(angle_str)
                if not (0 <= angle <= 180):
                    print(f"Error: Angle {angle} out of range (0-180).")
                    continue
                set_servo_angle(angle)
            except ValueError:
                print("Error: Could not convert received data to integer.")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error in main loop: {e}")
                break
    finally:
        cleanup()


if __name__ == '__main__':
    main()

