class ModbusRTUController:
    """Encapsulates a Modbus RTU servo motor controller over UART."""

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200):
        """Initialize the Modbus RTU client."""
        self._port = port
        self._baudrate = baudrate
        self._uart = None
        signal.signal(signal.SIGINT, _signal_handler)
        signal.signal(signal.SIGTERM, _signal_handler)
        try:
            self._uart = ModbusRTU._uart = self._open_uart()
            logger.info("UART opened on %s at %d baud", port, baudrate)
        except Exception as exc:
            logger.error("Failed to open UART on %s: %s", port, exc)
            self._uart = None

    def _open_uart(self) -> Any:
        """Open the UART device, degrading gracefully if unavailable."""
        try:
            import serial
            return serial.Serial(
                port=self._port,
                baudrate=self._baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS

