                logger.warning("Register 0x%04X is not readable (R/W != R)", address)
                return None
            fc = ModbusRTU._registers[address]["functioncode"]
            logger.debug("Reading single register 0x%04X", address)
            response = ModbusRTU._uart.read_single_register(
                address=address,
                functioncode=fc,
            )
            if response is None or response != address:
                logger.warning("Modbus read of 0x%04X failed (got %d)", address, response)
                return None
            return address
    except Exception as exc:
        logger.error("Error reading single register 0x%04X: %s", address, exc)
        return None


