    bus.write_byte_data(PCA9685_ADDRESS, reg, value)


def _read_register(bus, reg):
    return bus.read_byte_data(PCA9685_ADDRESS, reg)


def initialize():
    global _bus
    try:
        _bus = smbus2.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to i2c group.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _write_register(_bus, MODE1, 0x00)
        _write_register(_bus, PRESCALE, 0x00)
        _write_register(_bus, ALL_LED_ON_L, 0x00)
    except OSError as e:
        print(f"Error initializing PCA9685 at 0x{PCA9685_ADDRESS:02X}: {e}", file=sys.stderr)
        _bus.close()
        _bus = None
        sys.exit(1)


def _set_pwm(bus, channel, on, off):
    if not 0 <= channel <= 15:
        raise ValueError(f"Invalid channel {channel}; must be 0-15")
    if not 0 <= on <= 4095 or not 0 <= off <= 4095:
        raise ValueError(f"Invalid PWM values; must be 0-4095")
    try:
        _write_register(bus, LED0_ON_L + channel, on)
        _write_register(bus, ALL_LED_ON_L + channel, off)
    except OSError as e:
        raise RuntimeError(f"I2C write error on channel {channel}: {e}")


def set_angle(channel, angle):
    if not 0 <= channel <= 15:
        raise ValueError(f"Invalid channel {channel}; must be 0-15")
    if not 0 <= angle <= 180:
        raise ValueError(f"Invalid angle {angle}; must be 0-180")
    _set_pwm(_bus, channel, 0, int((angle / 180.0) * 4095))


def move_servo(channel, target_angle, step_size=5, delay=0.04):
    if not 0 <= channel <= 15:
        raise ValueError(f"Invalid channel {channel}; must be 0-15")
    if not 0 <= target_angle <= 180:
        raise ValueError(f"Invalid target angle {target_angle}; must be 0-180")
    if step_size <= 0:
        raise ValueError(f"step_size must be positive, got {step_size}")
    if delay < 0:
        raise ValueError(f"delay must be non-negative, got {delay}")

    current = _set_pwm(_bus, channel, 0, 0)
    current_angle = int(current / 4095 * 180)
    current_angle = max(0, min(180, current_angle))

    if target_angle > current_angle:
        steps = int(abs(target_angle - current_angle) / step_size)
        for _ in range(steps):
            if not _running:
                return current_angle
            _set_pwm(_bus, channel, int(current_angle / 4095 * 4095), 0)
            time.sleep(delay)
            current_angle += step_size
        _set_pwm(_bus, channel, int(current_angle / 4095 * 4095), 0)
    else:
        steps = int(abs(target_angle - current_angle) / step_size)
        for _ in range(steps):
            if not _running:
                return current_angle
            _set_pwm(_bus, channel, 0, int(current_angle / 4095 * 4095))
            time.sleep(delay)
            current_angle += step_size
        _set_pwm(_bus, channel, 0, int(current_angle / 4095 * 4095))

    return int(current_angle / 4095 * 180)


