    return move_servo(SEEK_CHANNEL, angle)


def deseek(angle):
    return move_servo(SEEK_CHANNEL, angle)


def drop(angle):
    return move_servo(DROP_CHANNEL, angle)


def pick(angle):
    return move_servo(DROP_CHANNEL, angle)


def grab(angle):
    return move_servo(GRAB_CHANNEL, angle)


def release(angle):
    return move_servo(GRAB_CHANNEL, angle)


def collect_object_steps(seek_angle):
    try:
        seek_angle = move_servo(SEEK_CHANNEL, seek_angle)
        grab_angle = move_servo(GRAB_CHANNEL, grab_angle)
        drop_angle = move_servo(DROP_CHANNEL, drop_angle)
        pick_angle = move_servo(DROP_CHANNEL, pick_angle)
        deseek_angle = move_servo(SEEK_CHANNEL, deseek_angle)
        return seek_angle, grab_angle, drop_angle, pick_angle, deseek_angle
    except Exception as e:
        print(f"Error during collect_object_steps: {e}", file=sys.stderr)
        return None, None, None, None, None


def drop_object_steps(drop_angle, release_angle=120):
    try:
        drop_pos = move_servo(DROP_CHANNEL, drop_angle, step_size=2, delay=0.01)
        release_angle = move_servo(GRAB_CHANNEL, release_angle)
        return move_servo(DROP_CHANNEL, drop_angle, step_size=2, delay=0.01), release_angle
    except Exception as e:
        print(f"Error during drop_object_steps: {e}", file=sys.stderr)
        return None, None


def get_pos_x(x_center):
    if not 0 <= x_center <= 320:
        raise ValueError(f"X center must be 0-320, got {x_center}")
    return max(0, min(180, int((x_center / 320.0) * 180)))


def get_pos_y(y_center):
    if not 0 <= y_center <= 320:
        raise ValueError(f"Y center must be 0-320, got {y_center}")
    return max(0, min(180, int((y_center / 320.0) * 180)))


def collect_object(x_center, y_center, drop_angle):
    try:
