        seek_pos = get_pos_y(y_center)
        seek_angle = seek(seek_pos)
        collect_steps = collect_object_steps(seek_angle)
        if collect_steps:
            base_pos, grab_angle, drop_angle, pick_angle, deseek_angle = collect_steps
            return base_pos, grab_angle, drop_angle, pick_angle, deseek_angle
        return None, None, None, None, None
    except Exception as e:
        print(f"Error during collect_object: {e}", file=sys.stderr)
        return None, None, None, None, None


def cleanup():
    global _bus
    if _bus is not None:
        try:
            _set_pwm(_bus, DROP_CHANNEL, 0, 0)
            _set_pwm(_bus, BASE_CHANNEL, 0, 0)
            _set_pwm(_bus, SEEK_CHANNEL, 0, 0)
            _set_pwm(_bus, GRAB_CHANNEL, 0, 0)
            _set_pwm(_bus, DROP_CHANNEL, 0, 0)
            _bus.write_byte_data(PCA9685_ADDRESS, MODE1, 0x00)
            _bus.write_byte_data(PCA9685_ADDRESS, PRESCALE, 0x00)
            _bus.write_byte_data(PCA9685_ADDRESS, ALL_LED_ON_L, 0x00)
            _bus.close()
        except Exception:
            pass
        _bus = None


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        initialize()
        print("PCA9685 initialized. Running in demo mode. Press Ctrl+C to exit.")
        while _running:
            time.sleep(0.5)
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Exited cleanly.")


if __name__ == "__main__":
    main()

