import curses
import os
import signal
import sys
import time

try:
    from adafruit_pca9685 import PCA9685
except ImportError:
    print("Error: adafruit-circuitpython-pca9685 is not installed.")
    print("Install with: pip install adafruit-circuitpython-pca9685")
    sys.exit(0)

I2C_BUS = 1
PWM_FREQUENCY = 60
PCA9685_ADDRESS = 0x40
PCA9685_CHANNELS = 16
PCA9685_DEFAULT_ADDRESS = 0x40
PCA9685_DEFAULT_BUS = 1

PWM_CHANNEL_ESC = 0
PWM_CHANNEL_STEERING = 1
THROTTLE_STOP_VALUE = 400
CALIBRATION_VALUES = (200, 600)
CALIBRATION_INCREMENT = 20
CALIBRATION_DELAY = 0.1
CENTERED_STEERING_VALUE = 500

ESC_MAX = 620
ESC_MIN = 380
STEERING_MAX = 620
STEERING_MIN = 380

ESC_MAX_VALUE = ESC_MAX
ESC_MIN_VALUE = ESC_MIN
STEERING_MAX_VALUE = STEERING_MAX
STEERING_MIN_VALUE = STEERING_MIN
STEERING_CENTER_VALUE = CENTERED_STEERING_VALUE

pwm = None
running = True


def cleanup():
    global pwm, running
    running = False
    try:
        if pwm is not None:
            try:
                pwm.channels[PWM_CHANNEL_ESC].duty_cycle = THROTTLE_STOP_VALUE
            except Exception:
                pass
            try:
                pwm.channels[PWM_CHANNEL_STEERING].duty_cycle = STEERING_CENTER_VALUE
            except Exception:
                pass
            try:
                pwm.deinit()
            except Exception:
                pass
    except Exception:
        pass
    try:
        if os.environ.get("TERM") is not None and sys.stdout.isatty():
            os.environ["TERM"] = sys.stdout.termname
    except Exception:
        pass


def signal_handler(signum, frame):
    cleanup()
    sys.exit(0)


def initialize_pca9685():
    global pwm
    try:
        pwm = PCA9685(address=PCA9685_ADDRESS, busnum=I2C_BUS)
        pwm.frequency = PWM_FREQUENCY
        pwm.channels[PWM_CHANNEL_ESC].duty_cycle = THROTTLE_STOP_VALUE
        pwm.channels[PWM_CHANNEL_STEERING].duty_cycle = STEERING_CENTER_VALUE
        return True
    except Exception as e:
        print(f"Error initializing PCA9685: {e}")
        return False


def calibrate_esc():
    global ESC_MAX_VALUE, ESC_MIN_VALUE, ESC_MAX_VALUE, ESC_MIN_VALUE
    print("Calibrating ESC...")
    try:
        for i in range(*CALIBRATION_VALUES):
            pwm.channels[PWM_CHANNEL_ESC].duty_cycle = i
            time.sleep(CALIBRATION_DELAY)
        for i in range(*CALIBRATION_VALUES, reverse=True):
            pwm.channels[PWM_CHANNEL_ESC].duty_cycle = i
            time.sleep(CALIBRATION_DELAY)
        pwm.channels[PWM_CHANNEL_ESC].duty_cycle = THROTTLE_STOP_VALUE
        print("ESC calibration complete.")
        ESC_MAX_VALUE = ESC_MAX
        ESC_MIN_VALUE = ESC_MIN
        ESC_MAX_VALUE = ESC_MAX
        ESC_MIN_VALUE = ESC_MIN
    except Exception as e:
        print(f"Error during ESC calibration: {e}")
        ESC_MAX_VALUE = ESC_MAX
        ESC_MIN_VALUE = ESC_MIN
        ESC_MAX_VALUE = ESC_MAX
        ESC_MIN_VALUE = ESC_MIN


def get_user_input():
    try:
        return curses.getkey()
    except Exception:
        return None


def main_loop():
    global ESC_MAX_VALUE, ESC_MIN_VALUE, ESC_MAX_VALUE, ESC_MIN_VALUE
    try:
        curses.curs_set(0)
        while running:
            try:
                key = get_user_input()
            except Exception:
                key = None

            if key == ord('q'):
                break

            if key == ord('x'):
                break

            if key == curses.KEY_UP and ESC_MAX_VALUE < ESC_MAX:
                ESC_MAX_VALUE += CALIBRATION_INCREMENT
                print(f"Max Value: {ESC_MAX_VALUE}")
            elif key == curses.KEY_DOWN and ESC_MIN_VALUE > ESC_MIN:
                ESC_MIN_VALUE += CALIBRATION_INCREMENT
                print(f"Min Value: {ESC_MIN_VALUE}")
            elif key == curses.KEY_LEFT and STEERING_MAX_VALUE > STEERING_MIN_VALUE:
                STEERING_MAX_VALUE -= CALIBRATION_INCREMENT
                print(f"Max Steering Value: {STEERING_MAX_VALUE}")
            elif key == curses.KEY_RIGHT and STEERING_MIN_VALUE < STEERING_CENTER_VALUE:
                STEERING_MIN_VALUE += CALIBRATION_INCREMENT
                print(f"Min Steering Value: {STEERING_MIN_VALUE}")
            elif key == curses.KEY_LEFT and STEERING_MAX_VALUE > STEERING_MIN_VALUE:
                STEERING_MAX_VALUE -= CALIBRATION_INCREMENT
                print(f"Max Steering Value: {STEERING_MAX_VALUE}")
            elif key == curses.KEY_RIGHT and STEERING_MIN_VALUE < STEERING_CENTER_VALUE:
                STEERING_MIN_VALUE += CALIBRATION_INCREMENT
                print(f"Min Steering Value: {STEERING_MIN_VALUE}")

            if key == curses.KEY_ENTER:
                break

            try:
                pwm.channels[PWM_CHANNEL_ESC].duty_cycle = ESC_MAX_VALUE
            except Exception as e:
                print(f"Error setting ESC duty cycle: {e}")

            try:
                pwm.channels[PWM_CHANNEL_STEERING].duty_cycle = STEERING_CENTER_VALUE
            except Exception as e:
                print(f"Error setting steering duty cycle: {e}")

    except Exception as e:
        print(f"Error in main loop: {e}")
    finally:
        cleanup()


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not os.environ.get("TERM") or not sys.stdout.isatty():
        print("Not running in a terminal. Exiting cleanly.")
        sys.exit(0)

    if not initialize_pca9685():
        sys.exit(0)

    try:
        calibrate_esc()
        main_loop()
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

