from digitalio import DigitalInOut, Direction

PUMP_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_S = 10
I2C_ADDRESS = 0x48  # Default Seesaw I2C address; may be 0x3E on some boards

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


