    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        return None


def initialize_seesaw(i2c_bus):
    try:
        sensor = Seesaw(i2c_bus, addr=I2C_ADDRESS)
        return sensor
    except Exception as exc:
        print(f"Error initializing Seesaw sensor at 0x{I2C_ADDRESS:02X}: {exc}", file=sys.stderr)
        return None


def initialize_pump(pin):
    try:
        pump = DigitalInOut(pin)
        pump.direction = Direction.OUTPUT
        pump.value = False
        return pump
    except Exception as exc:
        print(f"Error initializing pump on GPIO{pin}: {exc}", file=sys.stderr)
        return None


def read_moisture(sensor):
    try:
        return sensor.moisture_read()
    except Exception as exc:
        print(f"Error reading soil moisture: {exc}", file=sys.stderr)
        return None


def control_pump(pump, moisture_level, dry_threshold):
    if moisture_level is None:
        print("Pump: UNKNOWN (sensor read failed)")
        return
    if moisture_level < dry_threshold:
        pump.value = True
        print(f"Pump: ON (soil too dry: {moisture_level})")
    else:
        pump.value = False
        print(f"Pump: OFF (soil moisture OK: {moisture_level})")


def cleanup(pump, i2c_bus):
    if pump is not None:
        try:
            pump.value = False
            print("Pump: OFF (safety)")
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    sensor = initialize_seesaw(i2c_bus)
    if sensor is None:
        cleanup(None, i2c_bus)
        sys.exit(1)

