import time
import signal
import sys

# ServoKit library (PCA9685 16-channel PWM driver) for Raspberry Pi.
# The Adafruit 16-Channel PWM/Servo HAT uses the PCA9685 by default.
try:
    from adafruit_servokit import ServoKit
except ImportError:
    ServoKit = None

# Constants
I2C_BUS = 1
SERVO_CHANNELS = 16
MIN_CHANNEL = 0
MAX_CHANNEL = 15
MIN_ANGLE = 0
MAX_ANGLE = 180
STEP_DEGREES = 5
STEP_DELAY = 0.04
GRAB_ANGLE = 90
RELEASE_ANGLE = 150


def validate_channel(channel: int) -> None:
    """Validate that the requested channel is within the allowed range."""
    if not (MIN_CHANNEL <= channel <= MAX_CHANNEL):
        raise ValueError(f"Channel must be between {MIN_CHANNEL} and {MAX_CHANNEL}: {channel}")


def validate_angle(angle: int) -> None:
    """Validate that the requested angle is within the allowed range."""
    if not (MIN_ANGLE <= angle <= MAX_ANGLE):
        raise ValueError(f"Angle must be between {MIN_ANGLE} and {MAX_ANGLE}: {angle}")


def initialize_servokit() -> ServoKit:
    """Initialize the ServoKit object, handling potential import errors."""
    if ServoKit is None:
        raise ImportError("ServoKit library is not installed. Install with: pip install adafruit-circuitpython-servokit")
    try:
        return ServoKit(channels=SERVO_CHANNELS, i2c=None, address=0)
    except Exception as e:
        raise RuntimeError(f"Failed to initialize ServoKit: {e}")


def move_servo(kit: ServoKit, channel: int, target_angle: int) -> None:
    """Move a servo to a target angle in 5-degree increments."""
    validate_channel(channel)
    validate_angle(target_angle)

    current_angle = kit.servo[channel].angle
    if current_angle is None:
        current_angle = 0

    step = STEP_DEGREES if target_angle > current_angle else -STEP_DEGREES
    angle = current_angle
    while True:
        angle += step
        if angle > target_angle:
            angle = target_angle
        try:
            kit.servo[channel].angle = angle
        except Exception as e:
            raise RuntimeError(f"Failed to set servo {channel} angle: {e}")
        time.sleep(STEP_DELAY)


def grab_object(kit: ServoKit) -> None:
    """Grab an object using servo channel 0 at 90 degrees."""
    move_servo(kit, 0, GRAB_ANGLE)


def release_object(kit: ServoKit) -> None:
    """Release an object using servo channel 0 at 150 degrees."""
    move_servo(kit, 0, RELEASE_ANGLE)


def cleanup(kit: ServoKit) -> None:
    """Release all servos and clean up resources."""
    for ch in range(MIN_CHANNEL, MAX_CHANNEL + 1):
        try:
            kit.servo[ch].angle = None
        except Exception:
            pass
    print("Servos released.")


def main() -> None:
    """Main function to demonstrate servo control."""
    kit = None
    try:
        kit = initialize_servokit()
        print("ServoKit initialized successfully.")

        # Example usage: grab, release, and move an object
        grab_object(kit)
        time.sleep(1)
        release_object(kit)
        time.sleep(1)

        # Move servo on channel 1 to 45 degrees
        move_servo(kit, 1, 45)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        if kit is not None:
            cleanup(kit)


if __name__ == "__main__":
    main()

