    global _pump, _light
    for dev in (_pump, _light):
        if dev is not None:
            try:
                dev.off()
                dev.close()
            except Exception as exc:
                logger.warning("Error closing %s: %s", dev, exc)
    _pump = None
    _light = None


def _handle_signal(signum, frame):
    logger.info("Received signal %s, shutting down.", signum)
    _cleanup()
    sys.exit(0)


def parse_intent(phrase):
    """Return one of pump_on, pump_off, or light_toggle for a phrase."""
    phrase = phrase.strip().lower()
    if not phrase:
        return None
    if "turn the pump on" in phrase:
        return "pump_on"
    if "switch the light" in phrase:
        return "light_toggle"
    if "turn pump off" in phrase:
        return "pump_off"
    return None


def main():
