#!/usr/bin/env python3
"""DS1338 Real-Time Clock Driver for Raspberry Pi.

Uses smbus2 for I2C communication on bus 1 (GPIO2=SDA, GPIO3=SCL).
Requires: pip install smbus2
"""

import signal
import sys
import time
from datetime import datetime

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("This script requires the 'smbus2' package. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)


class DS1338:
    """Driver for the Maxim DS1338 I2C RTC (address 0x68)."""

    # Register addresses
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    # Bit masks
    MASK_SECONDS = 0x7F
    MASK_HOURS_24H = 0x3F  # bit 6 is the 12/24-hour flag
    MASK_CONTROL = 0x80

    def __init__(self, bus_number=1, address=0x68):
        self.address = address
        self._bus = None
        try:
            self._bus = SMBus(bus_number)
        except OSError as exc:
            raise RuntimeError(f"Cannot open I2C bus {bus_number}: {exc}") from exc

        # Verify device presence
        try:
            self._read_register(self.REG_CONTROL)
        except OSError:
            self.close()
            raise RuntimeError(
                f"No DS1338 found at address 0x{address:02X} on bus {bus_number}. "
                "Check wiring and pull-up resistors."
            ) from OSError

    def close(self):
        """Release the I2C bus handle."""
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def _write_register(self, register, data):
        """Write a single byte to a register."""
        try:
            self._bus.write_byte_data(self.address, register, data)
        except OSError as exc:
            raise RuntimeError(f"I2C write to register 0x{register:02X} failed: {exc}") from exc

    def _read_register(self, register):
        """Read a single byte from a register."""
        try:
            return self._bus.read_byte_data(self.address, register)
        except OSError as exc:
            raise RuntimeError(f"I2C read from register 0x{register:02X} failed: {exc}") from exc

    def _bcd_to_int(self, bcd):
        """Convert BCD byte to integer."""
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    def _int_to_bcd(self, integer):
        """Convert integer (0-99) to BCD byte."""
        if not 0 <= integer <= 99:
            raise ValueError(f"Integer value must be 0-99, got {integer}")
        return ((integer // 10) << 4) | (integer % 10)

    def _read_all(self):
        """Read all date/time registers and return as a dict."""
        data = {}
        for reg, name in ((self.REG_SECONDS, "seconds"),
                          (self.REG_MINUTES, "minutes"),
                          (self.REG_HOURS, "hours"),
                          (self.REG_DAY, "day"),
                          (self.REG_DATE, "date"),
                          (self.REG_MONTH, "month"),
                          (self.REG_YEAR, "year")):
            try:
                data[reg] = self._bcd_to_int(self._read_register(reg))
            except RuntimeError:
                data[reg] = None
        return data

    def _read_datetime(self, century=21):
        """Read date/time and return a datetime object."""
        data = self._read_all()
        if data is None or any(v is None for v in data.values()):
            raise RuntimeError("Incomplete data read from DS1338.")

        seconds = data[self.REG_SECONDS]
        minutes = data[self.REG_MINUTES]
        hours = data[self.REG_HOURS]
        day = data[self.REG_DAY]
        date = data[self.REG_DATE]
        month = data[self.REG_MONTH]
        year = data[self.REG_YEAR]

        # Validate ranges
        if not (0 <= seconds <= 59 and 0 <= minutes <= 59 and 0 <= hours <= 23
                and 1 <= day <= 31 and 1 <= date <= 12
                and 1 <= month <= 12 and 0 <= year <= 99):
            raise ValueError(f"Invalid date/time values: {data}")

        # Year is stored as the low two BCD digits; century is applied externally
        year = (year + 2000) % 100
        return datetime(year, month, date, hours, minutes, seconds)

    def _write_all(self, seconds=None, minutes=None, hours=None, day=None,
                   date=None, month=None, year=None):
        """Write date/time fields to the RTC."""
        data = {}
        if seconds is not None:
            data[self.REG_SECONDS] = self._int_to_bcd(seconds)
        if minutes is not None:
            data[self.REG_MINUTES] = self._int_to_bcd(minutes)
        if hours is not None:
            # 24-hour format: bit 6 is the 12/24-hour flag; clear it
            data[self.REG_HOURS] = self._int_to_bcd(hours) & 0x3F
        if day is not None:
            data[self.REG_DAY] = self._int_to_bcd(day)
        if date is not None:
            data[self.REG_DATE] = self._int_to_bcd(date)
        if month is not None:
            data[self.REG_MONTH] = self._int_to_bcd(month)
        if year is not None:
            data[self.REG_YEAR] = self._int_to_bcd(year % 100)

        for reg, value in data.items():
            try:
                self._write_register(reg, value)
            except RuntimeError:
                # Continue writing remaining fields on error
                pass

    def write_datetime(self, dt, century=21):
        """Write a datetime object to the RTC."""
        self._write_all(
            seconds=dt.second,
            minutes=dt.minute,
            hours=dt.hour,
            day=dt.isoweekday(),
            date=dt.day,
            month=dt.month,
            year=dt.year % 100,
        )


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting.", file=sys.stderr)
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    rtc = None
    try:
        rtc = DS1338(bus_number=1, address=0x68)
        print("DS1338 initialized successfully.")

        now = datetime.now()
        print(f"Current RTC time: {now.strftime('%Y-%m-%d %H:%M:%S')}")
        print(f"Current system time: {now.strftime('%Y-%m-%d %H:%M:%S')}")
        time.sleep(2)

        # Example: set RTC to a specific time
        target = datetime(2024, 12, 25, 12, 0, 0)
        print(f"Setting RTC to: {target.strftime('%Y-%m-%d %H:%M:%S')}")
        rtc.write_datetime(target, century=2024)
        print("RTC time set.")

    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
    except ValueError as exc:
        print(f"Value error: {exc}", file=sys.stderr)
    except OSError as exc:
        print(f"I2C bus error: {exc}", file=sys.stderr)
    finally:
        if rtc is not None:
            rtc.close()
        print("Program finished.")


if __name__ == "__main__":
    main()

