import serial
import time
import signal
import sys
import re

ESP_OK = b'OK'
ESP_ERROR = b'ERROR'
ESP_FAIL = b'FAIL'
ESP_READY = b'ready'

ESP_OK_RE = re.compile(r'^OK$')
ESP_ERROR_RE = re.compile(r'^ERROR$')
ESP_FAIL_RE = re.compile(r'^FAIL$')
ESP_READY_RE = re.compile(r'^ready$')


class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self._uart = None
        self._timeout = timeout
        try:
            self._uart = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout,
                write_timeout=timeout,
            )
        except serial.SerialException as exc:
            print(f"Error: cannot open UART port {port}: {exc}", file=sys.stderr)
            raise

    def _send_command(self, command, wait_for=None, timeout=None):
        if self._uart is None:
            return None
        try:
            self._uart.reset_input_buffer()
            self._uart.write(command)
            self._uart.flush()
            if wait_for is not None:
                response = b''
                start_time = time.monotonic()
                while time.monotonic() - start_time < timeout:
                    if self._uart.in_waiting > 0:
                        chunk = self._uart.read(self._uart.in_waiting)
                        if chunk:
                            response += chunk
                            if wait_for in response:
                                break
                    else:
                        time.sleep(0.01)
                return response
            return None
        except serial.SerialException as exc:
            print(f"UART communication error: {exc}", file=sys.stderr)
            return None

    def test_connection(self):
        response = self._send_command(b'AT', wait_for=ESP_OK)
        return response is not None and ESP_OK in response

    def restart(self):
        response = self._send_command(b'AT+RST', wait_for=ESP_READY, timeout=2.0)
        return response is not None and ESP_READY in response

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command, wait_for=ESP_OK, timeout=10.0)
        return response is not None and ESP_OK in response

    def disconnect_wifi(self):
        response = self._send_command(b'AT+CWQAP')
        return response is not None and ESP_OK in response

    def get_ip(self):
        response = self._send_command(b'AT+CIFSR')
        if response is None or ESP_FAIL in response:
            return None
        try:
            ip_data = response.split(b'+IPD,')[1]
            if len(ip_data) < 3:
                return None
            ip_addr = ip_data[1].decode('utf-8', errors='ignore').strip()
            return ip_addr
        except Exception:
            return None

    def send_http_request(self, method, url, host=None, port=80, headers=None, data=None):
        if not host:
            host = '192.168.0.1'
        command = f'AT+CIPSTART="TCP","{host}",{port}'
        response = self._send_command(command, wait_for=ESP_OK, timeout=5.0)
        if response is None or ESP_FAIL in response:
            return None
        try:
            self._uart.write(b'GET ' + (headers or '') + '\r\n')
            self._uart.write(f'{url}\r\n'.encode('utf-8'))
            self._uart.write(b'\r\n')
            self._uart.write(b'Host: {host}\r\n')
            if data:
                self._uart.write(data)
            self._uart.write(b'\r\n')
            response = self._send_command(b'AT+CIPSEND', wait_for=ESP_OK, timeout=5.0)
            if response is None or ESP_FAIL in response:
                return None
            start_time = time.monotonic()
            buffer = b''
            while time.monotonic() - start_time < 10.0:
                if self._uart.in_waiting > 0:
                    chunk = self._uart.read(self._uart.in_waiting)
                    if chunk:
                        buffer += chunk
                        if b'CLOSED' in buffer:
                            break
                else:
                    time.sleep(0.01)
            return buffer
        except serial.SerialException as exc:
            print(f"Error sending HTTP request: {exc}", file=sys.stderr)
            return None

    def receive_http_response(self, timeout=5.0):
        response = self._send_command(b'AT+CIPSEND', wait_for=ESP_OK, timeout=5.0)
        if response is None or ESP_FAIL in response:
            return None
        start_time = time.monotonic()
        buffer = b''
        while time.monotonic() - start_time < timeout:
            if self._uart.in_waiting > 0:
                chunk = self._uart.read(self._uart.in_waiting)
                if chunk:
                    buffer += chunk
                    if b'+IPD,' in buffer:
                        try:
                            ipd_index, colon_index = buffer.index(b'+IPD,') + 3, buffer.index(b':', colon_index)
                            payload = buffer[colon_index + 2:]
                            return payload
                        except ValueError:
                            pass
            else:
                time.sleep(0.01)
        return None

    def close(self):
        if self._uart is not None:
            try:
                if self._uart.is_open:
                    self._uart.close()
            except Exception:
                pass
            self._uart = None


def _signal_handler(signum, frame):
    print("\nExiting program...")
    if 'esp' in globals() and esp is not None:
        esp.close()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    esp = None
    try:
        esp = ESP8266()
        if esp.test_connection():
            print("ESP8266 is responding.")
            if esp.restart():
                print("ESP8266 restarted.")
                if esp.connect_wifi('ssid', 'password'):
                    print("Connected to WiFi.")
                    ip = esp.get_ip()
                    if ip:
                        print(f"IP Address: {ip}")
                    else:
                        print("Could not get IP address.")
                else:
                    print("Failed to connect to WiFi.")
            else:
                print("ESP8266 did not respond to restart.")
        else:
            print("ESP8266 is not responding.")
    finally:
        if esp is not None:
            esp.close()

