import serial
import time
import signal
import sys

import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
POLL_INTERVAL = 1.0
RADIATION_THRESHOLD = 50.0
ALERT_PIN = 18

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_radiation_level(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS read error: {e}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        return float(raw.decode('ascii', errors='replace'))
    except ValueError:
        print("Invalid data received from sensor (not a float).", file=sys.stderr)
        return None

def control_alert(alert_pin, radiation_level, threshold):
    if radiation_level is None:
        return
    if radiation_level > threshold:
        GPIO.output(alert_pin, GPIO.HIGH)
        print(f"Radiation level: {radiation_level:.2f} µSv/h - Alert triggered (GPIO18 HIGH)")
    else:
        GPIO.output(alert_pin, GPIO.LOW)
        print(f"Radiation level: {radiation_level:.2f} µSv/h - Alert cleared (GPIO18 LOW)")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setwarnings(False)
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if ser is None:
        GPIO.cleanup()
        sys.exit(1)

    try:
        while _running:
            radiation = read_radiation_level(ser)
            if radiation is not None:
                control_alert(ALERT_PIN, radiation, RADIATION_THRESHOLD)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        GPIO.cleanup()
        print("Resources released. Exiting.")

if __name__ == '__main__':
    main()

