import serial
import time
import pynmea2
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        return None

def read_gps_data(serial_port):
    """Reads and parses NMEA data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if not line:
            return None
        return line
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading GPS data: {e}", file=sys.stderr)
        return None

def parse_gps_data(gps_data):
    """Parses the NMEA sentence and extracts latitude, longitude, and altitude."""
    try:
        msg = pynmea2.parse(gps_data)
        # Check if the fix is valid (quality indicator '1')
        if msg.gps_qual == '1':
            latitude = msg.latitude
            longitude = msg.longitude
            altitude = msg.altitude
            return latitude, longitude, altitude
        else:
            return None, None, None
    except pynmea2.ParseError as e:
        print(f"NMEA parse error: {e}", file=sys.stderr)
        return None, None, None
    except Exception as e:
        print(f"Unexpected error parsing GPS data: {e}", file=sys.stderr)
        return None, None, None

def log_coordinates(log_file, latitude, longitude, altitude):
    """Logs the coordinates to a file with an ISO 8601 timestamp."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f"{timestamp}, Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}\n"
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error logging coordinates: {e}", file=sys.stderr)

def main():
    """Main function to read and log GPS data."""
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            gps_data = read_gps_data(serial_connection)
            if gps_data:
                latitude, longitude, altitude = parse_gps_data(gps_data)
                if latitude is not None and longitude is not None and altitude is not None:
                    log_coordinates(LOG_FILE, latitude, longitude, altitude)
                    print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}")
            time.sleep(0.1)  # Small delay to prevent busy-waiting
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

