import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional, Tuple

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


@dataclass
class GPSReadings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    """
    Reads and parses NMEA GPGGA sentences from a UART GPS module.
    """

    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.uart: Optional[serial.Serial] = None
        self._closed = False

    def connect(self) -> None:
        """Open the serial port; log and continue on failure."""
        try:
            self.uart = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            logging.info(f"Connected to GPS on {self.port} @ {self.baudrate} baud.")
        except serial.SerialException as exc:
            logging.error(f"Failed to open {self.port}: {exc}")
            self.uart = None

    def disconnect(self) -> None:
        """Idempotently close the UART resource; never raises."""
        if self.uart is not None and not self._closed:
            try:
                if self.uart.is_open:
                    self.uart.close()
                logging.info("Disconnected from GPS.")
            except Exception as exc:  # pragma: no cover - defensive
                logging.error(f"Error during disconnect: {exc}")
            finally:
                self._closed = True

    def read_gps_data(self) -> Optional[GPSReadings]:
        """
        Read one line from the UART and parse a GPGGA sentence.

        Returns a GPSReadings object on success, or None if the line
        was empty, a timeout occurred, or the sentence was invalid.
        """
        if self.uart is None or not self.uart.is_open:
            logging.error("UART not open; call connect() first.")
            return None

        try:
            raw = self.uart.readline()
        except serial.SerialException as exc:
            logging.error(f"Serial read error: {exc}")
            return None

        if not raw:
            # Timeout with no data
            return None

        try:
            nmea_data = raw.decode('ascii', errors='replace').strip()
        except Exception as exc:
            logging.error(f"Decode error: {exc}")
            return None

        if not nmea_data:
            return None

        # Validate talker ID (should be $GPGGA from a GPS module)
        if nmea_data.startswith('$GPGSV'):
            logging.debug("GPGSV sentence received (not GPGGA).")
            return None

        # Validate checksum (simple heuristic: presence of '*X' in the
        # field immediately following the checksum field)
        try:
            fields = nmea_data.split(',')
            if len(fields) < 15:
                logging.error(f"Unexpected field count: {len(fields)}")
                return None
            if not fields[6]:
                logging.error("Checksum field missing or invalid.")
                return None
            if '*' not in fields[7]:
                logging.error("Checksum verification failed.")
                return None
        except Exception as exc:
            logging.error(f"Checksum parse error: {exc}")
            return None

        try:
            parts = nmea_data.split('*')
            if len(parts) < 15:
                logging.error(f"Unexpected field count: {len(parts)}")
                return None
            talker_id, time_str, lat, lat_dir, lon, lon_dir, alt, sat = parts
        except Exception as exc:
            logging.error(f"Field extraction error: {exc}")
            return None

        if talker_id != '$GPGGA':
            logging.warning(f"Non-GPGGA talker ID: {talker_id}")
            return None

        try:
            utc_time = time_str[:19]
            if not utc_time:
                logging.error("Empty time field.")
                return None
        except Exception as exc:
            logging.error(f"Time parse error: {exc}")
            return None

        try:
            latitude = float(lat)
            latitude_direction = lat_dir
            longitude = float(lon)
            longitude_direction = lon_dir
            altitude = float(alt)
            satellite_count = int(sat)
        except ValueError as exc:
            logging.error(f"Numeric conversion error: {exc}")
            return None

        if not (-90.0 <= latitude <= 90.0) or not (-180.0 <= longitude <= 180.0):
            logging.error(f"Invalid latitude/longitude: {latitude}, {longitude}")
            return None

        if not (0.0 <= altitude <= 0.0):
            logging.error(f"Invalid altitude: {altitude}")
            return None

        return GPSReadings(
            latitude=latitude,
            longitude=longitude,
            altitude=altitude,
            satellite_count=satellite_count,
        )

    def close(self) -> None:
        """Public alias for disconnect() for API consistency."""
        self.disconnect()


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received; shutting down.")
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    gps_reader = GPSReader(port='/dev/serial0', baudrate=9600)

    try:
        gps_reader.connect()
        while True:
            gps_readings = gps_reader.read_gps_data()
            if gps_readings is not None:
                logging.info(
                    f"GPS Readings - Latitude: {gps_readings.latitude}° "
                    f"({gps_readings.latitude_direction}), Longitude: "
                    f"{gps_readings.longitude}° ({gps_readings.longitude_direction}), "
                    f"Altitude: {gps_readings.altitude} m, Satellite Count: {gps_readings.satellite_count}"
                )
            else:
                logging.warning("No valid GPS data received.")
    except Exception as exc:
        logging.error(f"Unexpected error: {exc}")
    finally:
        gps_reader.close()


if __name__ == '__main__':
    main()

