import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
READ_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
        )
        if not ser.is_open:
            ser.open()
        print(f"Serial port {port} opened at {baud} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None
    except OSError as e:
        print(f"OS error opening serial port {port}: {e}")
        return None

def read_pulse_oximeter_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None
    except OSError as e:
        print(f"OS error reading from serial port: {e}")
        return None

def process_pulse_oximeter_data(data):
    if not data:
        return None, None
    try:
        parts = data.split(',')
        if len(parts) != 2:
            raise ValueError(f"Expected 2 fields, got {len(parts)}: '{data}'")
        heart_rate, spo2 = parts
        return heart_rate, spo2
    except ValueError as e:
        print(f"Error processing data: {e}")
        return None, None

def display_pulse_oximeter_data(heart_rate, spo2):
    if heart_rate is not None and spo2 is not None:
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        sys.exit(1)

    try:
        while _running:
            pulse_oximeter_data = read_pulse_oximeter_data(serial_connection)
            if pulse_oximeter_data is not None:
                heart_rate, spo2 = process_pulse_oximeter_data(pulse_oximeter_data)
                if heart_rate is not None and spo2 is not None:
                    display_pulse_oximeter_data(heart_rate, spo2)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

