import sys
import time
import bluetooth

BLUETOOTH_DEVICE_ID = "XX:XX:XX:XX:XX:XX"
RFCOMM_PORT = 4
BAUD_RATE = 38400
TRANSMISSION_DELAY = 0.1


def send_command(command: str) -> None:
    """Send a command prefixed with 'X' and followed by a newline over RFCOMM."""
    full_command = f"X{command}\n"
    try:
        bluetooth.write(f/dev/rfcomm{RFCOMM_PORT}, full_command)
